SETTINGS_FILE_NAME = "amirs_settings.json"
FEES_FILE_NAME = "amirs_fees.json"


def _settings_path() -> str:
    """Файл настроек — рядом с программой (в папке EXE или скрипта)."""
    try:
        if getattr(sys, "frozen", False):
            base = os.path.dirname(os.path.abspath(sys.executable))
        else:
            base = os.path.dirname(os.path.abspath(sys.argv[0]))
    except Exception:
        base = ""
    return os.path.join(base or os.getcwd(), SETTINGS_FILE_NAME)


def load_app_settings() -> Dict[str, object]:
    """Читает сохранённые реквизиты (участок, судья, код); без файла — пусто."""
    try:
        with open(_settings_path(), "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def save_app_settings(payload: Dict[str, object]) -> None:
    """Сохраняет реквизиты участка, чтобы не вводить их каждый раз."""
    try:
        with open(_settings_path(), "w", encoding="utf-8") as fh:
            json.dump(payload, fh, ensure_ascii=False, indent=2)
    except OSError:
        pass


def komi_section_count() -> int:
    """Общее число участков в справочнике (контроль: 60)."""
    return len(KOMI_SECTION_NAMES)


def komi_district_of(section_name: str) -> Optional[str]:
    """Судебный район по наименованию участка (None, если не найдено)."""
    want = komi_normalize_section(section_name)
    for district, sites in KOMI_JUDICIAL_DISTRICTS:
        for name in sites:
            if komi_normalize_section(name) == want:
                return district
    return None


def komi_match_section(text: str) -> Optional[str]:
    """Находит в справочнике участок по неточному написанию.

    Сравнение — без учёта регистра, пробелов и суффикса «Республики Коми».
    Возвращает каноническое наименование либо None.
    """
    want = komi_normalize_section(text)
    if not want:
        return None
    for name in KOMI_SECTION_NAMES:
        if komi_normalize_section(name) == want:
            return name
    return None


def komi_normalize_section(text: str) -> str:
    """Нормализует наименование участка для сравнения."""
    s = re.sub(r"\s+", " ", str(text or "")).strip().lower()
    s = re.sub(r",?\s*республики коми\s*$", "", s)
    return s


def _genitive_word(word: str) -> str:
    """Родительный падеж для прилагательного-слова наименования участка."""
    for suf, rep in (("ский", "ского"), ("цкий", "цкого"),
                     ("ый", "ого"), ("ой", "ого"), ("ая", "ой")):
        if word.lower().endswith(suf):
            return word[:-len(suf)] + rep
    return word


def section_genitive(name: str) -> str:
    """«Димитровский судебный участок г. Сыктывкара» ->
    «Димитровского судебного участка г. Сыктывкара».

    Склоняются слова до «участок» включительно; «г. Сыктывкара» и другие
    уже родительные формы после слова «участок» не меняются.
    """
    words = re.sub(r"\s+", " ", str(name or "")).strip().split(" ")
    words = [w for w in words if w]
    out: List[str] = []
    for word in words:
        if word.lower() == "участок":
            out.append("участка")
            break
        out.append(_genitive_word(word))
    rest = words[len(out):]
    return " ".join(out + rest).strip()


class ConversionError(Exception):
    """Понятная пользователю ошибка конвертации (без стека)."""


@dataclass
class RegistryResult:
    """Итог обработки реестра."""
    success_count: int = 0
    total_rows: int = 0
    skipped_empty: int = 0
    rejected: List[Dict[str, str]] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    warning_count: int = 0
    warnings_log_path: str = ""
    duplicate_count: int = 0
    xml_path: str = ""
    log_path: str = ""
    journal_path: str = ""
    records: List[Dict[str, str]] = field(default_factory=list)


@dataclass
class BatchEntry:
    """Итог обработки одного файла в пакетном режиме."""
    path: str
    status: str  # "ok" | "error" | "crash"
    message: str = ""
    result: Optional[RegistryResult] = None


@dataclass
class BatchResult:
    """Итог пакетной обработки нескольких реестров."""
    entries: List[BatchEntry] = field(default_factory=list)
    ok_count: int = 0
    fail_count: int = 0
    total_accepted: int = 0
    total_rejected: int = 0
    duration_sec: float = 0.0


# ---------------------------------------------------------------------------
# Нормализация значений
# ---------------------------------------------------------------------------

def normalize_header(name) -> str:
    """Приводит название столбца к сравнимому виду."""
    return re.sub(r"\s+", " ", str(name or "")).strip().strip(":").lower()


def clean_placeholder(value) -> str:
    """Заменяет заглушки («*», «-», «нет» и т.п.) на пустое значение."""
    text = str(value or "").strip()
    return "" if text.lower() in PLACEHOLDERS else text


def only_digits(value) -> str:
    return re.sub(r"\D", "", str(value or ""))


def xml_safe(value) -> str:
    """Убирает символы, недопустимые в XML, и лишние пробелы/переводы строк."""
    text = XML_ILLEGAL.sub("", str(value or ""))
    return re.sub(r"\s+", " ", text).strip()


AMOUNT_PLAUSIBILITY_LIMIT = Decimal("10000000")   # 10 млн руб. — порог предупреждения
AMOUNT_MAX_HARD = Decimal("1000000000")           # 1 млрд руб. — жёсткий порог правдоподобия


def parse_amount_detailed(raw) -> Tuple[Optional[str], str]:
    """Разбирает денежную сумму -> (нормализованная_строка | None, предупреждение).

    Поддерживает российский («1 234,56»), американский («1,234.56») и
    смешанный («1.234,56») форматы, очищает суффиксы валюты («руб.», «р.»),
    определяет десятичный разделитель по правому из знаков «,» и «.».
    Неоднозначные случаи («1,234», «1.234») и суммы > 10 млн руб. возвращают
    предупреждение; отрицательные суммы и значения > 1 млрд руб. отклоняются.
    """
    if raw is None or isinstance(raw, bool):
        return None, ""
    raw_str = str(raw).strip()
    if not raw_str:
        return None, ""
    s = re.sub(r"[\s\u00A0\u202F]+", "", raw_str)
    s = re.sub(r"(?:руб(?:л[ейяь]*)?\.?|р\.?|₽)$", "", s, flags=re.IGNORECASE)
    if not s:
        return None, ""
    if s.startswith(("-", "−", "–", "—")):
        return None, ""
    if s.startswith("+"):
        s = s[1:]
    if not s or s.startswith(("+", "-", "−", "–", "—")):
        return None, ""

    warning = ""
    if re.fullmatch(r"\d+(?:[.,]\d+)?[eE][+-]?\d+", s):
        s_norm = s.replace(",", ".")
    else:
        if not re.fullmatch(r"[0-9.,]+", s):
            return None, ""
        if s.startswith((".", ",")) or s.endswith((".", ",")):
            return None, ""
        last_comma = s.rfind(",")
        last_dot = s.rfind(".")
        if last_comma != -1 and last_dot != -1:
            # Оба разделителя: правый — десятичный, левый — разделитель разрядов
            dec_sep = "," if last_comma > last_dot else "."
            thou_sep = "." if dec_sep == "," else ","
            if s.count(dec_sep) > 1:
                return None, ""
            head, _, tail = s.partition(dec_sep)
            if not head or not tail or thou_sep in tail:
                return None, ""
            s_norm = head.replace(thou_sep, "") + "." + tail
        elif last_comma != -1 or last_dot != -1:
            sep = "," if last_comma != -1 else "."
            if s.count(sep) > 1:
                parts = s.split(sep)
                if not (1 <= len(parts[0]) <= 3 and all(len(p) == 3 for p in parts[1:])):
                    return None, ""
                s_norm = "".join(parts)
            else:
                head, _, tail = s.partition(sep)
                if not head or not tail:
                    return None, ""
                if len(tail) == 3 and 1 <= len(head) <= 3 and head != "0":
                    warning = (
                        f"неоднозначный формат суммы «{raw_str}» (3 цифры после разделителя "
                        f"«{sep}» — проверьте, не является ли он разделителем тысяч)"
                    )
                s_norm = head + "." + tail
        else:
            s_norm = s

    try:
        value = Decimal(s_norm)
    except InvalidOperation:
        return None, ""
    if not value.is_finite() or value < 0:
        return None, ""
    if value > AMOUNT_MAX_HARD:
        return None, (
            f"сумма «{raw_str}» превышает порог правдоподобия 1 000 000 000 руб. "
            "(возможен сдвиг столбцов или попадание номера счёта)"
        )
    formatted = str(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    if value > AMOUNT_PLAUSIBILITY_LIMIT and not warning:
        warning = (
            f"аномально крупная сумма «{raw_str}» ({formatted} руб. > 10 000 000 руб.) "
            "— проверьте разрядность и отсутствие сдвига столбцов"
        )
    return formatted, warning


def parse_amount(raw) -> Optional[str]:
    """«1 234,56 руб» -> «1234.56». Возвращает None, если это не число или сумма некорректна."""
    amount, _warning = parse_amount_detailed(raw)
    return amount


def parse_date_value(raw) -> Optional[str]:
    """Приводит дату к виду ДД.ММ.ГГГГ. Понимает серийные даты Excel."""
    s = str(raw or "").strip()
    if not s:
        return None
    today = date.today()
    if re.fullmatch(r"\d+(\.\d+)?", s):
        # Excel хранит даты как число дней от 30.12.1899 (дробная часть — время суток)
        try:
            serial = int(Decimal(s))
        except (InvalidOperation, ValueError, OverflowError):
            return None
        if 10000 <= serial <= 80000:
            d = date(1899, 12, 30) + timedelta(days=serial)
            if 1900 <= d.year <= today.year + 1:
                return d.strftime("%d.%m.%Y")
        return None
    for fmt in ("%d.%m.%Y", "%d/%m/%Y", "%Y-%m-%d", "%d.%m.%y"):
        try:
            dt = datetime.strptime(s, fmt).date()
            if fmt == "%d.%m.%y" and dt > today:
                dt = dt.replace(year=dt.year - 100)
            if 1900 <= dt.year <= today.year + 1:
                return dt.strftime("%d.%m.%Y")
        except ValueError:
            continue
    return None


def clean_account_number(raw) -> str:
    """Чистит номер лицевого счета: префикс «Л/С», пробелы, научная запись."""
    s = re.sub(r"[\s\u00A0\u202F]", "", str(raw or ""))
    if not s:
        return ""
    s = re.sub(r"^(?:Л/?С|№)", "", s, flags=re.IGNORECASE)
    if not s:
        return ""
    try:
        value = Decimal(s.replace(",", "."))
    except InvalidOperation:
        return s
    if not value.is_finite():
        return s
    if value == value.to_integral_value():
        return str(int(value))
    return format(value.normalize(), "f")


# ---------------------------------------------------------------------------
# Проверка идентификаторов (ст. 124 ГПК РФ)
# ---------------------------------------------------------------------------

def _snils_control_ok(digits: str) -> bool:
    total = sum(int(d) * i for d, i in zip(reversed(digits[:9]), range(1, 10)))
    if total < 100:
        control = total
    else:
        control = total % 101
        if control == 100:
            control = 0
    return f"{control:02d}" == digits[9:]


def _inn_checksum(digits: str, weights) -> int:
    return sum(int(d) * w for d, w in zip(digits, weights)) % 11 % 10


def _inn_control_ok(digits: str) -> bool:
    if _inn_checksum(digits[:10], (7, 2, 4, 10, 3, 5, 9, 4, 6, 8)) != int(digits[10]):
        return False
    return _inn_checksum(digits[:11], (3, 7, 2, 4, 10, 3, 5, 9, 4, 6, 8)) == int(digits[11])


def check_snils(raw):
    """СНИЛС из 11 цифр -> (значение «123-456-789 01», предупреждение).

    Если цифр не 11 — ("", ""): номер непригоден ни в каком режиме.
    Если контрольное число не совпало — номер возвращается вместе с
    предупреждением: в мягком режиме он включается в пакет.
    """
    digits = only_digits(raw)
    if len(digits) != 11 or int(digits) == 0:
        return "", ""
    formatted = f"{digits[:3]}-{digits[3:6]}-{digits[6:9]} {digits[9:]}"
    if not _snils_control_ok(digits):
        return formatted, f"СНИЛС {formatted} не проходит контрольное число"
    return formatted, ""


def check_inn(raw):
    """ИНН из 12 цифр -> (значение, предупреждение). Логика как у СНИЛС."""
    digits = only_digits(raw)
    if len(digits) != 12 or int(digits) == 0:
        return "", ""
    if not _inn_control_ok(digits):
        return digits, f"ИНН {digits} не проходит контрольное число"
    return digits, ""


def validate_snils(raw) -> Optional[str]:
    """Строгая проверка СНИЛС (совместимость/тесты): значение либо None."""
    value, warning = check_snils(raw)
    return value if value and not warning else None


def validate_inn(raw) -> Optional[str]:
    """Строгая проверка ИНН (совместимость/тесты): значение либо None."""
    value, warning = check_inn(raw)
    return value if value and not warning else None


def validate_passport(raw) -> Optional[str]:
    """Серия и номер паспорта РФ: ровно 10 цифр -> «1234 567890» либо None."""
    digits = only_digits(raw)
    if len(digits) != 10:
        return None
    return f"{digits[:4]} {digits[4:]}"


# ---------------------------------------------------------------------------
# Генерация эталонного шаблона реестра (xlsx, без сторонних библиотек)
# ---------------------------------------------------------------------------

def _tpl_col_letter(index: int) -> str:
    """1 -> A, 13 -> M."""
    letters = ""
    while index > 0:
        index, rem = divmod(index - 1, 26)
        letters = chr(65 + rem) + letters
    return letters


def _tpl_escape(text) -> str:
    return (str(text or "")
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;"))


def _tpl_worksheet(rows, col_widths=None, freeze_rows: int = 0) -> bytes:
    """Собирает XML одного листа. rows — список строк из ячеек (стиль, текст)."""
    parts = [
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
        f'<worksheet xmlns="{NS[1:-1]}">',
    ]
    if freeze_rows > 0:
        parts.append(
            '<sheetViews><sheetView tabSelected="1" workbookViewId="0">'
            f'<pane ySplit="{freeze_rows}" topLeftCell="A{freeze_rows + 1}"'
            ' activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>'
        )
    else:
        parts.append('<sheetViews><sheetView workbookViewId="0"/></sheetViews>')
    if col_widths:
        cols = "".join(
            f'<col min="{i}" max="{i}" width="{w}" customWidth="1"/>'
            for i, w in enumerate(col_widths, start=1)
        )
        parts.append(f"<cols>{cols}</cols>")
    parts.append("<sheetData>")
    for r_idx, row in enumerate(rows, start=1):
        parts.append(f'<row r="{r_idx}">')
        for c_idx, cell in enumerate(row, start=1):
            if not cell:
                continue
            style, text = cell
            ref = f"{_tpl_col_letter(c_idx)}{r_idx}"
            if text:
                parts.append(
                    f'<c r="{ref}" s="{style}" t="inlineStr"><is>'
                    f'<t xml:space="preserve">{_tpl_escape(text)}</t></is></c>'
                )
            else:
                parts.append(f'<c r="{ref}" s="{style}"/>')
        parts.append("</row>")
    parts.append("</sheetData></worksheet>")
    return "".join(parts).encode("utf-8")


