def make_template(target_path: str) -> str:
    """Создаёт эталонный шаблон реестра: лист «Реестр» + лист «Инструкция».

    Строка-пример намеренно не содержит ни одного идентификатора должника —
    конвертер гарантированно отвергнет её, если сотрудник забудет её удалить.
    Бросает ConversionError, если файл невозможно записать.
    """
    if not target_path:
        raise ConversionError("Не указано имя файла шаблона.")
    if not target_path.lower().endswith(".xlsx"):
        target_path += ".xlsx"

    # -- лист «Реестр» -------------------------------------------------------
    title = ("ЭТАЛОННЫЙ РЕЕСТР ДОЛЖНИКОВ ДЛЯ КОНВЕРТЕРА АМИРС — "
             "удалите строку-пример (строка 3) и заполняйте таблицу ниже")
