def classify_document_text(text: str) -> Tuple[str, str]:
    """Определяет тип документа по характерным фразам.

    Возвращает (канонический_тип, уточнение). Порядок проверок = приоритет:
    специфичные формулировки раньше общих (расчёт раньше договора — в тексте
    договора тоже встречается слово «расчёт», платёжка раньше договора —
    в назначении платежа указан договор).
    """
    s = " ".join(str(text or "").lower().replace("ё", "е").split())
    if not s:
        return DOC_KIND_OTHER, ""

    def has(*patterns: str) -> bool:
        return any(re.search(p, s) for p in patterns)

    if has(r"о\s+вынесении\s+судебного\s+приказа"):
        return DOC_KIND_ZAYAVLENIE, ""
    pay_doc = has(r"плат[её]жное\s+поручение", r"банковская\s+квитанция",
                  r"квитанция\s+(?:№|об\s+оплате)")
    if pay_doc and has(r"госпошлин", r"государственн\w*\s+пошлин"):
        return DOC_KIND_DUTY, ""
    if has(r"судебный\s+приказ", r"решени[ея]\s+суда", r"определение\s+суда",
           r"исполнительный\s+лист"):
        return DOC_KIND_SUDAKT, ""
    if has(r"соглашение\s+об\s+уплате\s+алиментов"):
        return DOC_KIND_SOGLASH, ""
    if has(r"требование\s+об\s+уплате") and has(r"налог", r"страховым?\s+взнос",
                                                r"пени", r"штраф"):
        return DOC_KIND_NALOG, ""
    if has(r"расч[её]т\s+задолженности", r"расч[её]т\s+начислен",
           r"расч[её]т\s+суммы", r"сведения\s+о\s+начислениях",
           r"расшифровка\s+задолженности", r"задолженность\s+за\s+период",
           r"расч[её]т\s+пени", r"плат[её]жное\s+извещение",
           r"детализация\s+начислений", r"задолженность\s+по\s+оплате",
           r"расч[её]тн\w*\s+листок", r"справк\w*\s+о\s+начислен\w*",
           r"справк\w*\s+о\s+задолженности"):
        return DOC_KIND_RASCHET, ""
    if has(r"доверенност"):
        return DOC_KIND_TRUST, ""
    if has(r"претензи", r"досудебн\w*\s+порядок"):
        return DOC_KIND_PRETENZ, ""
    if has(r"свидетельство\s+о\s+рождении"):
        return DOC_KIND_BIRTH_CERT, ""
    if has(r"справк\w*\s+о\s+составе\s+семьи", r"совместн\w*\s+проживан",
           r"нахождении\s+на\s+иждивении", r"выписк\w*\s+из\s+домовой\s+книги"):
        return DOC_KIND_FAMILY_CERT, ""
    if has(r"уведомление\s+о\s+вручении", r"почтовая\s+квитанция",
           r"опись\s+вложени", r"кассовый\s+чек.*почта", r"\bрпо\b", r"трек-номер"):
        return DOC_KIND_POST, ""
    if pay_doc:
        return DOC_KIND_PAY_OTHER, ""
    if has(r"выписк\w*\s+из\s+(?:егрн|единого\s+государственного\s+реестра\s+недвижимости)",
           r"сведения\s+из\s+единого\s+государственного\s+реестра\s+недвижимости",
           r"об\s+основных\s+характеристиках\s+и\s+зарегистрированных\s+правах"):
        return DOC_KIND_EGRN, ""
    if has(r"договор"):
        for sub in _DOC_DOGOVOR_SUBTYPES:
            if sub.lower().replace("ё", "е") in s:
                return DOC_KIND_DOGOVOR, sub
        return DOC_KIND_DOGOVOR, ""
    return DOC_KIND_OTHER, ""


def classify_all_document_kinds(text: str) -> List[str]:
    """Находит все типы документов, встречающиеся в многостраничном скане/файле."""
    s = " ".join(str(text or "").lower().replace("ё", "е").split())
    if not s:
        return []

    def has(*patterns: str) -> bool:
        return any(re.search(p, s) for p in patterns)

    found: List[str] = []
    if has(r"о\s+вынесении\s+судебного\s+приказа"):
        found.append(DOC_KIND_ZAYAVLENIE)
    pay_doc = has(r"плат[её]жное\s+поручение", r"банковская\s+квитанция",
                  r"квитанция\s+(?:№|об\s+оплате)")
    if pay_doc and has(r"госпошлин", r"государственн\w*\s+пошлин"):
        found.append(DOC_KIND_DUTY)
    if has(r"судебный\s+приказ", r"решени[ея]\s+суда", r"определение\s+суда",
           r"исполнительный\s+лист"):
        found.append(DOC_KIND_SUDAKT)
    if has(r"соглашение\s+об\s+уплате\s+алиментов"):
        found.append(DOC_KIND_SOGLASH)
    if has(r"требование\s+об\s+уплате") and has(r"налог", r"страховым?\s+взнос",
                                                r"пени", r"штраф"):
        found.append(DOC_KIND_NALOG)
    if has(r"расч[её]т\s+задолженности", r"расч[её]т\s+начислен",
           r"расч[её]т\s+суммы", r"сведения\s+о\s+начислениях",
           r"расшифровка\s+задолженности", r"задолженность\s+за\s+период",
           r"расч[её]т\s+пени", r"плат[её]жное\s+извещение",
           r"детализация\s+начислений", r"задолженность\s+по\s+оплате",
           r"расч[её]тн\w*\s+листок", r"справк\w*\s+о\s+начислен\w*",
           r"справк\w*\s+о\s+задолженности"):
        found.append(DOC_KIND_RASCHET)
    if has(r"доверенност"):
        found.append(DOC_KIND_TRUST)
    if has(r"претензи", r"досудебн\w*\s+порядок"):
        found.append(DOC_KIND_PRETENZ)
    if has(r"свидетельство\s+о\s+рождении"):
        found.append(DOC_KIND_BIRTH_CERT)
    if has(r"справк\w*\s+о\s+составе\s+семьи", r"совместн\w*\s+проживан",
           r"нахождении\s+на\s+иждивении", r"выписк\w*\s+из\s+домовой\s+книги"):
        found.append(DOC_KIND_FAMILY_CERT)
    if has(r"уведомление\s+о\s+вручении", r"почтовая\s+квитанция",
           r"опись\s+вложени", r"кассовый\s+чек.*почта", r"\bрпо\b", r"трек-номер"):
        found.append(DOC_KIND_POST)
    if pay_doc and DOC_KIND_DUTY not in found:
        found.append(DOC_KIND_PAY_OTHER)
    if has(r"выписк\w*\s+из\s+(?:егрн|единого\s+государственного\s+реестра\s+недвижимости)",
           r"сведения\s+из\s+единого\s+государственного\s+реестра\s+недвижимости",
           r"об\s+основных\s+характеристиках\s+и\s+зарегистрированных\s+правах"):
        found.append(DOC_KIND_EGRN)
    if has(r"договор"):
        found.append(DOC_KIND_DOGOVOR)
    return found


# -- извлечение текста из файлов ----------------------------------------------

def _pdf_decode_literal(raw: bytes) -> str:
    try:
        return raw.decode("cp1251")
    except UnicodeDecodeError:
        return raw.decode("latin-1", "ignore")


def _pdf_tounicode_map(buf: bytes) -> Dict[int, str]:
    """Разбирает блок bfchar/bfrange из ToUnicode CMap -> {код: строка}."""
    cmap: Dict[int, str] = {}

    def _hex_str(hex_bytes: bytes) -> str:
        try:
            return bytes.fromhex(hex_bytes.decode("ascii")).decode("utf-16-be", "ignore")
        except (ValueError, UnicodeDecodeError):
            return ""

    for m in re.finditer(rb"beginbfchar(.*?)endbfchar", buf, re.S):
        for pm in re.finditer(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", m.group(1)):
            try:
                src = int(pm.group(1), 16)
            except ValueError:
                continue
            dst = _hex_str(pm.group(2))
            if dst:
                cmap[src] = dst
    for m in re.finditer(rb"beginbfrange(.*?)endbfrange", buf, re.S):
        for pm in re.finditer(
                rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>",
                m.group(1)):
            try:
                lo, hi = int(pm.group(1), 16), int(pm.group(2), 16)
            except ValueError:
                continue
            base = _hex_str(pm.group(3))
            if not base or len(base) != 1 or hi < lo or hi - lo > 65535:
                continue
            for code in range(lo, hi + 1):
                cmap[code] = chr(ord(base) + code - lo)
    return cmap


def _pdf_extract_text(path: str) -> Tuple[str, str, str]:
    """Текст из простых PDF (распечатки 1С/биллинга): потоки zlib, строки Tj/TJ,
    шестнадцатеричные строки через ToUnicode. Встроенный парсер без библиотек;
    если текста нет — файл, скорее всего, скан."""
    try:
        with open(path, "rb") as fh:
            data = fh.read(20 * 1024 * 1024)
    except OSError as exc:
        return "", f"файл не читается ({exc})", "fail"
    if not data.lstrip()[:5].startswith(b"%PDF"):
        return "", "это не PDF-файл", "fail"

    streams: List[bytes] = []
    for m in re.finditer(rb"stream\r?\n(.*?)endstream", data, re.S):
        raw = m.group(1)
        try:
            raw = zlib.decompress(raw)
        except zlib.error:
            pass
        streams.append(raw)

    cmap_total: Dict[int, str] = {}
    for buf in streams:
        if b"beginbfchar" in buf or b"beginbfrange" in buf:
            cmap_total.update(_pdf_tounicode_map(buf))

    parts: List[str] = []
    for buf in streams:
        if b"BT" not in buf or (b"Tj" not in buf and b"TJ" not in buf):
            continue  # не поток содержимого страницы (шрифты, метаданные)
        for sm in re.finditer(rb"\(((?:\\.|[^\\()])*)\)", buf):
            parts.append(_pdf_decode_literal(sm.group(1)))
        if cmap_total:
            for hm in re.finditer(rb"<([0-9A-Fa-f\s]+)>", buf):
                hexes = re.sub(rb"\s", b"", hm.group(1))
                out = []
                for i in range(0, len(hexes) - 1, 2):
                    try:
                        out.append(cmap_total.get(int(hexes[i:i + 2], 16), ""))
                    except ValueError:
                        continue
                if out:
                    parts.append("".join(out))
    text = re.sub(r"\s+", " ", " ".join(parts)).strip()
    if len(text) < 20:
        return "", "PDF без текстового слоя — проверить визуально", "scan"
    return text, "", "text"


def _pypdf_extract_text(path: str) -> str:
    """Резервное извлечение через pypdf (если установлен). Тише некуда: любая
    ошибка — пустая строка, встроенный парсер остаётся основным."""
    try:
        from pypdf import PdfReader
    except Exception:
        return ""
    try:
        reader = PdfReader(path)
        chunks = []
        for page in reader.pages[:50]:
            try:
                chunks.append(page.extract_text() or "")
            except Exception:
                chunks.append("")
        return re.sub(r"\s+", " ", " ".join(chunks)).strip()
    except Exception:
        return ""


_W_NS = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"


_PADDLE_OCR_INSTANCE = None
_PADDLE_OCR_CFG_USED = None
_PADDLE_LOCK = threading.Lock()
_MAX_CACHE_ENTRIES = 64
_DOC_TEXT_CACHE: Dict[Tuple[str, int, int, str], Tuple[str, str, str]] = {}


def _cache_put(cache_dict: dict, key, value) -> None:
    """Ограничивает размер кэша распознанных документов в ОЗУ (защита памяти и ПДн)."""
    if key in cache_dict:
        cache_dict.pop(key, None)
    elif len(cache_dict) >= _MAX_CACHE_ENTRIES:
        try:
            oldest = next(iter(cache_dict))
            cache_dict.pop(oldest, None)
        except StopIteration:
            pass
    cache_dict[key] = value


def _docx_extract_text(path: str, tesseract_cfg: str = "") -> Tuple[str, str, str]:
    """Текст из DOCX штатными средствами (zip + xml) + OCR вложенных картинок-сканов через PaddleOCR."""
    media_files: List[Tuple[str, bytes]] = []
    try:
        with zipfile.ZipFile(path, "r") as z:
            names = z.namelist()
            if "word/document.xml" not in names:
                return "", "это не документ Word (.docx)", "fail"
            root = ET.fromstring(z.read("word/document.xml"))
            for mname in sorted(names):
                if mname.startswith("word/media/"):
                    ext = os.path.splitext(mname)[1].lower()
                    if ext in _IMAGE_EXTS and len(media_files) < 5:
                        try:
                            media_files.append((ext, z.read(mname)))
                        except Exception as exc:
                            app_log(f"DOCX media read skip ({mname}): {type(exc).__name__}: {exc}")
    except (zipfile.BadZipFile, ET.ParseError) as exc:
        return "", f"файл повреждён ({type(exc).__name__})", "fail"
    except OSError as exc:
        return "", f"файл не читается ({exc})", "fail"
    parts = []
    for p in root.iter(_W_NS + "p"):
        line = " ".join(t.text or "" for t in p.iter(_W_NS + "t")).strip()
        if line:
            parts.append(line)
    text = " ".join(parts).strip()
    if len(text) >= 20 or not media_files:
        return text, "", "text"
    # Если в DOCX вставлены отсканированные страницы-картинки без текста:
    tess_exe = _find_paddle_ocr(tesseract_cfg)
    if not tess_exe:
        return text, "DOCX содержит скан-картинки (PaddleOCR не найден)", "scan"
    ocr_chunks: List[str] = []
    for ext, raw_img in media_files:
        fd, tmp_img = tempfile.mkstemp(suffix=ext, prefix="amirs_docxocr_")
        os.close(fd)
        try:
            with open(tmp_img, "wb") as fh:
                fh.write(raw_img)
            otext, _onote = _ocr_image_text(tmp_img, tess_exe)
            if otext:
                ocr_chunks.append(otext)
        except OSError:
            pass
        finally:
            try:
                os.remove(tmp_img)
            except OSError:
                pass
    if ocr_chunks:
        combined = (text + " " + " ".join(ocr_chunks)).strip()
        return re.sub(r"\s+", " ", combined), "OCR (скан в DOCX)", "image"
    return text, "DOCX со сканами без распознанного текста", "scan"


def _discover_model_subdirs(root_dir: str) -> Dict[str, str]:
    """Рекурсивно ищет папки моделей det, rec, cls внутри paddle_models или кэша (.paddleocr/.paddlex)."""
    found: Dict[str, str] = {}
    if not root_dir or not os.path.isdir(root_dir):
        return found
    for direct in ("det", "rec", "cls"):
        cand = os.path.join(root_dir, direct)
        if os.path.isdir(cand):
            found[direct] = cand
    if len(found) == 3:
        return found
    try:
        for cur_root, _dirs, files in os.walk(root_dir):
            fset = set(files)
            if not any(f.endswith((".pdmodel", ".pdiparams", ".json", ".yml")) for f in fset):
                continue
            low_path = cur_root.replace("\\", "/").lower()
            if "det" not in found and ("/det/" in low_path or low_path.endswith("/det") or "det" in os.path.basename(cur_root).lower()):
                found["det"] = cur_root
            elif "rec" not in found and ("/rec/" in low_path or low_path.endswith("/rec") or "rec" in os.path.basename(cur_root).lower()):
                found["rec"] = cur_root
            elif "cls" not in found and ("/cls/" in low_path or low_path.endswith("/cls") or "cls" in os.path.basename(cur_root).lower() or "ori" in os.path.basename(cur_root).lower()):
                found["cls"] = cur_root
    except OSError:
        pass
    return found


def _find_paddle_models_dir(configured: str = "") -> str:
    """Находит папку моделей paddle_models для портативного запуска (без интернета)."""
    search_dirs: List[str] = []
    app_dir = _app_data_dir()
    meipass = getattr(sys, "_MEIPASS", "")
    if configured and configured.strip():
        cfg = configured.strip()
        if cfg.startswith("inproc:"):
            cfg = cfg.split(":", 1)[1]
        if cfg and cfg != "auto":
            if not os.path.isabs(cfg):
                search_dirs.append(os.path.join(app_dir, cfg))
            search_dirs.append(cfg)
    for base in (app_dir, meipass):
        if base:
            search_dirs.append(os.path.join(base, "paddle_models"))
            search_dirs.append(os.path.join(base, "_internal", "paddle_models"))
            search_dirs.append(os.path.join(base, "PaddleOCR", "paddle_models"))
            search_dirs.append(os.path.join(base, "PaddleOCR"))
    home = os.path.expanduser("~")
    for cache_sub in (".paddleocr", ".paddlex"):
        cdir = os.path.join(home, cache_sub)
        if os.path.isdir(cdir):
            search_dirs.append(cdir)
    for d in search_dirs:
        if d and os.path.isdir(d):
            return os.path.abspath(d)
    return ""


def _find_paddle_ocr(configured: str = "") -> str:
    """Проверяет наличие движка PaddleOCR (встроенного в Python/EXE) и возвращает маркер готовности."""
    import importlib.util
    try:
        has_paddleocr = importlib.util.find_spec("paddleocr") is not None
    except Exception:
        has_paddleocr = False
    if not has_paddleocr:
        return ""
    models_dir = _find_paddle_models_dir(configured)
    return f"inproc:{models_dir}" if models_dir else "inproc:auto"


_OCR_CACHE: Dict[Tuple[str, int, int], Tuple[str, str]] = {}


def _get_paddle_ocr_instance(ocr_marker: str = ""):
    """Ленивая инициализация синглтона PaddleOCR с поддержкой портативных моделей и кэша."""
    global _PADDLE_OCR_INSTANCE, _PADDLE_OCR_CFG_USED
    if _PADDLE_OCR_INSTANCE is not None and _PADDLE_OCR_CFG_USED == ocr_marker:
        return _PADDLE_OCR_INSTANCE
    os.environ.setdefault("PADDLE_PDX_DISABLE_MODEL_SOURCE_CHECK", "True")
    os.environ.setdefault("FLAGS_allocator_strategy", "auto_growth")
    import inspect
    from paddleocr import PaddleOCR

    models_dir = _find_paddle_models_dir(ocr_marker)
    if models_dir:
        # Направляем кэш PaddleX/PaddleOCR в портативную папку, если там есть .paddlex/.paddleocr
        paddlex_sub = os.path.join(models_dir, ".paddlex")
        if os.path.isdir(paddlex_sub):
            os.environ.setdefault("PADDLE_PDX_CACHE_DIR", paddlex_sub)
        else:
            os.environ.setdefault("PADDLE_PDX_CACHE_DIR", models_dir)

    discovered = _discover_model_subdirs(models_dir)
    det_dir = discovered.get("det", "")
    rec_dir = discovered.get("rec", "")
    cls_dir = discovered.get("cls", "")

    try:
        params = set(inspect.signature(PaddleOCR.__init__).parameters.keys())
    except Exception:
        params = set()

    saved_cfg = load_app_settings()
    ocr_lang = str(saved_cfg.get("ocr_lang") or "ru").strip() or "ru"
    use_angle = bool(saved_cfg.get("ocr_use_angle_cls", True))
    use_gpu = bool(saved_cfg.get("ocr_use_gpu", False))
    use_mkldnn = bool(saved_cfg.get("ocr_enable_mkldnn", True))
    try:
        drop_score = float(saved_cfg.get("ocr_drop_score", 0.5))
    except (TypeError, ValueError):
        drop_score = 0.5
    try:
        det_db_thresh = float(saved_cfg.get("ocr_det_db_thresh", 0.3))
    except (TypeError, ValueError):
        det_db_thresh = 0.3
    try:
        det_db_box_thresh = float(saved_cfg.get("ocr_det_db_box_thresh", 0.6))
    except (TypeError, ValueError):
        det_db_box_thresh = 0.6

    kwargs: Dict[str, object] = {"lang": ocr_lang}
    if "show_log" in params:
        kwargs["show_log"] = False
    if "use_gpu" in params:
        kwargs["use_gpu"] = use_gpu
    if "enable_mkldnn" in params:
        kwargs["enable_mkldnn"] = use_mkldnn
    if "use_angle_cls" in params:
        kwargs["use_angle_cls"] = use_angle
    elif "use_textline_orientation" in params:
        kwargs["use_textline_orientation"] = use_angle
    if "use_doc_orientation_classify" in params:
        kwargs["use_doc_orientation_classify"] = False
    if "use_doc_unwarping" in params:
        kwargs["use_doc_unwarping"] = False
    if "device" in params:
        kwargs["device"] = "gpu" if use_gpu else "cpu"
    if "drop_score" in params:
        kwargs["drop_score"] = drop_score
    elif "text_rec_score_thresh" in params:
        kwargs["text_rec_score_thresh"] = drop_score
    if "det_db_thresh" in params:
        kwargs["det_db_thresh"] = det_db_thresh
    elif "text_det_thresh" in params:
        kwargs["text_det_thresh"] = det_db_thresh
    if "det_db_box_thresh" in params:
        kwargs["det_db_box_thresh"] = det_db_box_thresh
    elif "text_det_box_thresh" in params:
        kwargs["text_det_box_thresh"] = det_db_box_thresh

    if det_dir and os.path.isdir(det_dir):
        if "det_model_dir" in params:
            kwargs["det_model_dir"] = det_dir
        elif "text_detection_model_dir" in params:
            kwargs["text_detection_model_dir"] = det_dir
    if rec_dir and os.path.isdir(rec_dir):
        if "rec_model_dir" in params:
            kwargs["rec_model_dir"] = rec_dir
        elif "text_recognition_model_dir" in params:
            kwargs["text_recognition_model_dir"] = rec_dir
    if cls_dir and os.path.isdir(cls_dir):
        if "cls_model_dir" in params:
            kwargs["cls_model_dir"] = cls_dir
        elif "textline_orientation_model_dir" in params:
            kwargs["textline_orientation_model_dir"] = cls_dir

    try:
        _PADDLE_OCR_INSTANCE = PaddleOCR(**kwargs)
    except Exception as exc:
        if not (det_dir and os.path.isdir(det_dir) and rec_dir and os.path.isdir(rec_dir)):
            raise RuntimeError(
                "Локальные модели PaddleOCR не найдены (сетевая загрузка запрещена политикой ИБ)"
            ) from exc
        fallback_kw: Dict[str, object] = {"lang": ocr_lang}
        if "det_model_dir" in params:
            fallback_kw["det_model_dir"] = det_dir
        elif "text_detection_model_dir" in params:
            fallback_kw["text_detection_model_dir"] = det_dir
        if "rec_model_dir" in params:
            fallback_kw["rec_model_dir"] = rec_dir
        elif "text_recognition_model_dir" in params:
            fallback_kw["text_recognition_model_dir"] = rec_dir
        if cls_dir and os.path.isdir(cls_dir):
            if "cls_model_dir" in params:
                fallback_kw["cls_model_dir"] = cls_dir
            elif "textline_orientation_model_dir" in params:
                fallback_kw["textline_orientation_model_dir"] = cls_dir
        _PADDLE_OCR_INSTANCE = PaddleOCR(**fallback_kw)
    _PADDLE_OCR_CFG_USED = ocr_marker
    return _PADDLE_OCR_INSTANCE


def _extract_paddle_text(result) -> str:
    """Извлекает распознанный текст из структуры ответа PaddleOCR (совместимо с 2.x и 3.x)."""
    if not result:
        return ""
    lines_with_pos: List[Tuple[float, float, str]] = []
    plain_lines: List[str] = []
    for page in result:
        if not page:
            continue
        if isinstance(page, dict) and "rec_texts" in page:
            for t in page.get("rec_texts") or []:
                if t and str(t).strip():
                    plain_lines.append(str(t).strip())
            continue
        rec_texts_attr = getattr(page, "rec_texts", None)
        if rec_texts_attr is not None:
            for t in rec_texts_attr:
                if t and str(t).strip():
                    plain_lines.append(str(t).strip())
            continue
        if isinstance(page, (list, tuple)):
            for item in page:
                if not item or not isinstance(item, (list, tuple)) or len(item) < 2:
                    continue
                box, rec = item[0], item[1]
                txt = ""
                if isinstance(rec, (list, tuple)) and len(rec) >= 1:
                    txt = str(rec[0] or "").strip()
                elif isinstance(rec, str):
                    txt = rec.strip()
                if not txt:
                    continue
                try:
                    y0 = float(box[0][1])
                    x0 = float(box[0][0])
                    lines_with_pos.append((y0, x0, txt))
                except Exception:
                    plain_lines.append(txt)
    if lines_with_pos:
        lines_with_pos.sort(key=lambda it: (round(it[0] / 12.0), it[1]))
        plain_lines = [it[2] for it in lines_with_pos] + plain_lines
    return re.sub(r"\s+", " ", " ".join(plain_lines)).strip()


def _run_paddle_on_input(img_input, tesseract_exe: str) -> Tuple[str, str]:
    """Потокобезопасный вызов PaddleOCR для массива numpy или пути к файлу."""
    if not tesseract_exe:
        return "", "PaddleOCR не установлен (установите пакеты paddlepaddle и paddleocr)"
    try:
        with _PADDLE_LOCK:
            ocr = _get_paddle_ocr_instance(tesseract_exe)
            try:
                raw_res = ocr.ocr(img_input, cls=True)
            except TypeError:
                raw_res = ocr.ocr(img_input)
        text = _extract_paddle_text(raw_res)
        if not text:
            return "", "скан без распознанного текста"
        return text, "OCR"
    except Exception as exc:
        return "", f"OCR завершился с ошибкой ({type(exc).__name__}: {exc})"


def _run_paddle_ocr_single(img_path: str, ocr_marker: str) -> Tuple[str, str]:
    """Вызывает PaddleOCR для одного файла изображения (с поддержкой кириллических путей)."""
    if not ocr_marker:
        return "", "PaddleOCR не установлен (установите пакеты paddlepaddle и paddleocr)"
    img_input = img_path
    try:
        import numpy as np
        from PIL import Image
        with Image.open(img_path) as pil_img:
            img_input = np.array(pil_img.convert("RGB"))[:, :, ::-1]
    except Exception:
        pass
    return _run_paddle_on_input(img_input, ocr_marker)


def _ocr_image_text(path: str, tesseract_exe: str) -> Tuple[str, str]:
    """OCR картинки (JPG/PNG/BMP/TIFF/WEBP/GIF и др.) через портативный PaddleOCR.
    Поддерживает многостраничные TIFF и работу напрямую в оперативной памяти.
    """
    if not tesseract_exe:
        return "", "PaddleOCR не установлен — установите paddlepaddle и paddleocr или используйте сборщик EXE"
    try:
        stat = os.stat(path)
        key = (path, stat.st_mtime_ns, stat.st_size)
    except OSError:
        key = (path, 0, 0)
    if key in _OCR_CACHE:
        return _OCR_CACHE[key]
    ext = os.path.splitext(path)[1].lower()
    if ext in (".tif", ".tiff", ".webp", ".gif", ".jfif"):
        try:
            import numpy as np
            from PIL import Image, ImageSequence
            chunks: List[str] = []
            with Image.open(path) as img:
                for page_idx, frame in enumerate(ImageSequence.Iterator(img)):
                    if page_idx >= 5:
                        break
                    bgr_arr = np.array(frame.convert("RGB"))[:, :, ::-1]
                    t_part, _n_part = _run_paddle_on_input(bgr_arr, tesseract_exe)
                    if t_part:
                        chunks.append(t_part)
            if chunks:
                result = (" ".join(chunks).strip(), "OCR")
                _cache_put(_OCR_CACHE, key, result)
                return result
        except Exception as exc:
            app_log(f"Multipage image OCR fallback ({os.path.basename(path)}): {type(exc).__name__}: {exc}")
    try:
        result = _run_paddle_ocr_single(path, tesseract_exe)
    except Exception as exc:
        result = ("", f"OCR не выполнен ({type(exc).__name__})")
    _cache_put(_OCR_CACHE, key, result)
    return result


def _write_bmp_rgb(path: str, width: int, height: int, stride: int,
                   data: bytes) -> bool:
    """Пишет RGB-растр в BMP 24 бита штатными средствами (без Pillow)."""
    try:
        if width <= 0 or height <= 0 or len(data) < stride * height:
            return False
        row_bytes = width * 3
        pad = b"\x00" * ((4 - row_bytes % 4) % 4)
        row_size = row_bytes + len(pad)
        pixel_size = row_size * height
        header = b"BM" + struct.pack("<IHHI", 54 + pixel_size, 0, 0, 54)
        info = struct.pack("<IiiHHIIiiII", 40, width, -height, 1, 24, 0,
                           pixel_size, 2835, 2835, 0, 0)
        with open(path, "wb") as fh:
            fh.write(header)
            fh.write(info)
            for y in range(height):
                off = y * stride
                fh.write(data[off:off + row_bytes])
                if pad:
                    fh.write(pad)
        return True
    except OSError:
        return False


_PDF_OCR_MAX_PAGES = 4
_PDF_OCR_SCALE = 200 / 72
_PDF_OCR_ENOUGH = 250     # читаем до 4 страниц скан-PDF, чтобы захватить и заявление, и расчёт


def _pdf_raster_ocr(path: str, tesseract_exe: str) -> Tuple[str, str]:
    """OCR скана-PDF (v3.7): быстрая растеризация в оперативной памяти (numpy) + PaddleOCR."""
    if not tesseract_exe:
        return "", "PaddleOCR не установлен — скан-PDF не распознан"
    try:
        import pypdfium2 as pdfium
    except Exception:
        return "", "нет модуля pypdfium2 — скан-PDF не распознан"
    try:
        stat = os.stat(path)
        key = (path, stat.st_mtime_ns, stat.st_size)
    except OSError:
        key = (path, 0, 0)
    if key in _OCR_CACHE:
        return _OCR_CACHE[key]
    result = ("", "скан-PDF без распознанного текста")
    tmp_path = ""
    pdf = None
    try:
        pdf = pdfium.PdfDocument(path)
        chunks: List[str] = []
        for page_no in range(min(len(pdf), _PDF_OCR_MAX_PAGES)):
            bitmap = None
            try:
                bitmap = pdf[page_no].render(scale=_PDF_OCR_SCALE,
                                             rev_byteorder=False)
            except Exception as exc:
                app_log(f"PDF page render skip ({os.path.basename(path)} p.{page_no + 1}): {type(exc).__name__}")
                continue
            # Прямая передача буфера страницы в numpy без записи временного BMP на диск
            in_mem_ok = False
            try:
                import numpy as np
                if hasattr(bitmap, "to_numpy"):
                    arr = bitmap.to_numpy()
                else:
                    w, h, st = bitmap.width, bitmap.height, bitmap.stride
                    nc = getattr(bitmap, "n_channels", 3)
                    buf = np.frombuffer(bitmap.buffer, dtype=np.uint8).reshape((h, st))
                    arr = buf[:, :w * nc].reshape((h, w, nc))
                if arr.ndim == 3 and arr.shape[2] == 4:
                    arr = arr[:, :, :3]
                otext, _onote = _run_paddle_on_input(np.ascontiguousarray(arr), tesseract_exe)
                if otext:
                    chunks.append(otext)
                in_mem_ok = True
            except Exception:
                in_mem_ok = False
            if not in_mem_ok:
                try:
                    width, height, stride = bitmap.width, bitmap.height, bitmap.stride
                    n_channels = getattr(bitmap, "n_channels", 3)
                    raw = bytes(bitmap.buffer)
                    if n_channels == 4:
                        bgr_rows = []
                        for y in range(height):
                            row_slice = raw[y * stride : y * stride + width * 4]
                            bgr_rows.append(b"".join(
                                row_slice[i:i + 3] for i in range(0, len(row_slice), 4)
                            ))
                        raw = b"".join(bgr_rows)
                        stride = width * 3
                    fd, tmp_path = tempfile.mkstemp(suffix=".bmp", prefix="amirs_pdfocr_")
                    os.close(fd)
                    try:
                        if _write_bmp_rgb(tmp_path, width, height, stride, raw):
                            otext, _onote = _ocr_image_text(tmp_path, tesseract_exe)
                            if otext:
                                chunks.append(otext)
                    finally:
                        try:
                            os.remove(tmp_path)
                        except OSError:
                            pass
                        tmp_path = ""
                except Exception:
                    pass
            if sum(len(c) for c in chunks) >= _PDF_OCR_ENOUGH:
                break
        if chunks:
            result = (re.sub(r"\s+", " ", " ".join(chunks)).strip(), "OCR (скан-PDF)")
    except Exception as exc:
        app_log(f"PDF raster OCR error ({os.path.basename(path)}): {type(exc).__name__}: {exc}")
        result = ("", "скан-PDF не распознан (ошибка растеризации)")
    finally:
        if tmp_path:
            try:
                os.remove(tmp_path)
            except OSError:
                pass
        if pdf is not None:
            try:
                pdf.close()
            except Exception:
                pass
    _cache_put(_OCR_CACHE, key, result)
    return result


def _configured_paddle_models_path() -> str:
    try:
        s = load_app_settings()
        return str(s.get("ocr_models_path") or s.get("tesseract_path") or "")
    except Exception:
        return ""


# Псевдонимы обратной совместимости для внешних тестов и скриптов
_find_tessdata_dir = _find_paddle_models_dir
_find_tesseract = _find_paddle_ocr
_run_tesseract_single = _run_paddle_ocr_single
_configured_tesseract_path = _configured_paddle_models_path


# ---------------------------------------------------------------------------
# Версия 3.8.1: чтение вложений TXT/HTML/XML/CSV/XLSX/ODT/ODS/RTF/DOC,
# безопасный разбор ZIP-архивов, файлы электронной подписи.
# Все лимиты заданы константами; ничего из архива не пишется на диск под
# именем из архива (защита от path traversal и «ZIP-бомб»).
# ---------------------------------------------------------------------------
_MAX_TEXT_BYTES = 8 * 1024 * 1024          # читаем не более 8 МБ текстового файла
_MAX_TEXT_CHARS = 500_000                  # и не более 500 тыс. символов результата
_ZIP_MAX_MEMBERS = 25                      # файлов из архива
_ZIP_MAX_MEMBER_BYTES = 20 * 1024 * 1024   # размер одного файла после распаковки
_ZIP_MAX_TOTAL_BYTES = 60 * 1024 * 1024    # суммарный размер после распаковки


def _read_limited(path: str, limit: int) -> bytes:
    with open(path, "rb") as fh:
        return fh.read(limit)


def _decode_text_bytes(data: bytes) -> str:
    """UTF-8 (с BOM или без) → UTF-16 (по BOM) → CP1251."""
    if data.startswith((b"\xff\xfe", b"\xfe\xff")):
        return data.decode("utf-16", errors="replace")
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        return data.decode("cp1251", errors="replace")


def _squash_text(text: str) -> str:
    return re.sub(r"[ \t\r\f\v]+", " ", text).strip()[:_MAX_TEXT_CHARS]


def _txt_html_xml_extract_text(path: str) -> Tuple[str, str, str]:
    try:
        text = _decode_text_bytes(_read_limited(path, _MAX_TEXT_BYTES))
    except OSError as exc:
        return "", f"файл не читается ({exc})", "fail"
    if os.path.splitext(path)[1].lower() in (".html", ".htm", ".xml"):
        text = re.sub(r"(?is)<(script|style)\b.*?</\1\s*>", " ", text)
        text = re.sub(r"(?s)<!--.*?-->", " ", text)
        text = re.sub(r"(?i)</?(?:p|div|br|tr|li|h\d)\b[^>]*>", "\n", text)
        text = re.sub(r"(?s)<[^>]+>", " ", text)
        text = _html.unescape(text)
    text = _squash_text(text)
    if not text:
        return "", "пустой файл", "scan"
    return text, "", "text"


def _csv_extract_text(path: str) -> Tuple[str, str, str]:
    try:
        raw = _decode_text_bytes(_read_limited(path, _MAX_TEXT_BYTES))
    except OSError as exc:
        return "", f"файл не читается ({exc})", "fail"
    delimiter = "\t" if path.lower().endswith(".tsv") else ";"
    if not path.lower().endswith(".tsv"):
        try:
            delimiter = csv.Sniffer().sniff(raw[:4096], delimiters=";,\t|").delimiter
        except csv.Error:
            delimiter = ";"
    lines: List[str] = []
    try:
        for i, row in enumerate(csv.reader(io.StringIO(raw), delimiter=delimiter)):
            if i >= 5000:
                break
            lines.append(" ".join(c.strip() for c in row if c.strip()))
    except csv.Error:
        return "", "таблица CSV не разобрана", "fail"
    text = _squash_text("\n".join(x for x in lines if x))
    return (text, "", "text") if text else ("", "пустая таблица", "scan")


def _xlsx_attachment_extract_text(path: str) -> Tuple[str, str, str]:
    try:
        if os.path.getsize(path) > _ZIP_MAX_MEMBER_BYTES:
            return "", "книга Excel слишком велика — проверить визуально", "scan"
        rows, err = read_xlsx_native(path)
    except OSError as exc:
        return "", f"файл не читается ({exc})", "fail"
    if rows is None:
        return "", err or "книга Excel не прочитана", "fail"
    lines = []
    for r in rows[:5000]:
        cells = r.get("cells", {})
        lines.append(" ".join(str(cells[k]).strip() for k in sorted(cells) if str(cells[k]).strip()))
    text = _squash_text("\n".join(x for x in lines if x))
    return (text, "", "text") if text else ("", "пустая книга", "scan")


def _odt_ods_extract_text(path: str) -> Tuple[str, str, str]:
    try:
        with zipfile.ZipFile(path) as z:
            info = z.getinfo("content.xml")
            if info.file_size > _ZIP_MAX_MEMBER_BYTES:
                return "", "документ слишком велик — проверить визуально", "scan"
            with z.open(info) as src:
                data = src.read(_ZIP_MAX_MEMBER_BYTES + 1)
        if len(data) > _ZIP_MAX_MEMBER_BYTES:
            return "", "документ слишком велик — проверить визуально", "scan"
    except (zipfile.BadZipFile, KeyError, OSError, zlib.error, RuntimeError):
        return "", "файл ODF повреждён", "fail"
    s = data.decode("utf-8", errors="replace")
    s = re.sub(r"</(?:text:p|text:h|table:table-row)>", "\n", s)
    s = re.sub(r"</table:table-cell>", " ", s)
    s = re.sub(r"(?s)<[^>]+>", " ", s)
    text = _squash_text(_html.unescape(s))
    return (text, "", "text") if text else ("", "пустой документ", "scan")


def _rtf_extract_text(path: str) -> Tuple[str, str, str]:
    try:
        raw = _read_limited(path, _MAX_TEXT_BYTES)
    except OSError as exc:
        return "", f"файл RTF не читается ({exc})", "fail"
    s = raw.decode("latin-1", errors="ignore")
    s = re.sub(r"\{\\(?:fonttbl|colortbl|stylesheet|pict|object|info|header|footer)"
               r"[^{}]*(?:\{[^{}]*\}[^{}]*)*\}", " ", s)

    def _u_repl(m):
        code = int(m.group(1))
        return chr(code + 65536 if code < 0 else code) if -32768 <= code <= 65535 else ""

    s = re.sub(r"\\u(-?\d{1,6})\??", _u_repl, s)

    def _hex_repl(m):
        try:
            return bytes.fromhex(m.group(0).replace("\\'", "")).decode("cp1251", errors="ignore")
        except ValueError:
            return " "

    s = re.sub(r"(?:\\'[0-9a-fA-F]{2})+", _hex_repl, s)
    s = re.sub(r"\\(?:par|line|tab|cell|row)\b", " ", s)
    s = re.sub(r"\\[a-zA-Z]+-?\d*\s?", " ", s)
    s = re.sub(r"[{}]", " ", s)
    text = _squash_text(re.sub(r"\s+", " ", s))
    if len(text) < 10:
        return "", "RTF без распознанного текста", "scan"
    return text, "", "text"


_RU_VOWELS = set("аеёиоуыэюяАЕЁИОУЫЭЮЯ")


def _looks_like_russian_words(seg: str) -> bool:
    """Отсев «кириллического мусора» из случайных байтов: у настоящих слов доля
    гласных 28–55 %, а заглавных букв внутри слова почти нет."""
    letters = [c for c in seg if "А" <= c <= "я" or c in "Ёё"]
    if len(letters) < 4:
        return False
    vow = sum(1 for c in letters if c in _RU_VOWELS) / len(letters)
    upper = sum(1 for c in letters if c.isupper()) / len(letters)
    return 0.28 <= vow <= 0.55 and upper <= 0.35


def _doc_binary_extract_text(path: str) -> Tuple[str, str, str]:
    """Эвристическое чтение старого .doc (без внешних программ). Если слов
    не набралось — возвращает «scan» (проверить визуально), а не мусор."""
    try:
        data = _read_limited(path, 15 * 1024 * 1024)
    except OSError as exc:
        return "", f"файл не читается ({exc})", "fail"
    chunks: List[str] = []
    for codec, rx in (("utf-16-le", r"[А-Яа-яЁё0-9.,:;()«»№/\-\s]{8,}"),
                      ("cp1251", r"[А-Яа-яЁё][А-Яа-яЁё0-9.,:;()«»№/\-\s]{7,}")):
        view = data.decode(codec, errors="ignore")
        for m in re.finditer(rx, view):
            seg = m.group(0).strip()
            words = [w for w in re.findall(r"[А-Яа-яЁё]{3,}", seg) if _looks_like_russian_words(w)]
            if len(words) >= 2:
                chunks.append(seg)
    text = _squash_text(re.sub(r"\s+", " ", " ".join(chunks)))
    good = [w for w in re.findall(r"[А-Яа-яЁё]{4,}", text) if _looks_like_russian_words(w)]
    if len(good) < 8:
        return "", "бинарный .doc без надёжно читаемого текста — проверить визуально", "scan"
    return text, "текст из .doc извлечён эвристически — проверьте документ", "text"


def _zip_extract_text(path: str, tesseract_cfg: str = "") -> Tuple[str, str, str]:
    """Читает поддерживаемые файлы из ZIP в памяти/временной папке с жёсткими
    лимитами. Вложенные архивы не вскрываются; имена из архива не используются."""
    notes: List[str] = []
    texts: List[str] = []
    tmp = tempfile.mkdtemp(prefix="amirs_zip_")
    zf = None
    try:
        try:
            zf = zipfile.ZipFile(path)
        except (zipfile.BadZipFile, OSError):
            return "", "архив повреждён или не читается", "fail"
        infos = [i for i in zf.infolist() if not i.is_dir()]
        if len(infos) > _ZIP_MAX_MEMBERS:
            notes.append(f"в архиве {len(infos)} файлов — прочитаны первые {_ZIP_MAX_MEMBERS}")
            infos = infos[:_ZIP_MAX_MEMBERS]
        total = 0
        for idx, info in enumerate(infos):
            name = os.path.basename(info.filename.replace("\\", "/"))
            ext = os.path.splitext(name)[1].lower()
            if not name or name.startswith(".") or "__MACOSX" in info.filename:
                continue
            if ext in _ARCHIVE_EXTS:
                notes.append(f"вложенный архив «{name}» не вскрывается")
                continue
            if ext not in SUPPORTED_ATTACHMENT_EXTS or ext in _EDS_EXTS:
                continue
            if info.flag_bits & 0x1:
                notes.append(f"«{name}» зашифрован — проверить визуально")
                continue
            if info.file_size > _ZIP_MAX_MEMBER_BYTES or total + info.file_size > _ZIP_MAX_TOTAL_BYTES:
                notes.append(f"«{name}» слишком велик — не распаковывался")
                continue
            try:
                with zf.open(info) as src:
                    data = src.read(_ZIP_MAX_MEMBER_BYTES + 1)   # заголовок мог солгать
            except (zipfile.BadZipFile, RuntimeError, NotImplementedError, EOFError,
                    zlib.error, OSError):
                notes.append(f"«{name}» не прочитан")
                continue
            if len(data) > _ZIP_MAX_MEMBER_BYTES or total + len(data) > _ZIP_MAX_TOTAL_BYTES:
                notes.append(f"«{name}» слишком велик — не распаковывался")
                continue
            total += len(data)
            safe = os.path.join(tmp, f"{idx:03d}{ext}")
            with open(safe, "wb") as fh:
                fh.write(data)
            t, _note, _ch = _extract_document_text_uncached(safe, tesseract_cfg)
            if t.strip():
                texts.append(t)
            else:
                notes.append(f"«{name}» без читаемого текста — проверить визуально")
    finally:
        if zf is not None:
            zf.close()
        shutil.rmtree(tmp, ignore_errors=True)
    if texts:
        return "\n\n".join(texts)[:_MAX_TEXT_CHARS], "; ".join(notes), "text"
    return "", "; ".join(notes) or "в архиве нет читаемых документов", "scan"


def _analyze_eds_file(path: str, name: str) -> "DocFileInfo":
    """Файлы подписи/сертификата сами по себе документом не считаются и не
    подменяют текст заявления; проверяется только структура файла."""
    try:
        head = _read_limited(path, 4096)
    except OSError as exc:
        return DocFileInfo(name, "", f"файл не читается ({exc})", DOC_STATUS_FAIL)
    try:
        size = os.path.getsize(path)
    except OSError:
        size = len(head)
    is_pem = b"-----BEGIN" in head
    is_der = size >= 64 and head[:1] == b"\x30"      # ASN.1 SEQUENCE
    if not (is_pem or is_der):
        return DocFileInfo(name, "", "файл подписи повреждён или не является подписью/сертификатом",
                           DOC_STATUS_FAIL)
    return DocFileInfo(name, DOC_KIND_EDS,
                       "подпись/сертификат: действительность проверьте средствами КриптоПро",
                       DOC_STATUS_SKIP)


_FIO_STOP_WORDS = {"дата", "адрес", "снилс", "инн", "место", "паспорт", "телефон", "проживающий",
                   "проживающая", "зарегистрированный", "зарегистрированная", "рождения"}
_NUM_RX = r"\d[\d\s]{0,12}(?:[.,]\d{1,2})?"


def parse_claim_text_fields(text: str) -> Dict[str, str]:
    """Достаёт реквизиты из текста заявления о судебном приказе (экспресс-ввод).

    Версия 3.8.1: ФИО не «подхватывает» слово с новой строки; адрес должника
    ищется только в блоке должника (а не адрес взыскателя); период с датами
    ДД.ММ.ГГГГ распознаётся; сумма долга — в обоих порядках слов.
    """
    out: Dict[str, str] = {}
    if not text or not text.strip():
        return out
    clean = re.sub(r"[ \t]+", " ", text[:_MAX_TEXT_CHARS])

    m_cl = re.search(r"(?:Взыскатель|Заявитель)\s*[:\-–—]\s*([^\n\r;]{4,140}?)"
                     r"(?=\s+(?:Адрес|ИНН|ОГРН|Должник|Телефон)\b|\s*[\n\r]|\s*$)", clean, re.I)
    if m_cl:
        out["Взыскатель"] = m_cl.group(1).strip(" ,.;:")

    # --- должник: ФИО и его блок текста
    word = r"[А-ЯЁ][а-яё]+(?:-[А-ЯЁ][а-яё]+)?"
    fio_rx = (rf"({word}(?:[ \t]+{word}){{1,3}}|{word}[ \t]+[А-ЯЁ]\.[ \t]?[А-ЯЁ]\.)")
    m_deb = re.search(r"Должник\s*[:\-–—]\s*", clean)
    m_fio = re.search(r"Должник\s*[:\-–—]\s*" + fio_rx, clean)
    if not m_fio:
        m_fio = re.search(r"взыскать\s+с(?:\s+должника)?\s+" + fio_rx, clean, re.I)
    if m_fio:
        parts = m_fio.group(1).split()
        while len(parts) > 2 and parts[-1].lower() in _FIO_STOP_WORDS:
            parts.pop()
        out["ФИО должника"] = " ".join(parts).strip(" ,.;:")

    seg = clean
    if m_deb:
        tail = clean[m_deb.start():]
        m_end = re.search(r"(?:Взыскатель|Заявитель)\s*[:\-–—]", tail)
        seg = tail[:m_end.start()] if m_end else tail
    elif not m_fio:
        seg = clean

    m_bd = re.search(r"(?:дата\s+рождения|г\.?\s*р\.?)\s*[:\-–—]?\s*"
                     r"(\d{2}[./]\d{2}[./]\d{4}|\d{4}-\d{2}-\d{2})", seg, re.I)
    if m_bd:
        parsed_bd = parse_date_value(m_bd.group(1))
        if parsed_bd:
            out["Дата рождения (ДД.ММ.ГГГГ)"] = parsed_bd
    m_bp = re.search(r"(?:место\s+рождения|урожен(?:ец|ка))\s*[:\-–—]?\s*([^\n\r;]{3,90}?)"
                     r"(?=\s+(?:адрес|паспорт|снилс|инн|прожив|зарегистр)\b|\s*[\n\r]|\s*$)", seg, re.I)
    if m_bp:
        out["Место рождения"] = m_bp.group(1).strip(" ,.;:")

    addr_tail = (r"(?=\s+(?:СНИЛС|ИНН|паспорт|телефон|лицевой|прошу)\b|\s*[\n\r]|\s*$)")
    m_addr = re.search(r"(?:адрес\s+(?:регистрации|места\s+жительства|проживания|должника)"
                       r"|зарегистрирован\w*\s+по\s+адресу|место\s+жительства)\s*[:\-–—]?\s*"
                       r"([^\n\r]{10,160}?)" + addr_tail, seg, re.I)
    if not m_addr and m_deb:      # голое «Адрес:» допустимо только внутри блока должника
        m_addr = re.search(r"адрес\s*[:\-–—]\s*([^\n\r]{10,160}?)" + addr_tail, seg, re.I)
    if m_addr:
        out["Адрес должника"] = m_addr.group(1).strip(" ,.;:")

    m_snils = re.search(r"(?<!\d)(\d{3}[-\s]?\d{3}[-\s]?\d{3}[\s\-]?\d{2})(?!\d)", seg)
    if m_snils and len(only_digits(m_snils.group(1))) == 11:
        sn, _w = check_snils(m_snils.group(1))
        if sn:
            out["СНИЛС или ИНН"] = sn
    if "СНИЛС или ИНН" not in out:
        m_inn = re.search(r"ИНН\s*(?:должника)?\s*[:№\-]?\s*(\d{12})(?!\d)", seg, re.I)
        if m_inn:
            out["СНИЛС или ИНН"] = m_inn.group(1)

    m_acc = re.search(r"(?:лицево(?:й|му)\s+сч[её]т\w*|л/с)\s*[№:.\-]?\s*([0-9A-Za-z\-]{5,24})",
                      clean, re.I)
    if m_acc:
        out["Лицевой счёт"] = clean_account_number(m_acc.group(1))

    m_per = re.search(r"с\s+(\d{2}\.\d{2}\.\d{4})\s*(?:г\.?\s*)?(?:по|[-–—])\s*(\d{2}\.\d{2}\.\d{4})", clean, re.I)
    if m_per:
        out["Период задолженности"] = f"с {m_per.group(1)} по {m_per.group(2)}"
    else:
        m_per = re.search(r"за\s+период\s+(?:с\s+)?([^\n\r.;]{5,65}?)"
                          r"(?=\s+(?:в\s+размере|в\s+сумме|составляет|основного)\b|\s*[\n\r]|\s*$)",
                          clean, re.I)
        if m_per:
            out["Период задолженности"] = m_per.group(1).strip(" ,.;:")

    m_debt = (re.search(r"(?:основного\s+долга|сумма\s+долга|задолженность\s+составляет|"
                        r"взыскать[^.]{1,80}?задолженность)\s*(?:в\s+размере|в\s+сумме|[:\-–—])?\s*"
                        rf"({_NUM_RX})\s*руб", clean, re.I)
              or re.search(rf"({_NUM_RX})\s*руб\.?\s*(?:основного\s+долга|долга)", clean, re.I))
    if m_debt:
        amt = parse_amount(m_debt.group(1))
        if amt:
            out["Сумма долга, руб."] = amt
    m_pen = re.search(rf"(?:пени|неустойк[аи])\s*(?:в\s+размере|в\s+сумме|[:\-–—])?\s*({_NUM_RX})\s*руб",
                      clean, re.I)
    if m_pen:
        p_amt = parse_amount(m_pen.group(1))
        if p_amt:
            out["Пени, руб."] = p_amt
    m_duty = re.search(r"(?:госпошлин\w*|государственн\w*\s+пошлин\w*)\s*(?:в\s+размере|в\s+сумме|[:\-–—])?\s*"
                       rf"({_NUM_RX})\s*руб", clean, re.I)
    if m_duty:
        d_amt = parse_amount(m_duty.group(1))
        if d_amt:
            out["Оплачено пошлины, руб."] = d_amt
    cat = match_st122_category(clean)
    if cat:
        out["Категория (ст. 122)"] = cat
    return out


def _extract_document_text_uncached(path: str, tesseract_cfg: str = "") -> Tuple[str, str, str]:
    """(текст, примечание, канал) без кэша. Любая ошибка чтения одного файла
    превращается в канал fail — «странный» файл не должен валить проверку пакета."""
    ext = os.path.splitext(path)[1].lower()
    res: Tuple[str, str, str]
    try:
        if ext in _IMAGE_EXTS:
            text, note = _ocr_image_text(path, _find_paddle_ocr(tesseract_cfg))
            if text:
                res = (text, "OCR", "image")
            else:
                res = ("", note or "скан без распознанного текста", "image")
        elif ext == ".docx":
            res = _docx_extract_text(path, tesseract_cfg)
        elif ext == ".pdf":
            alt = _pypdf_extract_text(path)
            if len(alt) >= 20:
                res = (alt, "", "text")
            else:
                text, note, channel = _pdf_extract_text(path)
                if len(alt) > len(text):
                    text = alt
                if len(text) >= 20:
                    res = (text, "", "text")
                elif channel == "scan":
                    otext, onote = _pdf_raster_ocr(path, _find_paddle_ocr(tesseract_cfg))
                    if otext:
                        res = (otext, "OCR (скан-PDF)", "image")
                    else:
                        if onote:
                            note = f"скан-PDF: {onote}"
                        res = (text, note, channel)
                else:
                    res = (text, note, channel)
        elif ext in _TEXT_DOC_EXTS:
            res = _txt_html_xml_extract_text(path)
        elif ext in (".csv", ".tsv"):
            res = _csv_extract_text(path)
        elif ext in (".xlsx", ".xlsm"):
            res = _xlsx_attachment_extract_text(path)
        elif ext in (".ods", ".odt"):
            res = _odt_ods_extract_text(path)
        elif ext == ".rtf":
            res = _rtf_extract_text(path)
        elif ext == ".doc":
            res = _doc_binary_extract_text(path)
        elif ext in _ARCHIVE_EXTS:
            res = _zip_extract_text(path, tesseract_cfg)
        else:
            res = ("", "формат файла не поддерживается", "fail")
    except Exception as exc:  # noqa: BLE001 — изоляция сбоя одного вложения
        res = ("", f"не удалось прочитать файл ({type(exc).__name__})", "fail")
    return res


def extract_document_text(path: str, tesseract_cfg: str = "") -> Tuple[str, str, str]:
    """(текст, примечание, канал) — канал: text | image | scan | fail. Результат кэшируется."""
    try:
        st = os.stat(path)
        cache_key = (path, st.st_mtime_ns, st.st_size, tesseract_cfg or "")
    except OSError:
        cache_key = None
    if cache_key is not None and cache_key in _DOC_TEXT_CACHE:
        return _DOC_TEXT_CACHE[cache_key]
    res = _extract_document_text_uncached(path, tesseract_cfg)
    if cache_key is not None:
        _cache_put(_DOC_TEXT_CACHE, cache_key, res)
    return res


@dataclass
class DocFileInfo:
    """Один файл-приложение и результат его анализа."""
    name: str
    kind: str = ""          # канонический тип (пусто — не распознано)
    detail: str = ""        # уточнение: подтип договора, «OCR», причина отказа
    status: str = DOC_STATUS_UNREC
    raw_text: str = ""      # извлечённый текст файла (чтобы не перечитывать файл повторно)


@dataclass
class DocCheckResult:
    """Итог сверки приложений одного заявления."""
    folder: str = ""
    matched: bool = False   # папка найдена и сопоставлена заявлению
    files: List[DocFileInfo] = field(default_factory=list)
    found_kinds: List[str] = field(default_factory=list)
    missing: List[str] = field(default_factory=list)
    manual_files: List[str] = field(default_factory=list)
    note: str = ""

    @property
    def found_text(self) -> str:
        return ", ".join(self.found_kinds)

    @property
    def missing_text(self) -> str:
        return "; ".join(self.missing)


def analyze_attachment_file(path: str, tesseract_exe: str = "") -> DocFileInfo:
    """Читает один файл и определяет тип документа (сохраняя извлечённый текст)."""
    name = os.path.basename(path)
    ext = os.path.splitext(name)[1].lower()
    if ext in _EDS_EXTS:
        return _analyze_eds_file(path, name)
    text, note, channel = extract_document_text(path, tesseract_exe)
    if channel == "fail":
        return DocFileInfo(name, "", note or "не удалось прочитать", DOC_STATUS_FAIL)
    if not text.strip():
        return DocFileInfo(name, "", note or "текст не извлечён — проверить визуально",
                           DOC_STATUS_SCAN)
    kind, detail = classify_document_text(text)
    status = DOC_STATUS_OCR if note.startswith("OCR") else DOC_STATUS_OK
    if kind == DOC_KIND_OTHER:
        return DocFileInfo(name, kind, detail or "тип по тексту не определён",
                           DOC_STATUS_UNREC, raw_text=text)
    return DocFileInfo(name, kind, detail, status, raw_text=text)


def _check_document_files(paths: List[str], required_groups: List[List[str]],
                          tesseract_cfg: str = "", folder_label: str = ""
                          ) -> DocCheckResult:
    """Сверка набора файлов-приложений с обязательным комплектом (без двойного чтения файлов)."""
    res = DocCheckResult(folder=folder_label, matched=True)
    notes: List[str] = []
    for full in paths:
        info = analyze_attachment_file(full, tesseract_cfg)
        res.files.append(info)
        if info.status in (DOC_STATUS_SCAN, DOC_STATUS_FAIL):
            res.manual_files.append(info.name)
        if (info.kind and info.kind not in res.found_kinds
                and info.kind not in DOC_KINDS_INFO
                and info.kind != DOC_KIND_OTHER
                and info.status in (DOC_STATUS_OK, DOC_STATUS_OCR)):
            res.found_kinds.append(info.kind)
        if info.status in (DOC_STATUS_OK, DOC_STATUS_OCR):
            raw_text = info.raw_text
            if not raw_text:
                raw_text, _n, _c = extract_document_text(full, tesseract_cfg)
            for extra_kind in classify_all_document_kinds(raw_text):
                if (extra_kind not in res.found_kinds
                        and extra_kind not in DOC_KINDS_INFO
                        and extra_kind != DOC_KIND_OTHER):
                    res.found_kinds.append(extra_kind)
    for group in required_groups:
        if not any(kind in res.found_kinds for kind in group):
            res.missing.append(" или ".join(group))
    if res.files and not any(f.kind == DOC_KIND_ZAYAVLENIE for f in res.files):
        notes.append("само заявление среди файлов не распознано")
    if notes:
        res.note = "; ".join(notes)
    return res


def check_claim_documents(folder_path: str, required_groups: List[List[str]],
                          tesseract_cfg: str = "") -> DocCheckResult:
    """Анализирует папку одного заявления и сверяет с обязательным набором."""
    try:
        names = sorted(os.listdir(folder_path))
    except OSError as exc:
        res = DocCheckResult(folder=folder_path, matched=True)
        res.note = f"папка не читается ({exc})"
        res.missing = [" или ".join(g) for g in required_groups]
        return res
    subdirs = 0
    file_paths: List[str] = []
    for name in names:
        full = os.path.join(folder_path, name)
        if os.path.isdir(full):
            subdirs += 1
            continue
        file_paths.append(full)
    res = _check_document_files(file_paths, required_groups, tesseract_cfg,
                                folder_label=folder_path)
    if subdirs:
        res.note = (res.note + "; " if res.note else ""
                    ) + f"вложенных папок: {subdirs} (не просмотрены)"
    return res


def check_claim_files(file_paths: List[str], required_groups: List[List[str]],
                      tesseract_cfg: str = "") -> DocCheckResult:
    """Сверка отдельных файлов-приложений (кнопка «Обзор: файлы…», v3.6.1)."""
    paths = sorted(p for p in (file_paths or []) if os.path.isfile(p))
    return _check_document_files(paths, required_groups, tesseract_cfg)


# -- профили обязательных документов (amirs_docs.json) ------------------------

DEFAULT_DOC_PROFILES: Dict[str, List[List[str]]] = {
    "оплата жилого помещения, коммунальных услуг, услуг связи":
        [[DOC_KIND_DOGOVOR, DOC_KIND_EGRN], [DOC_KIND_RASCHET]],
    "обязательные платежи и взносы членов ТСН (кооператива)":
        [[DOC_KIND_DOGOVOR, DOC_KIND_EGRN], [DOC_KIND_RASCHET]],
    "сделка в простой письменной форме":
        [[DOC_KIND_DOGOVOR]],
    "нотариально удостоверенная сделка":
        [[DOC_KIND_DOGOVOR]],
    "заработная плата и иные выплаты работнику":
        [[DOC_KIND_RASCHET]],
    "компенсация за нарушение срока выплаты работнику":
        [[DOC_KIND_RASCHET]],
    "алименты на несовершеннолетних детей":
        [[DOC_KIND_BIRTH_CERT], [DOC_KIND_FAMILY_CERT, DOC_KIND_RASCHET]],
    "протест векселя в неплатеже, неакцепте и недатировании акцепта":
        [[DOC_KIND_DOGOVOR]],
    "расходы ФССП на розыск ответчика, должника, ребенка":
        [[DOC_KIND_RASCHET]],
}

_DOCS_CACHE: Dict[str, object] = {}


def doc_profiles_path() -> str:
    """Путь к файлу профилей документов (рядом с программой/EXE)."""
    return os.path.join(_app_data_dir(), DOCS_FILE_NAME)


def ensure_docs_config(path: str = "") -> str:
    """Создаёт amirs_docs.json, если файла ещё нет; существующий не трогает."""
    target = path or doc_profiles_path()
    if os.path.exists(target):
        return target
    try:
        with open(target, "w", encoding="utf-8") as fh:
            json.dump({
                "_описание": (
                    "Профили обязательных документов-приложений по категориям "
                    "ст. 122 ГПК РФ. Категория — список групп: заявление должно "
                    "содержать хотя бы один документ ИЗ КАЖДОЙ группы. Возможные "
                    "типы: " + "; ".join(sorted(
                        {kind for groups in DEFAULT_DOC_PROFILES.values()
                         for grp in groups for kind in grp}
                    )) + ". Файл можно править; испорченный файл не блокирует "
                    "программу (встроенные профили)."),
                "профили": DEFAULT_DOC_PROFILES,
            }, fh, ensure_ascii=False, indent=2)
        app_log(f"создан файл профилей документов: {target}")
    except OSError:
        pass  # не смогли создать — работаем на встроенных профилях
    return target


def load_doc_profiles(path: str = "") -> Dict[str, List[List[str]]]:
    """Читает профили из amirs_docs.json (перечитывает при изменении файла)."""
    target = path or doc_profiles_path()
    try:
        stat = os.stat(target)
        key = (target, stat.st_mtime_ns, stat.st_size)
    except OSError:
        return dict(DEFAULT_DOC_PROFILES)
    if _DOCS_CACHE.get("key") == key:
        return _DOCS_CACHE["profiles"]
    profiles = dict(DEFAULT_DOC_PROFILES)
    try:
        with open(target, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        raw = data.get("профили") if isinstance(data, dict) else None
        if isinstance(raw, dict):
            for cat, groups in raw.items():
                if not isinstance(groups, list):
                    continue
                clean: List[List[str]] = []
                for grp in groups:
                    if isinstance(grp, list):
                        kinds = [str(t).strip() for t in grp if str(t).strip()]
                        if kinds:
                            clean.append(kinds)
                    elif str(grp).strip():
                        clean.append([str(grp).strip()])
                if clean:
                    profiles[str(cat).strip()] = clean
    except (OSError, ValueError) as exc:
        app_log(f"amirs_docs.json не прочитан ({target}) — использую встроенные "
                f"профили ({exc})")
    _DOCS_CACHE["key"] = key
    _DOCS_CACHE["profiles"] = profiles
    return profiles


def docs_profile_groups(category: str,
                        profiles: Optional[Dict[str, List[List[str]]]] = None
                        ) -> Tuple[List[List[str]], str]:
    """Группы обязательных документов для категории требования.

    Возвращает (группы, источник): 'профиль' (из amirs_docs.json),
    'встроенный' (по распознанной категории ст. 122) или 'минимальный'
    (категория не распознана — только расчёт задолженности).
    """
    profiles = profiles if profiles is not None else load_doc_profiles()
    cat = (category or "").strip().lower()
    for name, groups in profiles.items():
        if name.strip().lower() == cat:
            return groups, "профиль"
    matched = match_st122_category(category or "")
    if matched and matched in DEFAULT_DOC_PROFILES:
        return DEFAULT_DOC_PROFILES[matched], "встроенный"
    return [[DOC_KIND_RASCHET]], "минимальный"


# -- сопоставление папок приложений со строками реестра -----------------------

def _norm_doc_key(s: str) -> str:
    """Нормализация ФИО/имени папки: строчные, без знаков, ё -> е."""
    s = (s or "").lower().replace("ё", "е")
    s = re.sub(r"[^0-9а-я\s]", " ", s)
    return " ".join(s.split())


def match_attachment_folders(root: str, records: List[Dict[str, str]]
                             ) -> Tuple[Dict[int, str], List[str], str]:
    """Сопоставляет подпапки «на заявление» со строками реестра.

    records — [{'row': int, 'fio': str, 'account': str}]. Сначала ищется
    лицевой счёт (4+ цифры в имени папки), затем нормализованное ФИО.
    Возвращает (сопоставленные, непривязанные папки, примечание).
    """
    by_account: Dict[str, int] = {}
    by_fio: Dict[str, int] = {}
    for rec in records:
        acc = re.sub(r"\D", "", str(rec.get("account") or ""))
        row_no = int(rec.get("row") or 0)
        if acc:
            by_account.setdefault(acc, row_no)
        fio = _norm_doc_key(rec.get("fio") or "")
        if fio:
            by_fio.setdefault(fio, row_no)
    try:
        names = sorted(os.listdir(root))
    except OSError as exc:
        return {}, [], f"папка приложений не читается ({exc})"
    mapping: Dict[int, str] = {}
    unmatched: List[str] = []
    _IGNORE_DIRS = {
        "build", "dist", "__pycache__", ".git", ".idea", ".vscode",
        "paddle_models", "paddleocr", "tesseract-ocr", "tesseract", "venv", ".venv"
    }
    _IGNORE_PREFIXES = (
        "пакет_документов_", "скрининг_ст125_", "конвертер_амирс"
    )
    _IGNORE_FILES = {
        "amirs_converter.py", "build_exe.py", "собрать_exe.bat",
        "конвертер_амирс.spec", "конвертер_амирс.exe",
        "amirs_docs.json", "amirs_fees.json", "amirs_settings.json",
        "amirs_import_package.xml", "инструкция_tesseract_ocr.txt",
        "инструкция_paddleocr.txt", "amirs_log.txt", "screening_journal.csv",
        "conversion_journal.csv", "claims_registry.csv", "error_log.csv",
        "warnings_log.csv", "шаблон_реестра_должников.xlsx"
    }
    root_files = 0
    for name in names:
        low_name = name.lower()
        if low_name.startswith(".") or low_name.startswith("~$"):
            continue
        full = os.path.join(root, name)
        if not os.path.isdir(full):
            if low_name in _IGNORE_FILES or low_name.endswith((".py", ".bat", ".spec", ".exe", ".pyc", ".log", ".csv", ".json", ".xml")):
                continue
            root_files += 1
            continue
        if low_name in _IGNORE_DIRS or low_name.startswith(_IGNORE_PREFIXES):
            continue
        row_no: Optional[int] = None
        for digits in re.findall(r"\d{4,}", name):
            if digits in by_account:
                row_no = by_account[digits]
                break
        if row_no is None:
            nfold = _norm_doc_key(name)
            for fio_key, r in by_fio.items():
                if fio_key and fio_key in nfold:
                    row_no = r
                    break
        if row_no is None or row_no in mapping:
            unmatched.append(name)
        else:
            mapping[row_no] = full
    note = f"файлов в корне папки: {root_files} — разложите по подпапкам" \
        if root_files else ""
    return mapping, unmatched, note


def match_attachment_files(paths: List[str], records: List[Dict[str, str]],
                           tesseract_cfg: str = ""
                           ) -> Tuple[Dict[int, List[str]], List[str], str]:
    """Сопоставляет отдельные файлы-приложения со строками реестра (v3.7.4).

    Ключ «Обзор: файлы…»: файлы без подпапок. Сначала лицевой счёт и ФИО
    ищутся в имени файла, затем — в тексте документа по границам чисел/слов.
    При неоднозначном совпадении (однофамильцы или несколько записей с тем же
    счётом) файл оставляется в списке непривязанных для ручного выбора.
    """
    acc_rows: Dict[str, List[int]] = {}
    fio_keys: List[Tuple[str, str, int]] = []   # (полное ФИО, «Фамилия И И», row)
    for rec in records:
        acc = re.sub(r"\D", "", str(rec.get("account") or ""))
        row_no = int(rec.get("row") or 0)
        if acc:
            acc_rows.setdefault(acc, []).append(row_no)
        fio = _norm_doc_key(rec.get("fio") or "")
        if fio:
            toks = fio.split()
            init = (toks[0] + " " + " ".join(t[0] for t in toks[1:])
                    if len(toks) > 1 else toks[0])
            fio_keys.append((fio, init, row_no))
    mapping: Dict[int, List[str]] = {}
    unmatched: List[str] = []
    without_text = 0
    ambiguous_count = 0
    for path in paths:
        if not path or not os.path.isfile(path):
            unmatched.append(os.path.basename(path or "∅"))
            continue
        name = os.path.basename(path)
        candidates: List[int] = []
        # этап 1 — имя файла: точное совпадение токен-числа с лицевым счётом, затем ФИО
        for digits in re.findall(r"(?<!\d)\d{4,}(?!\d)", name):
            if digits in acc_rows:
                for r in acc_rows[digits]:
                    if r not in candidates:
                        candidates.append(r)
        if not candidates:
            nname = _norm_doc_key(name)
            for fio_key, _init, r in fio_keys:
                if fio_key and re.search(rf"(?<![а-я0-9]){re.escape(fio_key)}(?![а-я0-9])", nname):
                    if r not in candidates:
                        candidates.append(r)
        # этап 2 — текст документа: поиск лицевого счёта по границам цифр, затем ФИО/инициалы
        if not candidates:
            text, _note, _chan = extract_document_text(path, tesseract_cfg)
            if text.strip():
                doc_numbers = set(re.findall(r"(?<!\d)\d{4,}(?!\d)", text))
                for acc, r_list in acc_rows.items():
                    if acc in doc_numbers:
                        for r in r_list:
                            if r not in candidates:
                                candidates.append(r)
                if not candidates:
                    ntext = _norm_doc_key(text)
                    for fio_key, init, r in fio_keys:
                        if (fio_key and re.search(rf"(?<![а-я0-9]){re.escape(fio_key)}(?![а-я0-9])", ntext)) or \
                                (len(init) >= 5 and re.search(rf"(?<![а-я0-9]){re.escape(init)}(?![а-я0-9])", ntext)):
                            if r not in candidates:
                                candidates.append(r)
            else:
                without_text += 1
        if len(candidates) == 1:
            mapping.setdefault(candidates[0], []).append(path)
        else:
            if len(candidates) > 1:
                ambiguous_count += 1
            unmatched.append(name)
    notes: List[str] = []
    if without_text:
        notes.append(f"файлов без распознанного текста (сканы): {without_text} "
                     "— не удалось привязать по содержимому")
    if ambiguous_count:
        notes.append(f"неоднозначных совпадений (однофамильцы/счета): {ambiguous_count} "
                     "— оставлены для ручной привязки")
    return mapping, unmatched, "; ".join(notes)


def apply_manual_file_binds(file_map: Dict[int, List[str]],
                            unmatched: List[str],
                            records: List[Dict[str, str]],
                            binds: Optional[Dict[str, Dict[str, object]]]
                            ) -> Tuple[Dict[int, int], List[str]]:
    """Ручная привязка файлов к заявлениям (v3.7, окно предпросмотра).

    binds — {путь файла: {"row": номер строки, "fio": ФИО должника}}.
    Каждый файл дописывается в file_map своей строки (без дублей с
    автопривязкой) и убирается из списка непривязанных; привязки
    исчезнувших файлов или несовпадающих строк отбрасываются.
    Возвращает ({строка: сколько файлов привязано}, [пути без привязки]).
    """
    per_row: Dict[int, int] = {}
    stale: List[str] = []
    if not binds:
        return per_row, stale
    rows = {int(r.get("row") or 0): r for r in records}
    for path, entry in binds.items():
        try:
            row_no = int((entry or {}).get("row") or 0)
        except (TypeError, ValueError):
            row_no = 0
        rec = rows.get(row_no)
        entry_fio = str((entry or {}).get("fio") or "")
        if not path or not os.path.isfile(path) or rec is None or \
                (entry_fio and str(rec.get("fio") or "") != entry_fio):
            stale.append(path)
            continue
        if not any(path in lst for lst in file_map.values()):
            file_map.setdefault(row_no, []).append(path)
            per_row[row_no] = per_row.get(row_no, 0) + 1
        base = os.path.basename(path)
        while base in unmatched:
            unmatched.remove(base)
    return per_row, stale


def _app_data_dir() -> str:
    """Папка для настроек и справочников программы (рядом с программой/EXE)."""
    return os.path.dirname(_settings_path()) or os.getcwd()


def _protected_user_data_dir() -> str:
    """Защищенный каталог в профиле текущего пользователя для хранения накопительного
    реестра (claims_registry.csv) и журналов скрининга (screening_journal.csv).
    """
    base = (os.environ.get("LOCALAPPDATA")
            or os.environ.get("APPDATA")
            or os.path.expanduser("~"))
    target = os.path.join(base, "Komi_Justice_AMIRS")
    try:
        os.makedirs(target, mode=0o700, exist_ok=True)
    except OSError:
        target = os.path.join(_app_data_dir(), "user_profile_data")
        os.makedirs(target, exist_ok=True)

    # Автоматическая миграция существующих реестра и журнала из папки программы
    old_dir = _app_data_dir()
    if os.path.abspath(old_dir) != os.path.abspath(target):
        for fname in (CLAIMS_REGISTRY_NAME, SCREENING_LOG_NAME):
            old_file = os.path.join(old_dir, fname)
            new_file = os.path.join(target, fname)
            if os.path.isfile(old_file) and not os.path.exists(new_file):
                try:
                    shutil.move(old_file, new_file)
                except OSError:
                    pass
    return target


def screening_journal_path() -> str:
    """Путь к журналу скрининга в защищенном профиле пользователя."""
    return os.path.join(_protected_user_data_dir(), SCREENING_LOG_NAME)


# Запись в журнал возможна из главного потока и из фонового воркера скрининга —
# лок гарантирует, что «проверка размера -> открытие файла» не перекроются.
_log_lock = threading.Lock()


def app_log(message: str) -> None:
    """Системный журнал работы программы: amirs_log.txt в защищенном профиле."""
    try:
        with _log_lock:
            path = os.path.join(_protected_user_data_dir(), APP_LOG_NAME)
            size = os.path.getsize(path) if os.path.exists(path) else 0
            with open(path, "a" if size < 2_000_000 else "w", encoding="utf-8") as fh:
                fh.write(f"{datetime.now():%Y-%m-%d %H:%M:%S}\t{message}\n")
    except OSError:
        pass  # журнал не должен мешать основной работе


def cleanup_ocr_temp_files() -> int:
    """Принудительно удаляет растровые снимки страниц (amirs_*ocr_*) из %TEMP%
    при каждом запуске и закрытии программы.
    """
    removed = 0
    temp_dirs = {tempfile.gettempdir()}
    for env_var in ("TEMP", "TMP", "LOCALAPPDATA"):
        val = os.environ.get(env_var)
        if val:
            if env_var == "LOCALAPPDATA":
                val = os.path.join(val, "Temp")
            if os.path.isdir(val):
                temp_dirs.add(val)

    for tdir in temp_dirs:
        try:
            for pattern in ("amirs_*ocr_*", "amirs_pdfocr_*", "amirs_docxocr_*"):
                for fpath in glob.glob(os.path.join(tdir, pattern)):
                    try:
                        if os.path.isfile(fpath) or os.path.islink(fpath):
                            os.remove(fpath)
                            removed += 1
                        elif os.path.isdir(fpath):
                            shutil.rmtree(fpath, ignore_errors=True)
                            removed += 1
                    except OSError:
                        pass
        except OSError:
            pass
    _DOC_TEXT_CACHE.clear()
    _OCR_CACHE.clear()
    if removed:
        app_log(f"TEMP CLEANUP: удалено временных растровых файлов OCR: {removed}")
    return removed


atexit.register(cleanup_ocr_temp_files)


def _yn(raw) -> str:
    """«да/есть/+» -> «yes»; «нет/не…» -> «no»; прочее («—») -> «» (нет данных).

    Тире и прочерки считаются «не применимо» (например, заявления подано
    самим взыскателем — графы о доверенности не касаются), а не «нет».
    """
    s = re.sub(r"\s+", " ", str(raw or "")).strip().lower()
    yes = {"да", "есть", "+", "1", "yes", "y", "true", "подписано", "подписан",
           "приложены", "направлена", "направлен", "отмечено"}
    no = {"нет", "no", "n", "0", "false", "не подписано", "не подписан",
          "не приложены", "не направлена", "не направлен", "не отмечено"}
    if s in yes:
        return "yes"
    if s in no:
        return "no"
    return ""


def _is_rf(raw) -> bool:
    """Является ли строка указанием на Российскую Федерацию."""
    s = re.sub(r"\s+", " ", str(raw or "")).strip().lower().rstrip(".")
    return "российск" in s or s in ("рф", "rf", "россия", "русская федерация")


def match_st122_category(text: str) -> str:
    """Свободный текст -> каноническая категория ст. 122 (пусто — не распознано)."""
    s = re.sub(r"\s+", " ", str(text or "")).strip().lower()
    if not s:
        return ""
    if any(k in s for k in CATEGORY_OTHER_KEYS):
        return CATEGORY_OTHER
    for canonical, keys in ST122_CATEGORIES:
        if any(k in s for k in keys):
            return canonical
    return ""


# -- редактируемая шкала госпошлины (amirs_fees.json) -------------------------

# Встроенная шкала (если файла нет или он испорчен): пп. 1 п. 1 ст. 333.19
# НК РФ в ред. 259-ФЗ (с 08.09.2024), формат (верхняя_граница, фикс, процент
# с превышения предыдущей ступени); приказное производство — доля от неё
# (пп. 2 п. 1 ст. 333.19 НК РФ, сейчас 50 %).
DEFAULT_FEE_TIERS = [
    (Decimal("100000"), Decimal("4000"), Decimal("0")),
    (Decimal("300000"), Decimal("4000"), Decimal("3")),
    (Decimal("500000"), Decimal("10000"), Decimal("2.5")),
    (Decimal("1000000"), Decimal("15000"), Decimal("2.0")),
    (Decimal("10000000"), Decimal("25000"), Decimal("1.0")),
    (Decimal("50000000"), Decimal("115000"), Decimal("0.5")),
]
DEFAULT_FEE_SHARE = Decimal("50")
_FEES_CACHE: Dict[str, object] = {}


def default_fee_config() -> Dict[str, object]:
    """Содержимое amirs_fees.json по умолчанию (действующая шкала НК РФ)."""
    return {
        "_как_править": (
            "Файл читается программой при каждом расчёте пошлины: при индексации "
            "ставок ст. 333.19 НК РФ поправьте числа здесь — EXE пересобирать "
            "не нужно, правки подхватываются без перезапуска. "
            "доля_приказного_процентов — сколько процентов от пошлины за "
            "имущественный иск платит взыскатель за судебный приказ "
            "(пп. 2 п. 1 ст. 333.19 НК РФ, сейчас 50 %). "
            "Ступени шкалы пп. 1 п. 1 ст. 333.19 НК РФ: до_руб — верхняя граница "
            "ступени; фикс_руб — постоянная часть на нижней границе ступени; "
            "процент_свыше — процент с суммы, превышающей верхнюю границу "
            "ПРЕДЫДУЩЕЙ ступени. Числа можно задавать целыми или дробными."
        ),
        "доля_приказного_процентов": 50,
        "ступени": [
            {"до_руб": 100000, "фикс_руб": 4000, "процент_свыше": 0},
            {"до_руб": 300000, "фикс_руб": 4000, "процент_свыше": 3},
            {"до_руб": 500000, "фикс_руб": 10000, "процент_свыше": 2.5},
            {"до_руб": 1000000, "фикс_руб": 15000, "процент_свыше": 2.0},
            {"до_руб": 10000000, "фикс_руб": 25000, "процент_свыше": 1.0},
            {"до_руб": 50000000, "фикс_руб": 115000, "процент_свыше": 0.5},
        ],
    }


def fees_config_path() -> str:
    """Путь к файлу шкалы пошлины (рядом с программой/EXE)."""
    return os.path.join(_app_data_dir(), FEES_FILE_NAME)


def ensure_fees_config(path: str = "") -> str:
    """Создаёт amirs_fees.json с текущей шкалой, если файла ещё нет.

    Существующий файл (в том числе отредактированный пользователем)
    никогда не перезаписывается.
    """
    target = path or fees_config_path()
    if os.path.exists(target):
        return target
    try:
        with open(target, "w", encoding="utf-8") as fh:
            json.dump(default_fee_config(), fh, ensure_ascii=False, indent=2)
        app_log(f"создан файл шкалы пошлины: {target}")
    except OSError:
        pass  # не смогли создать — работаем на встроенной шкале
    return target


def _num_or_none(value) -> Optional[Decimal]:
    """Число из JSON (целое/дробное/строка) -> Decimal; иначе None."""
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError):
        return None
    return result if result.is_finite() else None


def _parse_fee_config(data: Dict[str, object]) -> Optional[tuple]:
    """Разбор конфига: (доля_приказного, [(до_руб, фикс, процент), ...]).

    Логически испорченный конфиг (нечисловые значения, ступени не по
    возрастанию, доля вне 0–100 %) — это None: работаем на встроенной шкале.
    """
    share = _num_or_none(data.get("доля_приказного_процентов"))
    if share is None or not (Decimal("0") < share <= Decimal("100")):
        return None
    raw_tiers = data.get("ступени")
    if not isinstance(raw_tiers, list) or not raw_tiers:
        return None
    tiers: List[tuple] = []
    prev = Decimal("0")
    for item in raw_tiers:
        if not isinstance(item, dict):
            return None
        up_to = _num_or_none(item.get("до_руб"))
        fixed = _num_or_none(item.get("фикс_руб"))
        percent = _num_or_none(item.get("процент_свыше"))
        if up_to is None or fixed is None or percent is None:
            return None
        if up_to <= 0 or fixed < 0 or percent < 0 or up_to <= prev:
            return None
        tiers.append((up_to, fixed, percent))
        prev = up_to
    return share, tiers


def load_fee_scale(path: str = "") -> tuple:
    """Читает шкалу пошлины из amirs_fees.json рядом с программой.

    Возвращает (доля_приказного, ступени). Файла нет или он не читается —
    встроенная шкала ст. 333.19 НК РФ (ред. 259-ФЗ) и запись в amirs_log.txt.
    Файл перечитывается при изменении — правки действуют без перезапуска.
    """
    target = path or fees_config_path()
    key = None
    try:
        stat = os.stat(target)
        key = (target, stat.st_mtime_ns, stat.st_size)
        if _FEES_CACHE.get("key") == key:
            return _FEES_CACHE["scale"]
        with open(target, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        parsed = _parse_fee_config(data) if isinstance(data, dict) else None
    except (OSError, ValueError):
        parsed = None
    if parsed is None:
        if key is not None and _FEES_CACHE.get("bad_key") != key:
            app_log(f"amirs_fees.json не прочитан ({target}) — использую "
                    "встроенную шкалу ст. 333.19 НК РФ (ред. 259-ФЗ)")
            _FEES_CACHE["bad_key"] = key
        return DEFAULT_FEE_SHARE, list(DEFAULT_FEE_TIERS)
    if key is not None:
        _FEES_CACHE["key"] = key
        _FEES_CACHE["scale"] = parsed
    return parsed


def _state_duty_from_scale(amount: Decimal, share: Decimal,
                           tiers: List[tuple]) -> str:
    """Расчёт по шкале: фикс + процент с превышения предыдущей ступени.

    Сумма выше последней ступени — последняя ставка продолжается от её
    нижней границы (расширение формулы ступени «свыше …»): для шкалы
    ст. 333.19 НК РФ 600 000 руб. дают 10 000 + 300 000 × 2,5 % = 17 500,
    приказное — 8 750 руб. (свыше лимита приказного это справочно).
    """
    prev_bound = Decimal("0")
    for up_to, fixed, percent in tiers:
        if amount <= up_to:
            base = fixed + (amount - prev_bound) * percent / Decimal("100")
            duty = base * share / Decimal("100")
            return str(duty.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
        prev_bound = up_to
    lower = tiers[-2][0] if len(tiers) > 1 else Decimal("0")
    base = min(tiers[-1][1] + (amount - lower) * tiers[-1][2] / Decimal("100"), Decimal("900000"))
    duty = base * share / Decimal("100")
    return str(duty.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def state_duty_order(total_claim: str) -> str:
    """Госпошлина за судебный приказ: доля от пошлины имущественного иска.

    Шкала по умолчанию — пп. 1 п. 1 ст. 333.19 НК РФ (в ред. Федерального
    закона от 08.08.2024 № 259-ФЗ, с 08.09.2024): до 100 000 руб. —
    4 000 руб.; 100 001–300 000 — 4 000 руб. + 3 % суммы свыше 100 000;
    300 001–500 000 — 10 000 руб. + 2,5 % суммы свыше 300 000; приказное
    производство — 50 % от указанной суммы (пп. 2 п. 1 ст. 333.19 НК РФ).
    Шкала и доля приказного читаются из редактируемого файла amirs_fees.json
    рядом с программой: при индексации ставок достаточно поправить числа,
    EXE пересобирать не нужно.
    """
    amount = _dec(total_claim)
    if amount <= 0:
        return "0.00"
    share, tiers = load_fee_scale()
    return _state_duty_from_scale(amount, share, tiers)


@dataclass
class GroundFinding:
    """Вывод одного правила скрининга по ст. 125 ГПК РФ."""
    kind: str      # "return" | "refuse" | "manual" | "note"
    rule: str      # код правила: cat/limit/country/docs/duty/lgota/sign/dispute/dup/form124
    ref: str       # ссылка на норму, напр. «п. 1 ч. 1 ст. 125 ГПК РФ»
    text: str      # описание по-человечески


# Краткие названия оснований для вкладки «Статистика» и экспорта в Excel:
# (шифр правила, вид основания) -> название. Статистика группирует заявления
# по существу основания — без сумм пошлины, стран и прочих переменных
# подробностей (они остаются в журнале скрининга и в книге Excel).
GROUND_TITLES: Dict[Tuple[str, str], str] = {
    # возвращение (ч. 1 ст. 125, п. 4 ч. 1 ст. 135 ГПК РФ)
    ("docs", "return"):
        "не представлены документы, подтверждающие заявленное требование",
    ("duty", "return"):
        "госпошлина не оплачена либо уплачена не в полном размере",
    ("form124", "return"):
        "не соблюдены требования к форме и содержанию заявления (ст. 124 ГПК РФ)",
    ("sign", "return"):
        "заявление не подписано либо подписано лицом, не имеющим полномочий "
        "на его подписание и подачу",
    # отказ в принятии (ч. 3 ст. 125, ст. 134 ГПК РФ)
    ("cat", "refuse"):
        "заявлено требование, не предусмотренное ст. 122 ГПК РФ",
    ("limit", "refuse"):
        "сумма требования превышает предел приказного производства 500 000 руб.",
    ("country", "refuse"):
        "место жительства (нахождения) должника вне пределов Российской Федерации",
    # вопросы для ручной проверки помощника (судьи)
    ("cat", "manual"):
        "категория требования не указана или не распознана (ст. 122 ГПК РФ)",
    ("country", "manual"):
        "не указана страна постоянного проживания (нахождения) должника",
    ("duty", "manual"):
        "не подтверждена оплата государственной пошлины",
    ("lgota", "manual"):
        "заявлена льгота по госпошлине — проверить основание освобождения "
        "(ст. 333.36 НК РФ)",
    ("dispute", "manual"):
        "отмечены признаки спора о праве (п. 3–4 Пленума ВС РФ № 62)",
    ("dup", "manual"):
        "возможный дубликат ранее принятого заявления — сверить с делами "
        "участка в АМИРС",
}

# Фразы-опознаватели в текстах оснований (порядок важен: сначала самые
# характерные). По ним шифр правила восстанавливается для строк журнала,
# где хранится только «норма: текст».
_GROUND_TEXT_HINTS: List[Tuple[str, str]] = [
    ("не соответствуют ст. 124", "form124"),
    ("превышает предел приказного производства", "limit"),
    ("заявлено требование, не предусмотренное ст. 122", "cat"),
    ("не указана категория требования", "cat"),
    ("категория_требования", "cat"),
    ("не распознана", "cat"),
    ("вне пределов российской федерации", "country"),
    ("не указана страна", "country"),
    ("не представлены документы", "docs"),
    ("не подписано", "sign"),
    ("подписано представителем", "sign"),
    ("не имеющим полномочий", "sign"),
    ("не отмечено подписание", "sign"),
    ("госпошлина уплачена не в полном размере", "duty"),
    ("не подтверждена оплата госпошлины", "duty"),
    ("льгота по госпошлине", "lgota"),
    ("признаки спора о праве", "dispute"),
    ("возможный дубликат", "dup"),
]


def _ground_code_from_text(text: str) -> str:
    """Восстанавливает шифр правила по тексту основания из журнала.

    Тексты оснований генерируются программой и содержат устойчивые фразы,
    поэтому шифр восстанавливается по подстроке — в том числе для строк
    журнала старых версий. Возвращает "" , если фраза не опознана.
    """
    low = str(text or "").lower()
    for hint, code in _GROUND_TEXT_HINTS:
        if hint in low:
            return code
    return ""


@dataclass
class ScreeningEntry:
    """Результат проверки одного заявления по ст. 125 ГПК РФ."""
    row: int
    claimant: str
    fio: str
    total: str                          # сумма требования (долг + пени), «1234.56»
    category: str = ""
    category_matched: bool = False
    birth_date: str = ""
    address: str = ""
    requirement: str = ""
    identifier: str = "идентификатор не указан"
    duty_required: str = "0.00"
    duty_paid: str = ""
    verdict: str = V_MANUAL
    findings: List[GroundFinding] = field(default_factory=list)
    received: str = ""                  # дата поступления, ДД.ММ.ГГГГ
    docs: Optional[DocCheckResult] = None   # анализ приложений (v3.6), если включён


def _finalize_verdict(entry: ScreeningEntry) -> ScreeningEntry:
    """Итоговый вердикт: отказ > возврат > ручная проверка > в приказ."""
    kinds = {f.kind for f in entry.findings}
    if "refuse" in kinds:
        entry.verdict = V_REFUSE
    elif "return" in kinds:
        entry.verdict = V_RETURN
    elif "manual" in kinds:
        entry.verdict = V_MANUAL
    else:
        entry.verdict = V_OK
    return entry


def screen_single(rec: Dict[str, str], control: Dict[str, str],
                  control_present: Dict[str, bool],
                  duplicate: bool = False,
                  docs: Optional[DocCheckResult] = None) -> ScreeningEntry:
    """Проверяет одно заявление по основаниям ст. 125 ГПК РФ.

    rec — запись реестра (из process_registry); control — значения контрольных
    столбцов строки «как есть» (без чистки заглушек: «нет» — значимое значение);
    control_present — какие контрольные столбцы есть в файле; duplicate —
    возможный дубликат внутри реестра.
    """
    debt, penalty = _dec(rec.get("debt")), _dec(rec.get("penalty"))
    total = str((debt + penalty).quantize(Decimal("0.01")))
    entry = ScreeningEntry(
        row=int(rec.get("row") or 0),
        claimant=rec.get("claimant") or "—",
        fio=rec.get("fio") or "—",
        total=total,
        birth_date=rec.get("birth_date") or "",
        address=rec.get("address") or "",
        requirement=_requirement_text(rec),
        identifier=_identifier_text(rec),
        received=parse_date_value(control.get("Дата_Поступления")) or "",
    )

    # 1. Категория требования (ст. 122 ГПК РФ)
    if not control_present.get("Категория_Требования"):
        entry.findings.append(GroundFinding(
            "manual", "cat", "ст. 122 ГПК РФ",
            "в реестре нет контрольного столбца «Категория_Требования» — "
            "дополните реестр по шаблону (кнопка «Создать шаблон Excel»)"))
    elif not str(control.get("Категория_Требования") or "").strip():
        entry.findings.append(GroundFinding(
            "manual", "cat", "ст. 122 ГПК РФ",
            "не указана категория требования — выберите из списка (ст. 122 ГПК РФ)"))
    else:
        matched = match_st122_category(control.get("Категория_Требования"))
        entry.category = matched or str(control.get("Категория_Требования")).strip()
        entry.category_matched = bool(matched)
        if matched == CATEGORY_OTHER:
            entry.findings.append(GroundFinding(
                "refuse", "cat", "п. 1 ч. 3 ст. 125 ГПК РФ",
                "заявлено требование, не предусмотренное ст. 122 ГПК РФ"))
        elif matched:
            entry.findings.append(GroundFinding(
                "note", "cat", "ст. 122 ГПК РФ", f"категория требования: {matched}"))
        else:
            entry.findings.append(GroundFinding(
                "manual", "cat", "ст. 122 ГПК РФ",
                f"категория «{entry.category}» не распознана — выберите формулировку "
                "из списка (лист «Инструкция» шаблона)"))

    # 2. Предел приказного производства (ч. 1 ст. 121 ГПК РФ; п. 21 Пленума № 62)
    if debt + penalty > Decimal(ORDER_LIMIT):
        entry.findings.append(GroundFinding(
            "refuse", "limit",
            "п. 1 ч. 3 ст. 125 ГПК РФ, п. 21 постановления Пленума ВС РФ от 27.12.2016 № 62",
            f"сумма требования {_rub_plain(total)} руб. превышает предел приказного "
            "производства 500 000 руб. (ч. 1 ст. 121 ГПК РФ)"))

    # 3. Место жительства должника (п. 2 ч. 3 ст. 125 ГПК РФ)
    if control_present.get("Страна_Должника"):
        country = str(control.get("Страна_Должника") or "").strip()
        if not country:
            entry.findings.append(GroundFinding(
                "manual", "country", "п. 2 ч. 3 ст. 125 ГПК РФ",
                "не указана страна постоянного проживания (нахождения) должника"))
        elif not _is_rf(country):
            entry.findings.append(GroundFinding(
                "refuse", "country", "п. 2 ч. 3 ст. 125 ГПК РФ",
                f"место жительства (нахождения) должника вне пределов Российской "
                f"Федерации ({country})"))

    # 4. Документы, подтверждающие требование (п. 1 ч. 1 ст. 125 ГПК РФ).
    # С v3.6 программа может сама читать файлы-приложения (папка на заявление):
    # результат анализа файлов приоритетнее ручной отметки в реестре.
    entry.docs = docs
    if docs is not None:
        if not docs.matched:
            entry.findings.append(GroundFinding(
                "manual", "docs", "п. 1 ч. 1 ст. 125 ГПК РФ",
                "папка с приложениями к заявлению не найдена — проверить "
                "комплектность вручную"))
        elif docs.missing:
            if docs.manual_files:
                # в папке есть файлы, из которых текст не извлечён (сканы, испорченные):
                # автоматический «возврат» был бы несправедлив — ручная сверка
                extra = (f", и ещё {len(docs.manual_files) - 3}"
                         if len(docs.manual_files) > 3 else "")
                entry.findings.append(GroundFinding(
                    "manual", "docs", "п. 1 ч. 1 ст. 125 ГПК РФ",
                    "не распознано по тексту: " + docs.missing_text
                    + "; в папке есть файлы без распознанного текста (сканы): "
                    + ", ".join(docs.manual_files[:3]) + extra
                    + " — сверить комплектность вручную"))
            else:
                entry.findings.append(GroundFinding(
                    "return", "docs", "п. 1 ч. 1 ст. 125 ГПК РФ",
                    "не представлены документы, подтверждающие заявленное требование "
                    "— в приложениях не распознано: " + docs.missing_text))
        elif (control_present.get("Документы_Приложены")
              and _yn(control.get("Документы_Приложены")) == "no"):
            entry.findings.append(GroundFinding(
                "manual", "docs", "п. 1 ч. 1 ст. 125 ГПК РФ",
                "в реестре отмечено «документы не приложены», но в приложениях "
                "распознаны: " + docs.found_text + " — сверить вручную"))
        else:
            entry.findings.append(GroundFinding(
                "note", "docs", "п. 1 ч. 1 ст. 125 ГПК РФ",
                f"приложено файлов: {len(docs.files)}; распознано по тексту: "
                f"{docs.found_text}" + (f"; {docs.note}" if docs.note else "")))
    elif control_present.get("Документы_Приложены"):
        state = _yn(control.get("Документы_Приложены"))
        if state == "no":
            entry.findings.append(GroundFinding(
                "return", "docs", "п. 1 ч. 1 ст. 125 ГПК РФ",
                "не представлены документы, подтверждающие заявленное требование"))
        elif state == "yes":
            entry.findings.append(GroundFinding(
                "note", "docs", "п. 1 ч. 1 ст. 125 ГПК РФ",
                "документы, подтверждающие требование, приложены"))
        else:
            entry.findings.append(GroundFinding(
                "manual", "docs", "п. 1 ч. 1 ст. 125 ГПК РФ",
                "не отмечено наличие документов, подтверждающих требование"))

    # 5. Подпись и полномочия подписанта (п. 4 ч. 1 ст. 135 ГПК РФ)
    if control_present.get("Заявление_Подписано"):
        sign_state = _yn(control.get("Заявление_Подписано"))
        trust_state = _yn(control.get("Доверенность_Есть"))
        if sign_state == "no":
            entry.findings.append(GroundFinding(
                "return", "sign", "п. 4 ч. 1 ст. 135 ГПК РФ",
                "заявление не подписано либо подписано и подано лицом, не имеющим "
                "полномочий на его подписание и подачу"))
        elif sign_state == "yes" and trust_state == "no":
            entry.findings.append(GroundFinding(
                "return", "sign", "п. 4 ч. 1 ст. 135 ГПК РФ",
                "заявление подписано представителем, полномочия не подтверждены "
                "(доверенность не приложена)"))
        elif sign_state == "yes":
            entry.findings.append(GroundFinding(
                "note", "sign", "ст. 135 ГПК РФ",
                "заявление подписано заявителем либо представителем "
                "с подтверждёнными полномочиями"))
        else:
            entry.findings.append(GroundFinding(
                "manual", "sign", "п. 4 ч. 1 ст. 135 ГПК РФ",
                "не отмечено подписание заявления заявителем (представителем)"))

    # 6. Государственная пошлина (п. 2 ч. 1 ст. 125; ст. 333.19, 333.36 НК РФ)
    exempt_basis = DUTY_EXEMPT.get(entry.category) if entry.category_matched else None
    duty_paid_raw = str(control.get("Оплачено_Пошлины") or "").strip()
    duty_paid = parse_amount(duty_paid_raw)
    entry.duty_paid = duty_paid if duty_paid is not None else duty_paid_raw
    lgota_yes = control_present.get("Льгота_Пошлина") and \
        _yn(control.get("Льгота_Пошлина")) == "yes"
    if exempt_basis:
        entry.duty_required = "0.00"
        entry.findings.append(GroundFinding(
            "note", "duty", exempt_basis,
            "заявитель освобождён от уплаты государственной пошлины"))
    elif lgota_yes:
        entry.duty_required = "0.00"
        entry.findings.append(GroundFinding(
            "manual", "lgota", "ст. 333.36 НК РФ",
            f"в реестре указана льгота по госпошлине («{control.get('Льгота_Пошлина')}») — "
            "проверьте основание освобождения"))
    else:
        entry.duty_required = state_duty_order(total)
        if control_present.get("Оплачено_Пошлины"):
            if duty_paid is None:
                if _yn(duty_paid_raw) in ("yes", "no"):
                    msg_duty = (
                        f"в поле «Оплачено_Пошлины» указано «{duty_paid_raw}» вместо суммы — "
                        f"укажите сумму в рублях (расчёт: {_rub_plain(entry.duty_required)} руб., "
                        "пп. 1–2 п. 1 ст. 333.19 НК РФ)"
                    )
                else:
                    msg_duty = (
                        f"не подтверждена оплата госпошлины — расчёт: "
                        f"{_rub_plain(entry.duty_required)} руб. "
                        "(пп. 1–2 п. 1 ст. 333.19 НК РФ)"
                    )
                entry.findings.append(GroundFinding(
                    "manual", "duty", "п. 2 ч. 1 ст. 125 ГПК РФ", msg_duty))
            elif Decimal(duty_paid) + Decimal("0.005") < Decimal(entry.duty_required):
                entry.findings.append(GroundFinding(
                    "return", "duty", "п. 2 ч. 1 ст. 125 ГПК РФ",
                    f"госпошлина уплачена не в полном размере: расчёт "
                    f"{_rub_plain(entry.duty_required)} руб., оплачено "
                    f"{_rub_plain(str(duty_paid))} руб."))
            else:
                entry.findings.append(GroundFinding(
                    "note", "duty", "п. 2 ч. 1 ст. 125 ГПК РФ",
                    f"госпошлина уплачена: {_rub_plain(str(duty_paid))} руб. "
                    f"(расчёт {_rub_plain(entry.duty_required)} руб.)"))

    # 7. Спор о праве (п. 3 ч. 3 ст. 125 ГПК РФ; п. 3–4 Пленума № 62)
    if control_present.get("Признаки_Спора"):
        state = _yn(control.get("Признаки_Спора"))
        if state == "yes":
            entry.findings.append(GroundFinding(
                "manual", "dispute", "п. 3 ч. 3 ст. 125 ГПК РФ",
                "отмечены признаки спора о праве — оценить по п. 3–4 постановления "
                "Пленума ВС РФ от 27.12.2016 № 62"))
        elif state == "no":
            entry.findings.append(GroundFinding(
                "note", "dispute", "п. 3 ч. 3 ст. 125 ГПК РФ",
                "признаков спора о праве не отмечено"))

    # 8. Возможный дубликат / тождественное требование (ст. 134 ГПК РФ)
    if duplicate:
        entry.findings.append(GroundFinding(
            "manual", "dup", "ст. 134 ГПК РФ",
            "возможный дубликат ранее принятого заявления — сверить с делами "
            "участка в АМИРС (тождественное требование)"))

    entry.findings.append(GroundFinding(
        "note", "final", "ст. 126, 127 ГПК РФ",
        "решение о вынесении судебного приказа принимает мировой судья"))
    return _finalize_verdict(entry)


def _read_control_columns(excel_path: str):
    """Читает контрольные столбцы скрининга из реестра.

    Возвращает (какие_столбцы_есть, {строка: {столбец: значение}},
    все_строки, {название_столбца: номер}). Значения читаются «как есть»:
    для ст. 125 «нет» — значимое значение, заглушки не чистятся.
    """
    rows, error = read_xlsx_native(excel_path)
    if error or not rows:
        return {}, {}, [], {}
    header_idx = find_header_row(rows)
    if header_idx is None:
        return {}, {}, rows, {}
    col_of = {normalize_header(v): c for c, v in rows[header_idx]["cells"].items()}
    present = {name: normalize_header(name) in col_of for name in SCREENING_COLUMNS}
    by_row: Dict[int, Dict[str, str]] = {}
    for row in rows[header_idx + 1:]:
        values = {}
        for name in SCREENING_COLUMNS:
            col = col_of.get(normalize_header(name))
            if col is not None:
                values[name] = str(row["cells"].get(col, "")).strip()
        if any(values.values()):
            by_row[row["row"]] = values
    return present, by_row, rows, col_of


@dataclass
class ScreeningResult:
    """Итог скрининга реестра по ст. 125 ГПК РФ."""
    folder: str
    files: List[str] = field(default_factory=list)
    total: int = 0
    ok_count: int = 0
    return_count: int = 0
    refuse_count: int = 0
    manual_count: int = 0
    rejected: int = 0
    warning_count: int = 0
    warnings_log_path: str = ""
    log_path: str = ""
    workbook_path: str = ""
    journal_path: str = ""
    entries: List[ScreeningEntry] = field(default_factory=list)


# Журнал скрининга дописывают и фоновый воркер (пакетный скрининг), и
# экспресс-проверка в главном потоке. Без лока их записи могут перемешаться
# на границе буфера файла — строки CSV (источник вкладки «Статистика»)
# окажутся испорченными. Лок охватывает и определение is_new: иначе два
# потока одновременно увидят «файла нет» и каждый запишет строку заголовка.
_journal_lock = threading.Lock()


def _append_screening_rows(journal_path: str,
                           rows: List[Dict[str, str]]) -> str:
    """Дописывает строки скрининга в screening_journal.csv (создаёт при первом запуске)."""
    if not rows:
        return ""
    buffer = io.StringIO()
    writer = csv.DictWriter(buffer, fieldnames=SCREENING_LOG_FIELDS,
                            delimiter=";", extrasaction="ignore")
    try:
        with _journal_lock:
            is_new = not os.path.exists(journal_path)
            if is_new:
                writer.writeheader()
            writer.writerows(rows)
            os.makedirs(os.path.dirname(journal_path) or ".", exist_ok=True)
            with open(journal_path, "a", encoding="utf-8-sig" if is_new else "utf-8",
                      newline="") as fh:
                fh.write(buffer.getvalue())
    except OSError as exc:
        app_log(f"Журнал скрининга не обновлён: {exc}")
        return ""
    return journal_path


def read_screening_journal(journal_path: Optional[str] = None) -> List[Dict[str, str]]:
    """Читает журнал скрининга (вкладка «Статистика» и экспорт) из защищенного профиля."""
    path = journal_path or screening_journal_path()
    if not os.path.isfile(path):
        return []
    try:
        with open(path, "r", encoding="utf-8-sig") as fh:
            return [dict(r) for r in csv.DictReader(fh, delimiter=";")
                    if any((v or "").strip() for v in r.values())]
    except (OSError, csv.Error) as exc:
        app_log(f"Журнал скрининга не прочитан: {exc}")
        return []


# Периоды для вкладки «Статистика» (выпадающий список).
STATS_PERIOD_OPTIONS = ("Всё время", "Текущая неделя", "Текущий месяц",
                        "Текущий год", "Прошлый год", "Произвольный период")


def period_bounds(choice: str, today: Optional[date] = None
                  ) -> Tuple[Optional[date], Optional[date]]:
    """Границы периода (от, до) включительно по названию периода.

    Для «Всё время» и «Произвольный период» возвращает (None, None) —
    во втором случае границы берутся из полей «с»/«по» на вкладке.
    """
    today = today or date.today()
    if choice == "Текущая неделя":
        monday = today - timedelta(days=today.weekday())
        return monday, today
    if choice == "Текущий месяц":
        return today.replace(day=1), today
    if choice == "Текущий год":
        return date(today.year, 1, 1), today
    if choice == "Прошлый год":
        return date(today.year - 1, 1, 1), date(today.year - 1, 12, 31)
    return None, None


def filter_journal_rows(rows: List[Dict[str, str]],
                        date_from: Optional[date] = None,
                        date_to: Optional[date] = None) -> List[Dict[str, str]]:
    """Оставляет строки журнала скрининга в периоде [от, до] включительно.

    Дата берётся из столбца «Дата_время» (момент скрининга). При включённом
    периоде строки без разобранной даты отбрасываются; без периода
    возвращаются все строки как есть.
    """
    if date_from is None and date_to is None:
        return list(rows)
    kept: List[Dict[str, str]] = []
    for r in rows:
        m = re.match(r"(\d{4})-(\d{2})-(\d{2})", str(r.get("Дата_время") or ""))
        if not m:
            continue
        try:
            d = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        except ValueError:
            continue
        if date_from is not None and d < date_from:
            continue
        if date_to is not None and d > date_to:
            continue
        kept.append(r)
    return kept


def claimant_history(journal_path: Optional[str] = None,
                     top: int = 30) -> List[Dict[str, str]]:
    """Частые взыскатели из журнала скрининга — для «умной формы».

    Возвращает список словарей {«взыскатель», «категория», «заявок»},
    отсортированный по числу заявлений (частые — первыми). У каждого
    взыскателя подставляется самая частая его категория ст. 122 (значение
    «не указана» не учитывается). Источник — screening_journal.csv:
    вести справочник вручную не нужно, список пополняется сам по мере
    работы. Используется экспресс-проверкой одного заявления.
    """
    agg: Dict[str, Dict[str, object]] = {}
    for row in read_screening_journal(journal_path):
        name = (row.get("Взыскатель") or "").strip()
        if not name:
            continue
        cat = (row.get("Категория_122") or "").strip()
        if cat in ("", "не указана"):
            cat = ""
        info = agg.setdefault(name, {"cats": {}, "count": 0})
        info["count"] = int(info["count"]) + 1
        if cat:
            cats: Dict[str, int] = info["cats"]  # порядок вставки = хронология
            cats[cat] = cats.get(cat, 0) + 1
    result: List[Dict[str, str]] = []
    for name, info in agg.items():
        cats: Dict[str, int] = info["cats"]
        cat, best = "", 0
        for c, n in cats.items():
            if n > best:
                best, cat = n, c
        result.append({"взыскатель": name, "категория": cat,
                       "заявок": str(info["count"])})
    result.sort(key=lambda item: (-int(item["заявок"]), item["взыскатель"]))
    return result[:max(1, top)]


# ---------------------------------------------------------------------------
# Накопительный реестр заявок (v3.5): проверенные экспресс-заявления копятся
# в claims_registry.csv и одной кнопкой уходят в АМИРС готовым XML-пакетом.
# ---------------------------------------------------------------------------

def claims_registry_path() -> str:
    """Файл накопительного реестра в защищенном профиле пользователя."""
    return os.path.join(_protected_user_data_dir(), CLAIMS_REGISTRY_NAME)


_claims_lock = threading.Lock()


def read_claims_registry(path: Optional[str] = None,
                         strict: bool = False) -> List[Dict[str, str]]:
    """Читает накопительный реестр (список словарей по CLAIMS_FIELDS).

    При strict=True (используется всеми операциями модификации реестра)
    ошибка чтения существующего файла вызывает ConversionError, чтобы
    исключить перезапись и потерю ранее накопленных заявок.
    """
    target = path or claims_registry_path()
    if not os.path.exists(target):
        return []
    try:
        with open(target, "r", encoding="utf-8-sig") as fh:
            rows = [dict(r) for r in csv.DictReader(fh, delimiter=";")
                    if any((v or "").strip() for v in r.values())]
    except (OSError, csv.Error, UnicodeDecodeError) as exc:
        app_log(f"Накопительный реестр не прочитан: {exc}")
        if strict:
            raise ConversionError(
                f"Не удалось прочитать накопительный реестр ({os.path.basename(target)}): {exc}. "
                "Закройте файл в других программах (например, Excel) и повторите попытку."
            ) from exc
        return []
    for row in rows:  # новые колонки у старых файлов не должны ломать программу
        for name in CLAIMS_FIELDS:
            row.setdefault(name, "")
    return rows


def _rewrite_claims_registry(rows: List[Dict[str, str]],
                             path: Optional[str] = None,
                             strict: bool = False) -> str:
    """Атомарно перезаписывает накопительный реестр через временный файл и резервную копию .bak."""
    target = path or claims_registry_path()
    buffer = io.StringIO()
    writer = csv.DictWriter(buffer, fieldnames=CLAIMS_FIELDS, delimiter=";",
                            extrasaction="ignore")
    writer.writeheader()
    writer.writerows(rows)
    payload = buffer.getvalue()
    target_dir = os.path.dirname(os.path.abspath(target)) or "."
    tmp_path = ""
    try:
        os.makedirs(target_dir, exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(
            prefix=".claims_tmp_", suffix=".csv", dir=target_dir
        )
        os.close(fd)
        with open(tmp_path, "w", encoding="utf-8-sig", newline="") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        if os.path.isfile(target):
            try:
                shutil.copy2(target, target + ".bak")
            except OSError:
                pass
        os.replace(tmp_path, target)
        tmp_path = ""
    except OSError as exc:
        app_log(f"Накопительный реестр не сохранён: {exc}")
        if strict:
            raise ConversionError(
                f"Не удалось сохранить накопительный реестр ({os.path.basename(target)}): {exc}"
            ) from exc
        return ""
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except OSError:
                pass
    return target


def _read_claim_seq(target: str, use_global_settings: bool) -> int:
    """Читает последний выданный номер заявки (из .seq-файла и настроек)."""
    max_seq = 0
    seq_path = target + ".seq"
    if os.path.isfile(seq_path):
        try:
            with open(seq_path, "r", encoding="utf-8") as fh:
                digits = re.sub(r"\D", "", fh.read())
                if digits:
                    max_seq = max(max_seq, int(digits))
        except OSError as exc:
            app_log(f"Не удалось прочитать счётчик ID ({seq_path}): {exc}")
    if use_global_settings:
        try:
            val = int(load_app_settings().get("last_claim_id", 0) or 0)
            max_seq = max(max_seq, val)
        except (TypeError, ValueError):
            pass
    return max_seq


def _write_claim_seq(target: str, last_no: int, use_global_settings: bool) -> None:
    """Сохраняет последний выданный номер заявки для исключения повторной выдачи ID."""
    seq_path = target + ".seq"
    try:
        os.makedirs(os.path.dirname(os.path.abspath(seq_path)) or ".", exist_ok=True)
        with open(seq_path, "w", encoding="utf-8") as fh:
            fh.write(str(int(last_no)))
    except OSError as exc:
        app_log(f"Не удалось сохранить счётчик ID ({seq_path}): {exc}")
    if use_global_settings:
        try:
            cfg = load_app_settings()
            if int(cfg.get("last_claim_id", 0) or 0) < last_no:
                cfg["last_claim_id"] = int(last_no)
                save_app_settings(cfg)
        except Exception as exc:
            app_log(f"Не удалось обновить last_claim_id в настройках: {exc}")


def append_claim_rows(rows: List[Dict[str, str]],
                      path: Optional[str] = None) -> List[str]:
    """Добавляет заявки в накопительный реестр с монотонным ID; возвращает присвоенные ID."""
    if not rows:
        return []
    target = path or claims_registry_path()
    use_global = path is None
    with _claims_lock:
        existing = read_claims_registry(target, strict=True)
        last_issued = _read_claim_seq(target, use_global)
        for row in existing:
            digits = re.sub(r"\D", "", str(row.get("ID") or ""))
            if digits:
                last_issued = max(last_issued, int(digits))
        next_no = last_issued + 1
        assigned = []
        for row in rows:
            row = dict(row)
            if "ID" not in row or not str(row["ID"]).strip():
                row["ID"] = f"З-{next_no:06d}"
            digits = re.sub(r"\D", "", str(row["ID"]))
            if digits:
                next_no = max(next_no, int(digits) + 1)
            assigned.append(row["ID"])
            row.setdefault("Статус", CR_NEW)
            existing.append(row)
        _rewrite_claims_registry(existing, target, strict=True)
        _write_claim_seq(target, next_no - 1, use_global)
        return assigned


def update_claim_rows(ids: List[str], patch: Dict[str, str],
                      path: Optional[str] = None) -> int:
    """Обновляет поля заявок по списку ID; возвращает число изменённых строк."""
    if not ids:
        return 0
    wanted = {str(i) for i in ids}
    with _claims_lock:
        rows = read_claims_registry(path, strict=True)
        changed = 0
        for row in rows:
            if row.get("ID") in wanted:
                row.update(patch)
                changed += 1
        if changed:
            _rewrite_claims_registry(rows, path, strict=True)
        return changed


def remove_claim_rows(ids: List[str], path: Optional[str] = None) -> int:
    """Удаляет заявки по списку ID; возвращает число удалённых строк."""
    if not ids:
        return 0
    wanted = {str(i) for i in ids}
    with _claims_lock:
        rows = read_claims_registry(path, strict=True)
        kept = [row for row in rows if row.get("ID") not in wanted]
        removed = len(rows) - len(kept)
        if removed:
            _rewrite_claims_registry(kept, path, strict=True)
        return removed


PII_CLAIMS_FIELDS = (
    "Должник", "Дата_рождения", "Место_рождения", "Адрес",
    "СНИЛС", "ИНН", "Паспорт", "Лицевой_счет"
)


def purge_exported_personal_data(sent_ids: Optional[List[str]] = None,
                                 exported_fios: Optional[List[str]] = None,
                                 registry_path: Optional[str] = None,
                                 journal_path: Optional[str] = None,
                                 source_file: Optional[str] = None,
                                 exported_rows: Optional[List[int]] = None) -> int:
    """Автоматически удаляет персональные данные из накопительного реестра
    (claims_registry.csv) и журналов скрининга (screening_journal.csv) после
    выгрузки XML-пакета в ПИ «АМИРС».

    В накопительном реестре очистка выполняется СТРОГО по уникальному ID
    отправленной заявки (sent_ids) и статусу CR_SENT, чтобы не затронуть
    неотправленные заявления однофамильцев или того же должника по другим периодам.
    """
    purged_count = 0
    wanted_ids = {str(i) for i in (sent_ids or []) if i}
    journal_fios: set = set()
    if not wanted_ids and exported_fios:
        journal_fios = {str(f).strip().lower() for f in (exported_fios or [])
                        if f and str(f).strip() not in ("", "—")}
    wanted_row_nums = {str(int(r)) for r in (exported_rows or []) if r}

    reg_target = registry_path or claims_registry_path()
    if os.path.isfile(reg_target) and wanted_ids:
        with _claims_lock:
            rows = read_claims_registry(reg_target, strict=False)
            changed = False
            still_pending_fios: set = set()
            purged_claim_fios: set = set()
            for row in rows:
                cid = str(row.get("ID") or "")
                fio_low = str(row.get("Должник") or "").strip().lower()
                if (cid and cid in wanted_ids) or row.get("Статус") == CR_SENT:
                    if row.get("Должник") not in ("", "[ПДн удалены после выгрузки в АМИРС]"):
                        if fio_low and fio_low != "—":
                            purged_claim_fios.add(fio_low)
                        for field_name in PII_CLAIMS_FIELDS:
                            row[field_name] = ""
                        row["Должник"] = "[ПДн удалены после выгрузки в АМИРС]"
                        changed = True
                        purged_count += 1
                else:
                    if fio_low and fio_low not in ("", "—", "[пдн удалены после выгрузки в амирс]"):
                        still_pending_fios.add(fio_low)
            if changed:
                _rewrite_claims_registry(rows, reg_target, strict=False)
            journal_fios.update(purged_claim_fios - still_pending_fios)

    j_target = journal_path or screening_journal_path()
    if os.path.isfile(j_target) and (journal_fios or wanted_row_nums):
        with _journal_lock:
            j_rows = read_screening_journal(j_target)
            j_changed = False
            for r in j_rows:
                jfio = str(r.get("Должник") or "").strip().lower()
                jfile = str(r.get("Файл") or "").strip()
                jrow = str(r.get("Строка") or "").strip()
                match_by_row = bool(source_file and jfile == source_file
                                    and wanted_row_nums and jrow in wanted_row_nums)
                match_by_fio = bool(jfio in journal_fios and (
                    not source_file or jfile in (source_file, "экспресс-проверка")
                ))
                if (match_by_row or match_by_fio) and r.get("Должник") != "[ПДн удалены]":
                    r["Должник"] = "[ПДн удалены]"
                    j_changed = True
            if j_changed:
                buffer = io.StringIO()
                writer = csv.DictWriter(buffer, fieldnames=SCREENING_LOG_FIELDS,
                                        delimiter=";", extrasaction="ignore")
                writer.writeheader()
                writer.writerows(j_rows)
                try:
                    with open(j_target, "w", encoding="utf-8-sig", newline="") as fh:
                        fh.write(buffer.getvalue())
                except OSError as exc:
                    app_log(f"Не удалось обезличить журнал скрининга: {exc}")

    if purged_count:
        app_log(f"ЗАЩИТА ПДн: персональные данные автоматически удалены для {purged_count} записей")
    return purged_count


def _parse_identifier(raw: str) -> tuple:
    """«СНИЛС или ИНН» одним полем -> (вид, значение, предупреждение).

    11 цифр — СНИЛС, 12 цифр — ИНН (контрольное число проверяется).
    Иначе ("", "", подсказка).
    """
    digits = only_digits(raw)
    if len(digits) == 11:
        value, warning = check_snils(digits)
        return ("snils", value, warning)
    if len(digits) == 12:
        value, warning = check_inn(digits)
        return ("inn", value, warning)
    hint = "" if not digits else f"в номере {len(digits)} цифр — нужно 11 (СНИЛС) или 12 (ИНН)"
    return ("", "", hint)


def claim_missing_data(row: Dict[str, str]) -> List[str]:
    """Чего не хватает заявке для XML-пакета по ст. 124 ГПК РФ (список/пусто)."""
    missing: List[str] = []
    if not (row.get("Взыскатель") or "").strip():
        missing.append("взыскатель")
    if not (row.get("Должник") or "").strip():
        missing.append("ФИО должника")
    if not parse_date_value(row.get("Дата_рождения")):
        missing.append("дата рождения")
    if not (row.get("Место_рождения") or "").strip():
        missing.append("место рождения")
    if not (row.get("Адрес") or "").strip():
        missing.append("адрес регистрации")
    snils_raw = only_digits(row.get("СНИЛС"))
    inn_raw = only_digits(row.get("ИНН"))
    snils = validate_snils(row.get("СНИЛС"))
    inn = validate_inn(row.get("ИНН"))
    passport = validate_passport(row.get("Паспорт"))
    if not (snils or inn or passport):
        if len(snils_raw) == 11:
            missing.append("СНИЛС не проходит контрольное число — проверьте номер")
        elif len(inn_raw) == 12:
            missing.append("ИНН не проходит контрольное число — проверьте номер")
        else:
            missing.append("идентификатор: СНИЛС, ИНН или паспорт")
    raw_pen = str(row.get("Пени") or "").strip()
    pen_amt = parse_amount(raw_pen) if raw_pen else "0.00"
    if raw_pen and pen_amt is None:
        missing.append("сумма пени должна быть неотрицательным числом")
    raw_duty = str(row.get("Пошлина_оплачено") or "").strip()
    duty_amt = parse_amount(raw_duty) if raw_duty else "0.00"
    if raw_duty and duty_amt is None:
        missing.append("сумма оплаченной пошлины должна быть неотрицательным числом")
    debt = parse_amount(row.get("Сумма_долга"))
    if debt is None:
        missing.append("сумма долга числом")
    else:
        penalty = pen_amt or "0.00"
        if Decimal(debt) + Decimal(penalty) <= 0:
            missing.append("сумма требования больше нуля")
    return missing


def claim_display_status(row: Dict[str, str]) -> str:
    """Человекочитаемый статус карточки для таблицы реестра."""
    if row.get("Статус") == CR_SENT:
        return "Отправлено"
    verdict = row.get("Вердикт") or ""
    if verdict in (V_RETURN, V_REFUSE, V_MANUAL):
        return verdict
    if claim_missing_data(row):
        return "Дозаполнить"
    return "Готов к отправке"


@dataclass
class ClaimsSendResult:
    """Итог отправки накопительного реестра в АМИРС."""
    xml_path: str = ""
    sent_ids: List[str] = field(default_factory=list)
    problems: List[Dict[str, str]] = field(default_factory=list)  # не отправлено
    warnings: List[Dict[str, str]] = field(default_factory=list)  # отправлено с пометкой
    skipped_verdict: int = 0   # не отправлено: возврат/отказ/на проверку
    already_sent: int = 0      # не отправлено: уже в более раннем пакете
    total: int = 0


def send_claims_to_amirs(court_code: str, xml_path: str,
                         rows: Optional[List[Dict[str, str]]] = None,
                         mark_sent: bool = True,
                         path: Optional[str] = None) -> ClaimsSendResult:
    """Формирует XML-пакет АМИРС из готовых заявок накопительного реестра.

    Отправляются заявки со статусом «Проверено» и вердиктом «В ПРИКАЗ», у
    которых хватает данных по ст. 124 ГПК РФ. Остальные остаются в реестре:
    возвраты/отказы — потому что приказ по ним не выносится, недозаполненные —
    потому что АМИРС такое не примет (список проблем возвращается в результате).
    mark_sent=True — пометить отправленные (статус «Отправлено»).
    """
    result = ClaimsSendResult()
    all_rows = read_claims_registry(path) if rows is None else rows
    result.total = len(all_rows)
    court_code = str(court_code or "").strip().upper() or DEFAULT_COURT_CODE

    records: List[Dict[str, str]] = []
    seen: Dict[str, str] = {}
    for row in all_rows:
        if row.get("Статус") == CR_SENT:
            result.already_sent += 1
            continue
        verdict = row.get("Вердикт") or ""
        if verdict in (V_RETURN, V_REFUSE, V_MANUAL):
            result.skipped_verdict += 1
            continue
        cid = row.get("ID") or ""
        who = row.get("Должник") or "—"

        missing = claim_missing_data(row)
        if missing:
            result.problems.append({"ID": cid, "Должник": who,
                                    "Проблема": "не хватает: " + ", ".join(missing)})
            continue

        debt = parse_amount(row.get("Сумма_долга")) or "0.00"
        penalty = parse_amount(row.get("Пени")) or "0.00"
        duty_paid = parse_amount(row.get("Пошлина_оплачено")) or "0.00"
        snils, snils_warn = check_snils(row.get("СНИЛС"))
        inn, inn_warn = check_inn(row.get("ИНН"))
        ident_warn = snils_warn or inn_warn
        if ident_warn:
            result.problems.append({
                "ID": cid, "Должник": who,
                "Проблема": f"{ident_warn} — исправьте или укажите другой идентификатор"})
            continue

        dedup_key = f"{(row.get('Должник') or '').lower()}|{(row.get('Лицевой_счет') or '').strip()}|{debt}"
        if dedup_key in seen:
            # как и в мягком режиме конвертера: включаем, но предупреждаем —
            # тождественное требование (ст. 134 ГПК РФ) надо сверить в АМИРС
            result.warnings.append({
                "ID": cid, "Должник": who,
                "Предупреждение": f"возможный дубликат заявки {seen[dedup_key]} — "
                                  "сверьте, тождественное требование (ст. 134 ГПК РФ)"})
        else:
            seen[dedup_key] = cid

        records.append({
            "id": cid,
            "account": clean_account_number(row.get("Лицевой_счет")),
            "claimant": xml_safe(row.get("Взыскатель") or ""),
            "fio": xml_safe(row.get("Должник") or ""),
            "birth_date": parse_date_value(row.get("Дата_рождения")) or "",
            "birth_place": xml_safe(row.get("Место_рождения") or ""),
            "address": xml_safe(row.get("Адрес") or ""),
            "snils": snils or "",
            "inn": inn or "",
            "passport": validate_passport(row.get("Паспорт")) or "",
            "period": xml_safe(row.get("Период") or ""),
            "subject": xml_safe(row.get("Существо_требования") or ""),
            "debt": debt,
            "penalty": penalty,
            "duty": duty_paid,
        })

    if not records:
        return result

    root = ET.Element("AmirsImportPackage", {
        "version": "2.0",
        "courtCode": court_code,
        "createDate": datetime.now().strftime("%Y-%m-%dT%H:%M:%S"),
        "sourceSystem": "Komi_Justice_AutoConverter",
    })
    orders_node = ET.SubElement(root, "CourtOrders")
    for rec in records:
        order_node = ET.SubElement(orders_node, "CourtOrderRecord")
        ET.SubElement(order_node, "AccountNumber").text = rec["account"]
        ET.SubElement(order_node, "ClaimantName").text = rec["claimant"]
        debtor_node = ET.SubElement(order_node, "Debtor")
        ET.SubElement(debtor_node, "FullName").text = rec["fio"]
        ET.SubElement(debtor_node, "BirthDate").text = rec["birth_date"]
        ET.SubElement(debtor_node, "BirthPlace").text = rec["birth_place"]
        ET.SubElement(debtor_node, "Address").text = rec["address"]
        if rec["snils"]:
            ET.SubElement(debtor_node, "SNILS").text = rec["snils"]
        if rec["inn"]:
            ET.SubElement(debtor_node, "INN").text = rec["inn"]
        if rec["passport"]:
            ET.SubElement(debtor_node, "Passport").text = rec["passport"]
        fin_node = ET.SubElement(order_node, "FinancialDetails")
        ET.SubElement(fin_node, "DebtPeriod").text = rec["period"]
        ET.SubElement(fin_node, "PrincipalDebt").text = rec["debt"]
        ET.SubElement(fin_node, "Penalty").text = rec["penalty"]
        ET.SubElement(fin_node, "StateDuty").text = rec["duty"]

    warnings: List[str] = []
    result.xml_path = _safe_write(_prettify_xml(root), xml_path, warnings)
    result.sent_ids = [rec["id"] for rec in records]
    if mark_sent and result.sent_ids:
        exported_fios = [rec["fio"] for rec in records if rec.get("fio")]
        update_claim_rows(result.sent_ids, {
            "Статус": CR_SENT,
            "Отправлено": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "Пакет": os.path.basename(xml_path),
        }, path=path)
        purge_exported_personal_data(
            sent_ids=result.sent_ids,
            exported_fios=exported_fios,
            registry_path=path,
        )
    return result


def _parse_ground_chunk(chunk: str) -> Optional[GroundFinding]:
    """«норма: описание» -> GroundFinding (для статистики из журнала)."""
    chunk = str(chunk or "").strip()
    if not chunk:
        return None
    ref, _, text = chunk.partition(": ")
    return GroundFinding("journal", "", ref.strip(), text.strip() or chunk)


def journal_to_entries(rows: List[Dict[str, str]]) -> List[ScreeningEntry]:
    """Восстанавливает записи для статистики из строк screening_journal.csv."""
    entries: List[ScreeningEntry] = []
    kind_map = [("Основания_возврата", "return"),
                ("Основания_отказа", "refuse"),
                ("Ручная_проверка", "manual")]
    for r in rows:
        dt = str(r.get("Дата_время") or "")
        received = ""
        m = re.match(r"(\d{4})-(\d{2})-\d{2}", dt)
        if m:
            received = f"01.{m.group(2)}.{m.group(1)}"
        entry = ScreeningEntry(
            row=0,
            claimant=r.get("Взыскатель") or "—",
            fio=r.get("Должник") or "—",
            total=str(parse_amount(r.get("Сумма_требования_руб")) or "0.00"),
            category=r.get("Категория_122") or "",
            category_matched=bool(r.get("Категория_122")),
            duty_required=r.get("Пошлина_расчет") or "0.00",
            duty_paid=r.get("Пошлина_оплачено") or "",
            verdict=r.get("Вердикт") or V_MANUAL,
            received=received,
        )
        for column, kind in kind_map:
            for chunk in str(r.get(column) or "").split("; "):
                finding = _parse_ground_chunk(chunk)
                if finding is not None:
                    finding.kind = kind
                    entry.findings.append(finding)
        entries.append(entry)
    return entries


def build_statistics_sections(entries: List[ScreeningEntry]) -> List[tuple]:
    """Секции статистики скрининга: [(заголовок, [шапка], [строки])].

    Используется вкладкой «Статистика», книгой Excel и экспортом.
    """
    now = datetime.now()
    total = len(entries)
    ok = [e for e in entries if e.verdict == V_OK]
    ret = [e for e in entries if e.verdict == V_RETURN]
    ref = [e for e in entries if e.verdict == V_REFUSE]
    man = [e for e in entries if e.verdict == V_MANUAL]

    def pct(n: int) -> str:
        return f"{(100.0 * n / total):.1f} %" if total else "—"

    sections: List[tuple] = []

    sections.append(("ОБЩИЕ СВЕДЕНИЯ", ["Показатель", "Значение"], [
        ["Поступило заявлений (строк реестра)", str(total)],
        ["В приказ — оснований ст. 125 ГПК РФ не выявлено",
         f"{len(ok)} ({pct(len(ok))})"],
        ["Возвращено (ч. 1 ст. 125, ст. 135 ГПК РФ)",
         f"{len(ret)} ({pct(len(ret))})"],
        ["Отказано (ч. 3 ст. 125, ст. 134 ГПК РФ)",
         f"{len(ref)} ({pct(len(ref))})"],
        ["Требуют ручной проверки помощника (судьи)",
         f"{len(man)} ({pct(len(man))})"],
        ["Отчёт сформирован", now.strftime("%d.%m.%Y %H:%M")],
    ]))

    def grounds_rows(kind: str) -> List[List[str]]:
        # Группируем по существу основания (шифр правила), а не по полному
        # тексту: в текстах про пошлину, ст. 124, страну и лимит есть переменные
        # подробности (суммы, названия стран, причины ошибок реквизитов), из-за
        # которых одинаковые основания выглядели в статистике как разные строки.
        # Неопознанные тексты (старые или ручные записи журнала) идут как есть.
        counter: Dict[Tuple[str, str], int] = {}
        extra: Dict[str, int] = {}
        for e in entries:
            for f in e.findings:
                if f.kind != kind:
                    continue
                title = GROUND_TITLES.get((f.rule, kind))
                if title is None:
                    title = GROUND_TITLES.get((_ground_code_from_text(f.text), kind))
                if title:
                    counter[(f.ref, title)] = counter.get((f.ref, title), 0) + 1
                else:
                    label = f"{f.ref} — {f.text}" if f.ref else f.text
                    extra[label] = extra.get(label, 0) + 1
        rows = [[f"{ref} — {title}" if ref else title, str(n)]
                for (ref, title), n in
                sorted(counter.items(), key=lambda kv: (-kv[1], kv[0]))]
        rows += [[label, str(n)] for label, n in
                 sorted(extra.items(), key=lambda kv: (-kv[1], kv[0]))]
        return rows or [["(нет)", "0"]]

    sections.append(("ОСНОВАНИЯ ВОЗВРАТА ЗАЯВЛЕНИЙ",
                     ["Основание (норма — описание)", "Заявлений"],
                     grounds_rows("return")))
    sections.append(("ОСНОВАНИЯ ОТКАЗА В ПРИНЯТИИ",
                     ["Основание (норма — описание)", "Заявлений"],
                     grounds_rows("refuse")))
    sections.append(("ВОПРОСЫ ДЛЯ РУЧНОЙ ПРОВЕРКИ",
                     ["Вопрос (норма — описание)", "Заявлений"],
                     grounds_rows("manual")))

    cat_counter: Dict[str, List] = {}
    for e in entries:
        label = e.category if e.category else "не указана"
        bucket = cat_counter.setdefault(label, [0, Decimal("0")])
        bucket[0] += 1
        bucket[1] += _dec(e.total)
    sections.append(("КАТЕГОРИИ ТРЕБОВАНИЙ (СТ. 122 ГПК РФ)",
                     ["Категория", "Заявлений", "Сумма, руб."],
                     [[k, str(v[0]), _rub_plain(str(v[1]))] for k, v in
                      sorted(cat_counter.items(), key=lambda kv: (-kv[1][0], kv[0]))]
                     or [["(нет)", "0", "0,00"]]))

    cl_counter: Dict[str, List] = {}
    for e in entries:
        bucket = cl_counter.setdefault(e.claimant, [0, Decimal("0")])
        bucket[0] += 1
        bucket[1] += _dec(e.total)
    top = sorted(cl_counter.items(), key=lambda kv: (-kv[1][0], kv[0]))[:10]
    sections.append(("ВЗЫСКАТЕЛИ (ТОП-10 ПО ЧИСЛУ ЗАЯВЛЕНИЙ)",
                     ["Взыскатель", "Заявлений", "Сумма, руб."],
                     [[k, str(v[0]), _rub_plain(str(v[1]))] for k, v in top]
                     or [["(нет)", "0", "0,00"]]))

    month_counter: Dict[str, List[int]] = {}
    for e in entries:
        key = "дата не указана"
        if re.fullmatch(r"\d{2}\.\d{2}\.\d{4}", e.received or ""):
            key = f"{e.received[6:]}-{e.received[3:5]}"
        bucket = month_counter.setdefault(key, [0, 0, 0, 0])
        bucket[0] += 1
        if e.verdict == V_OK:
            bucket[1] += 1
        elif e.verdict == V_RETURN:
            bucket[2] += 1
        elif e.verdict == V_REFUSE:
            bucket[3] += 1
    sections.append(("ПО МЕСЯЦАМ ПОСТУПЛЕНИЯ",
                     ["Месяц", "Поступило", "В приказ", "Возвращено", "Отказано"],
                     [[k] + [str(x) for x in v] for k, v in sorted(month_counter.items())]))

    amounts = [_dec(e.total) for e in entries]
    if amounts:
        sections.append(("СУММЫ ТРЕБОВАНИЙ", ["Показатель", "Значение"], [
            ["Общая сумма требований, руб.", _rub_plain(str(sum(amounts)))],
            ["Средняя сумма заявления, руб.",
             _rub_plain(str((sum(amounts) / len(amounts)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)))],
            ["Наибольшая сумма заявления, руб.", _rub_plain(str(max(amounts)))],
            ["Наименьшая сумма заявления, руб.", _rub_plain(str(min(amounts)))],
        ]))
    else:
        sections.append(("СУММЫ ТРЕБОВАНИЙ", ["Показатель", "Значение"],
                         [["(нет данных)", "0,00"]]))

    duty_required = sum((_dec(e.duty_required) for e in entries), Decimal("0"))
    duty_paid = sum((_dec(e.duty_paid) for e in entries if _dec(e.duty_paid) > 0),
                    Decimal("0"))
    underpay = sum(1 for e in entries
                   if _dec(e.duty_required) > 0 and 0 < _dec(e.duty_paid)
                   and _dec(e.duty_paid) + Decimal("0.005") < _dec(e.duty_required))
    exempt = sum(1 for e in entries if _dec(e.duty_required) == 0
                 and any("освобожд" in f.text for f in e.findings))
    sections.append(("ГОСПОШЛИНА (СТ. 333.19, 333.36 НК РФ)",
                     ["Показатель", "Значение"], [
                         ["Рассчитано к уплате, руб.", _rub_plain(str(duty_required))],
                         ["Подтверждено оплат, руб.", _rub_plain(str(duty_paid))],
                         ["Заявлений с недоплатой пошлины", str(underpay)],
                         ["Заявлений с льготой (освобождением)", str(exempt)],
                     ]))
    return sections


