# стили вердиктов: 7 — в приказ (зелёный), 8 — возврат (жёлтый),
# 9 — отказ (красный), 10 — на проверку (голубой)
_SCREEN_VERDICT_STYLE = {V_OK: 7, V_RETURN: 8, V_REFUSE: 9, V_MANUAL: 10}


def _write_xlsx_book(path: str, sheets: List[tuple]) -> str:
    """Собирает книгу Excel из листов [(имя, rows[, widths, freeze])] без библиотек."""
    normalized = []
    for sheet in sheets:
        if len(sheet) == 2:
            normalized.append((sheet[0], sheet[1], None, 0))
        else:
            normalized.append(sheet)
    sheets = normalized
    n = len(sheets)
    overrides = "".join(
        f'<Override PartName="/xl/worksheets/sheet{i}.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
        for i in range(1, n + 1))
    sheets_xml = "".join(
        f'<sheet name="{_tpl_escape(name)}" sheetId="{i}" r:id="rId{i}"/>'
        for i, (name, _, _, _) in enumerate(sheets, start=1))
    rels_xml = "".join(
        f'<Relationship Id="rId{i}" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" '
        f'Target="worksheets/sheet{i}.xml"/>' for i in range(1, n + 1))
    rels_xml += (
        f'<Relationship Id="rId{n + 1}" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" '
        'Target="styles.xml"/>')
    files = {
        "[Content_Types].xml": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
            '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
            '<Default Extension="xml" ContentType="application/xml"/>'
            '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
            f'{overrides}'
            '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
            "</Types>"
        ).encode("utf-8"),
        "_rels/.rels": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
            "</Relationships>"
        ).encode("utf-8"),
        "xl/workbook.xml": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            f'<workbook xmlns="{NS[1:-1]}" xmlns:r="{NS_R[1:-1]}">'
            f"<sheets>{sheets_xml}</sheets></workbook>"
        ).encode("utf-8"),
        "xl/_rels/workbook.xml.rels": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            f'{rels_xml}'
            "</Relationships>"
        ).encode("utf-8"),
        "xl/styles.xml": _SCREEN_STYLES.encode("utf-8"),
    }
    for i, (name, rows, widths, freeze) in enumerate(sheets, start=1):
        files[f"xl/worksheets/sheet{i}.xml"] = _tpl_worksheet(rows, widths, freeze)
    try:
        with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
            for name, payload in files.items():
                z.writestr(name, payload)
    except OSError as exc:
        raise ConversionError(
            f"Не удалось записать книгу Excel «{os.path.basename(path)}»: {exc}"
        ) from exc
    return path


def build_screening_workbook(path: str, entries: List[ScreeningEntry],
                             source_name: str, section_label: str = "") -> str:
    """Книга Excel: лист «Скрининг» (построчный вердикт) + лист «Статистика»."""
    rows = [[(_S_TITLE,
              f"СКРИНИНГ ЗАЯВЛЕНИЙ ПО СТ. 125 ГПК РФ — реестр «{source_name}»"
              + (f", участок: {section_label}" if section_label else ""))],
            [(_S_HEAD, "Стр."), (_S_HEAD, "Должник"), (_S_HEAD, "Взыскатель"),
             (_S_HEAD, "Сумма, руб."), (_S_HEAD, "Категория (ст. 122)"),
             (_S_HEAD, "Пошлина расч., руб."), (_S_HEAD, "Оплачено, руб."),
             (_S_HEAD, "Вердикт"), (_S_HEAD, "Основания и примечания")]]
    for e in sorted(entries, key=lambda x: (x.row, x.fio)):
        grounds = "; ".join(f"{f.ref}: {f.text}" for f in e.findings
                            if f.kind in ("return", "refuse", "manual"))
        if not grounds:
            grounds = "формальные основания ст. 125 не выявлены"
        rows.append([
            (_S_DATA, str(e.row) if e.row else "—"),
            (_S_DATA, e.fio),
            (_S_DATA, e.claimant),
            (_S_DATA, _rub_plain(e.total)),
            (_S_DATA, e.category or "не указана"),
            (_S_DATA, _rub_plain(e.duty_required)),
            (_S_DATA, _rub_plain(e.duty_paid) if _dec(e.duty_paid) > 0 else "—"),
            (_SCREEN_VERDICT_STYLE.get(e.verdict, _S_DATA), e.verdict),
            (_S_DATA, grounds),
        ])
    sheet_screen_rows = rows
    stat_rows = [[(_S_TITLE, "СТАТИСТИКА СКРИНИНГА ПО СТ. 125 ГПК РФ")]]
    for title, header, data_rows in build_statistics_sections(entries):
        stat_rows.append([(_S_TITLE, title)])
        stat_rows.append([(_S_HEAD, h) for h in header])
        for r in data_rows:
            stat_rows.append([(_S_DATA, str(c)) for c in r])
        stat_rows.append([])

    hint_rows = [
        [(_S_TITLE, "КАК РАБОТАТЬ С КНИГОЙ СКРИНИНГА")],
        [(_S_TEXT, "1. Лист «Скрининг»: вердикт по каждому заявлению. «В ПРИКАЗ» — "
                   "формальных оснований ст. 125 не выявлено; «ВОЗВРАТ»/«ОТКАЗ» — "
                   "подготовлены проекты определений (файлы 06–08 в этой папке); "
                   "«НА ПРОВЕРКУ» — вопросы для помощника и судьи.")],
        [(_S_TEXT, "2. Лист «Статистика»: сводка по основаниям, категориям, "
                   "взыскателям, месяцам, суммам и госпошлине — источник для "
                   "докладов и квартальных отчётов.")],
        [(_S_TEXT, "3. Журнал: screening_journal.csv рядом с программой — вся "
                   "история скринингов; вкладка «Статистика» окна программы "
                   "читает именно его.")],
        [(_S_TEXT, "4. Решение по каждому заявлению принимает мировой судья "
                   "(ст. 125, 126 ГПК РФ); листы проверки (файл 09) вкладываются "
                   "в материал дела.")],
    ]
    sheets = [
        ("Скрининг", rows, [7, 28, 28, 13, 32, 13, 13, 14, 72], 2),
        ("Статистика", stat_rows, [70, 16, 16, 16, 16], 0),
    ]
    # v3.6: лист «Приложения» — построчный анализ файлов-приложений
    docs_entries = [e for e in sorted(entries, key=lambda x: (x.row, x.fio)) if e.docs]
    if docs_entries:
        docs_rows = [[(_S_TITLE, "АНАЛИЗ ПРИЛОЖЕННЫХ ДОКУМЕНТОВ (файлы заявлений)")],
                     [(_S_HEAD, "Стр."), (_S_HEAD, "Должник"), (_S_HEAD, "Файл"),
                      (_S_HEAD, "Распознано"), (_S_HEAD, "Статус")]]
        for e in docs_entries:
            d = e.docs
            if not d.files:
                docs_rows.append([
                    (_S_DATA, str(e.row) or "—"), (_S_DATA, e.fio),
                    (_S_DATA, "—"), (_S_DATA, d.found_text or "—"),
                    (_S_DATA, ("приложения не сопоставлены" if not d.matched
                               else d.note or "файлы не найдены"))])
            for f in d.files:
                docs_rows.append([
                    (_S_DATA, str(e.row) or "—"), (_S_DATA, e.fio),
                    (_S_DATA, f.name), (_S_DATA, f.kind or "—"),
                    (_S_DATA, f.status + (f" ({f.detail})" if f.detail else ""))])
            if d.missing_text:
                docs_rows.append([
                    (_S_DATA, str(e.row) or "—"), (_S_DATA, e.fio),
                    (_S_DATA, "ИТОГ"), (_S_DATA, "не хватает: " + d.missing_text),
                    (_S_DATA, "")])
        sheets.append(("Приложения", docs_rows, [7, 26, 42, 46, 32], 2))
    sheets.append(("Как работать", hint_rows, [120], 0))
    return _write_xlsx_book(path, sheets)


def screening_readme_text(result: ScreeningResult, source_name: str,
                          extra_warnings: Optional[List[str]] = None) -> str:
    lines = [
        "ПАМЯТКА: КАК РАБОТАТЬ С РЕЗУЛЬТАТАМИ СКРИНИНГА ПО СТ. 125 ГПК РФ",
        "=" * 68,
        "",
        f"Реестр: {source_name}.",
        f"Проверено заявлений: {result.total} (в приказ: {result.ok_count}, "
        f"возврат: {result.return_count}, отказ: {result.refuse_count}, "
        f"на проверку: {result.manual_count}"
        + (f", строк с ошибками ст. 124: {result.rejected}" if result.rejected else "")
        + ").",
        "",
        "1. 09_Листы_проверки_ст125.docx — лист проверки по каждому заявлению",
        "   (вкладывается в материал дела; таблица: норма — результат — примечание).",
        "2. 06_Определения_о_возвращении_проекты.docx — проекты определений о",
        "   возвращении (ч. 1 ст. 125 ГПК РФ) с точными пунктами и основаниями.",
        "3. 07_Определения_об_отказе_проекты.docx — проекты определений об отказе",
        "   в принятии (ч. 3 ст. 125 ГПК РФ).",
        "4. 08_Сопроводительные_письма_заявителям.docx — уведомления взыскателям",
        "   (приложение к копии определения, возврат документов).",
        "5. Скрининг_ст125_….xlsx — построчная таблица вердиктов + лист «Статистика».",
        "6. Журнал: screening_journal.csv рядом с программой — вкладка «Статистика»",
        "   окна программы читает его и строит сводку; amirs_log.txt — технический журнал.",
        "",
        "Сроки: определение о возвращении/отказе — в течение 3 дней со дня",
        "поступления заявления (ч. 4 ст. 125 ГПК РФ).",
        "Решение по каждому заявлению принимает мировой судья; программа готовит",
        "проекты и не заменяет процессуальных полномочий судьи.",
    ]
    if extra_warnings:
        lines += ["", "ВНИМАНИЕ (папки приложений):"]
        lines += ["- " + w for w in extra_warnings]
    lines += ["", f"Конвертер реестров АМИРС, версия {APP_VERSION}."]
    return "\n".join(lines)


def generate_screening_package(excel_path: str, settings: DocSettings,
                               output_dir: Optional[str] = None,
                               strict_ids: bool = False,
                               journal: bool = True,
                               attachments_dir: str = "",
                               attachments_files: Optional[List[str]] = None,
                               manual_binds: Optional[Dict[str, Dict[str, object]]] = None
                               ) -> ScreeningResult:
    """Скрининг реестра по ст. 125 ГПК РФ + готовые документы аппарата.

    В папке «Скрининг_ст125_<имя реестра>» создаются:
      Скрининг_ст125_<имя>.xlsx               — вердикты + лист «Статистика»;
      09_Листы_проверки_ст125.docx            — лист проверки по каждому заявлению;
      06_Определения_о_возвращении_проекты.docx — для вердикта «ВОЗВРАТ»;
      07_Определения_об_отказе_проекты.docx   — для вердикта «ОТКАЗ»;
      08_Сопроводительные_письма_заявителям.docx — уведомления;
      00_ПАМЯТКА_СКРИНИНГ.txt                 — порядок работы.
    Каждая проверенная строка дописывается в screening_journal.csv (рядом
    с программой) — источник вкладки «Статистика».
    attachments_dir / attachments_files (v3.6/3.6.1) — приложения к заявлениям:
    папка с подпапками «на заявление» и/или список отдельных файлов (PDF, DOCX,
    фото-сканы), сопоставляемых со строками реестра по ФИО/л/с. manual_binds
    (v3.7) — ручная привязка файлов из окна предпросмотра.
    """
    started_at = datetime.now()
    if not os.path.isfile(excel_path):
        raise ConversionError(f"Файл не найден: {excel_path}")
    base_dir = output_dir or os.path.dirname(os.path.abspath(excel_path)) or os.getcwd()
    stem = os.path.splitext(os.path.basename(excel_path))[0]
    folder = os.path.join(base_dir, f"Скрининг_ст125_{_safe_filename(stem)}")
    os.makedirs(folder, exist_ok=True)

    try:
        parsed = process_registry(excel_path, output_dir=folder,
                                  strict_ids=strict_ids, xml_name=None, journal=False)
    except ConversionError as exc:
        raise ConversionError(str(exc).replace("XML-пакет не сформирован",
                                               "скрининг не выполнен")) from exc

    present, control_by_row, raw_rows, col_of = _read_control_columns(excel_path)

    # Анализ приложений (v3.6): папки «на заявление» сопоставляются со строками
    # реестра по лицевому счёту, затем по ФИО; отдельные файлы (v3.6.1, кнопка
    # «Обзор: файлы…») — по ФИО/л/с в имени файла или в тексте документа.
    doc_mapping: Dict[int, str] = {}
    doc_unmatched: List[str] = []
    doc_root_note = ""
    doc_file_map: Dict[int, List[str]] = {}
    doc_files_unmatched: List[str] = []
    doc_files_note = ""
    doc_profiles: Dict[str, List[List[str]]] = {}
    has_dir = bool(attachments_dir and os.path.isdir(attachments_dir))
    has_files = bool(attachments_files)
    docs_enabled = has_dir or has_files
    tesseract_cfg = _configured_paddle_models_path() if docs_enabled else ""
    if docs_enabled:
        doc_profiles = load_doc_profiles()
        doc_records = [{"row": int(r.get("row") or 0), "fio": r.get("fio") or "",
                        "account": r.get("account") or ""} for r in parsed.records]
        if has_dir:
            doc_mapping, doc_unmatched, doc_root_note = match_attachment_folders(
                attachments_dir, doc_records)
        if has_files:
            doc_file_map, doc_files_unmatched, doc_files_note = \
                match_attachment_files([p for p in attachments_files
                                        if os.path.isfile(p)],
                                       doc_records, tesseract_cfg)
            if manual_binds:
                manual_rows, _stale = apply_manual_file_binds(
                    doc_file_map, doc_files_unmatched, doc_records, manual_binds)
                if manual_rows:
                    doc_files_note = (doc_files_note + "; " if doc_files_note
                                      else "") + \
                        f"привязано вручную: {sum(manual_rows.values())}"

    def folder_file_paths(claim_folder: str) -> Optional[List[str]]:
        """Список файлов папки заявления (без подпапок); None — не читается."""
        try:
            return [os.path.join(claim_folder, n)
                    for n in sorted(os.listdir(claim_folder))
                    if os.path.isfile(os.path.join(claim_folder, n))]
        except OSError:
            return None

    def claim_docs_result(claim_folder: str, claim_files: List[str],
                          groups: List[List[str]]) -> DocCheckResult:
        """Сверка приложений одного заявления: папка + отдельные файлы."""
        if claim_folder and claim_files:
            fpaths = folder_file_paths(claim_folder)
            if fpaths is None:
                fpaths = []
            res = _check_document_files(fpaths + sorted(claim_files), groups,
                                        tesseract_cfg, folder_label=claim_folder)
            res.note = (res.note + "; " if res.note else "") + \
                f"папка + отдельные файлы: {len(claim_files)}"
            return res
        if claim_folder:
            return check_claim_documents(claim_folder, groups, tesseract_cfg)
        res = check_claim_files(claim_files, groups, tesseract_cfg)
        res.note = (res.note + "; " if res.note else "") + \
            f"отдельные файлы (без папки): {len(claim_files)}"
        return res

    def raw_cell(row_no: int, name: str) -> str:
        col = col_of.get(normalize_header(name))
        if col is None:
            return ""
        for r in raw_rows:
            if r["row"] == row_no:
                return str(r["cells"].get(col, "")).strip()
        return ""

    entries: List[ScreeningEntry] = []
    seen: Dict[str, int] = {}
    for rec in parsed.records:
        key = f"{(rec.get('fio') or '').lower()}|{rec.get('account') or ''}|{rec.get('debt') or ''}"
        duplicate = key in seen
        seen.setdefault(key, int(rec.get("row") or 0))
        docs_result = None
        row_no = int(rec.get("row") or 0)
        if docs_enabled:
            claim_folder = doc_mapping.get(row_no, "")
            claim_files = doc_file_map.get(row_no, [])
            control_row = control_by_row.get(row_no, {})
            category = match_st122_category(
                str(control_row.get("Категория_Требования") or ""))
            groups, source = docs_profile_groups(category, doc_profiles)
            if claim_folder or claim_files:
                docs_result = claim_docs_result(claim_folder, claim_files, groups)
                if source == "минимальный":
                    docs_result.note = (docs_result.note + "; " if docs_result.note
                                        else "") + "категория не распознана — " \
                        "проверен минимальный набор"
            else:
                docs_result = DocCheckResult(matched=False,
                                             note="приложения не найдены")
        entries.append(screen_single(rec, control_by_row.get(int(rec.get("row") or 0), {}),
                                     present, duplicate, docs_result))

    rejected_rows = set()
    for rej in parsed.rejected:
        try:
            row_no = int(rej["Строка"])
        except (KeyError, ValueError, TypeError):
            continue
        rejected_rows.add(row_no)
        rec_like = {
            "row": row_no,
            "claimant": xml_safe(raw_cell(row_no, "Взыскатель")) or "—",
            "fio": xml_safe(raw_cell(row_no, "Должник_ФИО")) or "—",
            "birth_date": parse_date_value(raw_cell(row_no, "Дата_Рождения")) or "",
            "address": xml_safe(raw_cell(row_no, "Адрес_Регистрации")),
            "account": clean_account_number(raw_cell(row_no, "Номер_Лицевого_Счета")),
            "period": xml_safe(raw_cell(row_no, "Период_Задолженности")),
            "subject": xml_safe(raw_cell(row_no, "Существо_Требований")),
            "debt": parse_amount(raw_cell(row_no, "Сумма_Долга")) or "0.00",
            "penalty": parse_amount(raw_cell(row_no, "Сумма_Пени")) or "0.00",
            "duty": "0.00",
            "snils": "", "inn": "", "passport": "",
        }
        entry = screen_single(rec_like, control_by_row.get(row_no, {}), present, False)
        if docs_enabled:
            rej_map, _, _ = match_attachment_folders(attachments_dir,
                                                     [rec_like]) if has_dir else ({}, [], "")
            rej_files = doc_file_map.get(row_no, []) if has_files else []
            rej_folder = rej_map.get(row_no, "")
            rej_cat = match_st122_category(
                str(control_by_row.get(row_no, {}).get("Категория_Требования") or ""))
            rej_groups, _ = docs_profile_groups(rej_cat, doc_profiles)
            if rej_folder or rej_files:
                entry.docs = claim_docs_result(rej_folder, rej_files, rej_groups)
            else:
                entry.docs = DocCheckResult(matched=False,
                                            note="приложения не найдены")
        entry.findings.insert(0, GroundFinding(
            "return", "form124", "п. 3 ч. 1 ст. 125 ГПК РФ",
            f"форма и содержание заявления не соответствуют ст. 124 ГПК РФ "
            f"({rej.get('Причина', 'ошибки реквизитов')})"))
        _finalize_verdict(entry)
        entries.append(entry)

    entries.sort(key=lambda e: e.row)

    # предупреждения по папкам и отдельным файлам приложений (v3.6/3.6.1)
    doc_warnings: List[str] = []
    if doc_root_note:
        doc_warnings.append(doc_root_note + ".")
    if doc_files_note:
        doc_warnings.append(doc_files_note + ".")
    if doc_unmatched:
        doc_warnings.append("Папки приложений без заявления: "
                            + ", ".join(doc_unmatched[:5])
                            + ("…" if len(doc_unmatched) > 5 else "")
                            + " — привяжите вручную.")
    if doc_files_unmatched:
        doc_warnings.append("Файлы приложений без заявления: "
                            + ", ".join(doc_files_unmatched[:5])
                            + ("…" if len(doc_files_unmatched) > 5 else "")
                            + " — привяжите вручную.")

    result = ScreeningResult(folder=folder, total=len(entries),
                             rejected=len(parsed.rejected),
                             warning_count=parsed.warning_count,
                             warnings_log_path=parsed.warnings_log_path,
                             log_path=parsed.log_path)
    result.entries = entries  # v3.6: записи с анализом приложений — для GUI и тестов
    for e in entries:
        if e.verdict == V_OK:
            result.ok_count += 1
        elif e.verdict == V_RETURN:
            result.return_count += 1
        elif e.verdict == V_REFUSE:
            result.refuse_count += 1
        else:
            result.manual_count += 1

    source_name = os.path.basename(excel_path)
    if settings.section.strip() and komi_match_section(settings.section) is None:
        parsed.warnings.append(
            "Наименование участка не найдено в справочнике 60 участков РК: «"
            + settings.section.strip() + "» — проверьте выбор участка.")
    section_label = settings.court_full

    returns = [e for e in entries if e.verdict == V_RETURN]
    refuses = [e for e in entries if e.verdict == V_REFUSE]
    notices = returns + refuses

    if returns:
        result.files.append(write_docx(
            os.path.join(folder, "06_Определения_о_возвращении_проекты.docx"),
            _join_blocks(_blocks_return_determination(e, settings) for e in returns)))
    if refuses:
        result.files.append(write_docx(
            os.path.join(folder, "07_Определения_об_отказе_проекты.docx"),
            _join_blocks(_blocks_refuse_determination(e, settings) for e in refuses)))
    if notices:
        result.files.append(write_docx(
            os.path.join(folder, "08_Сопроводительные_письма_заявителям.docx"),
            _join_blocks((_blocks_return_letter(e, settings) if e.verdict == V_RETURN
                          else _blocks_refuse_letter(e, settings)) for e in notices)))
    result.files.append(write_docx(
        os.path.join(folder, "09_Листы_проверки_ст125.docx"),
        _join_blocks(_blocks_checklist(e, settings) for e in entries)))

    result.workbook_path = build_screening_workbook(
        os.path.join(folder, f"Скрининг_ст125_{_safe_filename(stem)}.xlsx"),
        entries, source_name, section_label)
    result.files.append(result.workbook_path)

    try:
        readme_path = os.path.join(folder, "00_ПАМЯТКА_СКРИНИНГ.txt")
        with open(readme_path, "w", encoding="utf-8-sig") as fh:
            fh.write(screening_readme_text(result, source_name, doc_warnings))
        result.files.append(readme_path)
    except OSError as exc:
        parsed.warnings.append(f"Памятка скрининга не записана ({exc}).")

    # журнал скрининга — рядом с программой (источник вкладки «Статистика»)
    timestamp = started_at.strftime("%Y-%m-%d %H:%M:%S")
    log_rows = []
    for e in entries:
        grounds_ret = "; ".join(f"{f.ref}: {f.text}"
                                for f in e.findings if f.kind == "return")
        grounds_ref = "; ".join(f"{f.ref}: {f.text}"
                                for f in e.findings if f.kind == "refuse")
        grounds_man = "; ".join(f"{f.ref}: {f.text}"
                                for f in e.findings if f.kind == "manual")
        log_rows.append({
            "Дата_время": timestamp,
            "Файл": source_name,
            "Строка": e.row or "",
            "Участок": section_label,
            "Взыскатель": e.claimant,
            "Должник": e.fio,
            "Сумма_требования_руб": e.total,
            "Категория_122": e.category or "не указана",
            "Вердикт": e.verdict,
            "Основания_возврата": grounds_ret,
            "Основания_отказа": grounds_ref,
            "Ручная_проверка": grounds_man,
            "Пошлина_расчет": e.duty_required,
            "Пошлина_оплачено": e.duty_paid or "0.00",
            "Документы_найдено": e.docs.found_text if e.docs else "",
            "Документы_недостаёт": e.docs.missing_text if e.docs else "",
            "Примечание": "",
        })
    if doc_warnings:
        parsed.warnings.extend(doc_warnings)
        result.warning_count += len(doc_warnings)
        warn_path = os.path.join(folder, WARNINGS_LOG_NAME)
        warn_exists = os.path.exists(warn_path)
        try:
            with open(warn_path, "a",
                      encoding="utf-8-sig" if not warn_exists else "utf-8",
                      newline="") as fh:
                writer = csv.DictWriter(
                    fh, fieldnames=["Строка", "Должник", "Предупреждение"],
                    delimiter=";")
                if not warn_exists:
                    writer.writeheader()
                for text in doc_warnings:
                    writer.writerow({"Строка": "", "Должник": "",
                                     "Предупреждение": text})
            if not result.warnings_log_path:
                result.warnings_log_path = warn_path
        except OSError as exc:
            parsed.warnings.append(
                f"Предупреждения о папках приложений не записаны ({exc}).")
    result.journal_path = _append_screening_rows(
        screening_journal_path(), log_rows)
    app_log(f"СКРИНИНГ: {source_name} — всего {result.total}, в приказ "
            f"{result.ok_count}, возврат {result.return_count}, отказ "
            f"{result.refuse_count}, на проверку {result.manual_count}")

    if journal:
        warnings: List[str] = []
        _append_journal_row(
            os.path.join(base_dir, JOURNAL_NAME),
            {
                "Дата_время": timestamp,
                "Файл": source_name,
                "Код_участка": "",
                "Всего_строк": result.total,
                "Принято": result.ok_count,
                "Отклонено": result.rejected,
                "Предупреждения": result.warning_count,
                "Дубликаты": 0,
                "Режим": "скрининг ст. 125",
                "Секунды": round((datetime.now() - started_at).total_seconds(), 1),
                "Статус": "СКРИНИНГ",
            },
            warnings,
        )
    return result


