class ModernTooltip:
    """Всплывающая подсказка для виджета."""

    def __init__(self, widget, text: str):
        self.widget = widget
        self.text = text
        self.tip_window = None
        widget.bind("<Enter>", self.show_tip)
        widget.bind("<Leave>", self.hide_tip)

    def show_tip(self, event=None):
        if self.tip_window or not self.text:
            return
        try:
            bx, by, _, _ = self.widget.bbox("insert")
            x = self.widget.winfo_rootx() + bx + 25
            y = self.widget.winfo_rooty() + by + 25
        except Exception:
            x = self.widget.winfo_rootx() + 20
            y = self.widget.winfo_rooty() + self.widget.winfo_height() + 6
        try:
            self.tip_window = tw = tk.Toplevel(self.widget)
            tw.wm_overrideredirect(True)
            tw.wm_geometry(f"+{x}+{y}")
            tw.attributes("-topmost", True)
            frame = tk.Frame(tw, bg="#D1D1D6", bd=1, relief="solid")
            frame.pack(fill="both", expand=True)
            tk.Label(frame, text=self.text, justify="left",
                     bg="#FFFFFF", fg="#1D1D1F", font=("Segoe UI", 9),
                     padx=10, pady=6).pack()
        except Exception:
            self.tip_window = None

    def hide_tip(self, event=None):
        if self.tip_window:
            try:
                self.tip_window.destroy()
            except Exception:
                pass
            self.tip_window = None


def _is_win_zoomed(win) -> bool:
    """Проверяет, развёрнуто ли окно на весь экран (Windows / Linux / macOS)."""
    try:
        if win.state() == "zoomed":
            return True
    except Exception:
        pass
    try:
        return bool(win.attributes("-zoomed"))
    except Exception:
        return False


def _set_win_zoomed(win, zoomed: bool = True) -> None:
    """Разворачивает окно на весь экран или возвращает обычный вид."""
    if zoomed:
        try:
            win.state("zoomed")
            return
        except Exception:
            pass
        try:
            win.attributes("-zoomed", True)
        except Exception:
            pass
    else:
        try:
            win.state("normal")
        except Exception:
            pass
        try:
            win.attributes("-zoomed", False)
        except Exception:
            pass


class AppleButton(tk.Canvas):
    """Современная скругленная кнопка в стиле Apple (macOS/iOS).

    Реагирует на нажатие левой кнопкой мыши в любой точке своей площади
    (включая углы и внутренние поля), поддерживает плавную подсветку при
    наведении и нажатии, а также программное изменение state/text через
    .config() и .configure().
    """

    def __init__(self, master, text="", command=None, bg="#007AFF", fg="#FFFFFF",
                 hover_bg="#0062CC", active_bg="#004999",
                 disabled_bg="#E5E5EA", disabled_fg="#8E8E93",
                 font=("Segoe UI", 10, "bold"), radius=10,
                 padx=16, pady=8, anchor="center", **kwargs):
        try:
            parent_bg = master.cget("bg")
        except Exception:
            parent_bg = "#FFFFFF"
        super().__init__(master, bg=parent_bg, bd=0, highlightthickness=0,
                         relief="flat", cursor="hand2", takefocus=1)
        self._text = str(text or "")
        self._command = command
        self._bg = bg
        self._fg = fg
        self._hover_bg = hover_bg
        self._active_bg = active_bg
        self._disabled_bg = disabled_bg
        self._disabled_fg = disabled_fg
        self._font = font
        self._radius = max(int(radius), 4)
        self._padx = int(padx)
        self._pady = int(pady)
        self._anchor = anchor
        self._state = "normal"
        self._hovered = False
        self._pressed = False
        self._focused = False

        self._update_requested_size()
        self.bind("<Configure>", self._draw)
        self.bind("<Enter>", self._on_enter, add="+")
        self.bind("<Leave>", self._on_leave, add="+")
        self.bind("<ButtonPress-1>", self._on_press, add="+")
        self.bind("<ButtonRelease-1>", self._on_release, add="+")
        self.bind("<FocusIn>", self._on_focus_in, add="+")
        self.bind("<FocusOut>", self._on_focus_out, add="+")
        self.bind("<Return>", self._on_key_activate, add="+")
        self.bind("<space>", self._on_key_activate, add="+")

    def _update_requested_size(self):
        try:
            import tkinter.font as tkfont
            f = tkfont.Font(root=self, font=self._font)
            tw = int(f.measure(self._text))
            th = int(f.metrics("linespace"))
        except Exception:
            tw = len(self._text) * 8
            th = 18
        req_w = max(tw + self._padx * 2, 36)
        req_h = max(th + self._pady * 2, 30)
        super().configure(width=req_w, height=req_h)

    def _current_colors(self):
        if self._state == "disabled":
            return self._disabled_bg, self._disabled_fg
        if self._pressed:
            return self._active_bg, self._fg
        if self._hovered:
            return self._hover_bg, self._fg
        return self._bg, self._fg

    def _draw(self, _event=None):
        self.delete("all")
        win_w = self.winfo_width()
        win_h = self.winfo_height()
        w = win_w if win_w > 4 else int(self.cget("width") or 36)
        h = win_h if win_h > 4 else int(self.cget("height") or 30)
        r = max(min(self._radius, (w - 2) // 2, (h - 2) // 2), 2)
        fill_color, text_color = self._current_colors()
        outline_col = "#0051D5" if (self._focused and self._state != "disabled") else fill_color

        x1, y1, x2, y2 = 1, 1, w - 2, h - 2
        d = r * 2
        # Точная геометрия скругленного прямоугольника (4 дуги + 2 прямоугольника)
        self.create_arc(x1, y1, x1 + d, y1 + d, start=90, extent=90,
                        fill=fill_color, outline=outline_col)
        self.create_arc(x2 - d, y1, x2, y1 + d, start=0, extent=90,
                        fill=fill_color, outline=outline_col)
        self.create_arc(x1, y2 - d, x1 + d, y2, start=180, extent=90,
                        fill=fill_color, outline=outline_col)
        self.create_arc(x2 - d, y2 - d, x2, y2, start=270, extent=90,
                        fill=fill_color, outline=outline_col)
        self.create_rectangle(x1 + r, y1, x2 - r, y2,
                              fill=fill_color, outline=fill_color)
        self.create_rectangle(x1, y1 + r, x2, y2 - r,
                              fill=fill_color, outline=fill_color)
        if outline_col != fill_color:
            self.create_line(x1 + r, y1, x2 - r, y1, fill=outline_col)
            self.create_line(x1 + r, y2, x2 - r, y2, fill=outline_col)
            self.create_line(x1, y1 + r, x1, y2 - r, fill=outline_col)
            self.create_line(x2, y1 + r, x2, y2 - r, fill=outline_col)

        if self._anchor == "w":
            tx = self._padx
            t_anchor = "w"
        else:
            tx = w / 2
            t_anchor = "center"
        self.create_text(tx, h / 2, text=self._text, fill=text_color,
                         font=self._font, anchor=t_anchor)

    def _on_enter(self, _event=None):
        if self._state != "disabled":
            self._hovered = True
            self._draw()

    def _on_leave(self, _event=None):
        if self._hovered or self._pressed:
            self._hovered = False
            self._pressed = False
            self._draw()

    def _on_press(self, _event=None):
        if self._state == "disabled":
            return
        self._pressed = True
        self._draw()

    def _on_release(self, event=None):
        if self._state == "disabled":
            return
        was_pressed = self._pressed
        self._pressed = False
        if event is not None:
            w = self.winfo_width()
            h = self.winfo_height()
            inside = (0 <= event.x <= w) and (0 <= event.y <= h)
        else:
            inside = True
        self._hovered = inside
        self._draw()
        if was_pressed and inside and callable(self._command):
            self.after(10, self._command)

    def _on_focus_in(self, _event=None):
        self._focused = True
        self._draw()

    def _on_focus_out(self, _event=None):
        self._focused = False
        self._draw()

    def _on_key_activate(self, _event=None):
        if self._state != "disabled" and callable(self._command):
            self._pressed = True
            self._draw()
            self.after(80, self._finish_key_activate)

    def _finish_key_activate(self):
        self._pressed = False
        self._draw()
        if self._state != "disabled" and callable(self._command):
            self._command()

    def configure(self, cnf=None, **kw):
        if cnf:
            kw.update(cnf)
        redraw = False
        if "state" in kw:
            self._state = str(kw.pop("state"))
            super().configure(cursor="arrow" if self._state == "disabled" else "hand2")
            redraw = True
        if "text" in kw:
            self._text = str(kw.pop("text"))
            self._update_requested_size()
            redraw = True
        if "command" in kw:
            self._command = kw.pop("command")
        if "bg" in kw:
            self._bg = kw.pop("bg")
            redraw = True
        if "fg" in kw:
            self._fg = kw.pop("fg")
            redraw = True
        if "activebackground" in kw:
            self._active_bg = kw.pop("activebackground")
        if "activeforeground" in kw:
            kw.pop("activeforeground")
        if kw:
            super().configure(**kw)
        if redraw:
            self._draw()

    config = configure

    def cget(self, key):
        if key == "state":
            return self._state
        if key == "text":
            return self._text
        return super().cget(key)


class ClaimEditDialog(tk.Toplevel):
    """Карточка исправления заявки накопительного реестра.

    Незаполненные (или ошибочные) поля подсвечены красным — это подсказка,
    чего не хватает для XML-пакета по ст. 124 ГПК РФ. Суммы и дата рождения
    проверяются при сохранении; СНИЛС и ИНН — одним полем (11 цифр — СНИЛС,
    12 — ИНН, вид номера программа определяет сама).
    """

    LABEL_DARK = "#1D1D1F"
    LABEL_RED = "#FF3B30"
    BG_PAGE = "#F5F5F7"
    BG_CARD = "#FFFFFF"
    BG_INPUT = "#F5F5F7"

    # (подпись, ключ записи; "_ident" — объединённое поле СНИЛС/ИНН)
    FIELDS = [
        ("Взыскатель", "Взыскатель"),
        ("ФИО должника", "Должник"),
        ("Дата рождения (ДД.ММ.ГГГГ)", "Дата_рождения"),
        ("Место рождения", "Место_рождения"),
        ("Адрес регистрации", "Адрес"),
        ("СНИЛС или ИНН", "_ident"),
        ("Паспорт (серия и номер)", "Паспорт"),
        ("Лицевой счёт", "Лицевой_счет"),
        ("Период задолженности", "Период"),
        ("Существо требования", "Существо_требования"),
        ("Сумма долга, руб.", "Сумма_долга"),
        ("Пени, руб.", "Пени"),
        ("Оплачено пошлины, руб.", "Пошлина_оплачено"),
        ("Примечание", "Примечание"),
    ]

    def __init__(self, master, row: Dict[str, str]):
        super().__init__(master)
        self.title(f"Заявка {row.get('ID') or ''} — исправить карточку")
        self.configure(bg=self.BG_PAGE)
        self.resizable(True, True)
        self.saved = False
        self.row = dict(row)
        self.vars: Dict[str, tk.StringVar] = {}
        missing = claim_missing_data(self.row)

        body = tk.Frame(self, bg=self.BG_CARD, bd=1, relief="solid")
        body.pack(fill="both", expand=True, padx=10, pady=10)
        head = tk.Frame(body, bg=self.BG_CARD)
        head.pack(fill="x", padx=14, pady=(12, 2))
        tk.Label(head, text=f"Заявка {row.get('ID') or ''} · "
                            f"{row.get('Вердикт') or '—'}",
                 font=("Segoe UI", 11, "bold"), fg="#1D1D1F",
                 bg=self.BG_CARD).pack(side="left")
        tk.Label(head, text="красным — не хватает для АМИРС",
                 font=("Segoe UI", 9), fg=self.LABEL_RED,
                 bg=self.BG_CARD).pack(side="right")

        grid = tk.Frame(body, bg=self.BG_CARD)
        grid.pack(fill="x", padx=14, pady=(4, 8))
        for idx, (label, key) in enumerate(self.FIELDS):
            r, c = divmod(idx, 2)
            if key == "_ident":
                value = row.get("СНИЛС") or row.get("ИНН") or ""
            else:
                value = row.get(key, "")
            var = tk.StringVar(value=str(value or ""))
            self.vars[key] = var
            if not self._field_ok(key, var.get(), row):
                fg = self.LABEL_RED
            else:
                fg = self.LABEL_DARK
            tk.Label(grid, text=label, font=("Segoe UI", 9), fg=fg,
                     bg=self.BG_CARD).grid(row=r, column=c * 2, sticky="w",
                                           padx=(0, 4), pady=3)
            tk.Entry(grid, textvariable=var, width=30, font=("Segoe UI", 9),
                     bg=self.BG_INPUT, fg=self.LABEL_DARK,
                     relief="solid", bd=1).grid(row=r, column=c * 2 + 1,
                                                sticky="we", padx=(0, 12),
                                                pady=2, ipady=3)
        grid.columnconfigure(1, weight=1)
        grid.columnconfigure(3, weight=1)

        if missing:
            tk.Label(body, text="Не хватает для отправки: " + ", ".join(missing),
                     wraplength=560, justify="left", font=("Segoe UI", 9),
                     fg=self.LABEL_RED, bg=self.BG_CARD).pack(anchor="w", padx=14,
                                                              pady=(0, 6))

        btns = tk.Frame(body, bg=self.BG_CARD)
        btns.pack(fill="x", padx=14, pady=(4, 14))
        AppleButton(btns, text="СОХРАНИТЬ", font=("Segoe UI", 10, "bold"),
                    bg="#34C759", fg="#FFFFFF", hover_bg="#2DB14E", active_bg="#248A3D",
                    radius=10, padx=18, pady=9,
                    command=self._save).pack(side="left", fill="x", expand=True)
        AppleButton(btns, text="Отмена", font=("Segoe UI", 9, "bold"),
                    bg="#F2F2F7", fg="#007AFF", hover_bg="#E5E5EA", active_bg="#D1D1D6",
                    radius=10, padx=16, pady=9,
                    command=self._on_dialog_close).pack(side="left", padx=(8, 0))

        self.transient(master)
        try:
            self.grab_set()
        except Exception:
            pass
        self.update_idletasks()
        saved_geom = getattr(master, "_claim_dialog_geometry", "")
        saved_state = getattr(master, "_claim_dialog_state", "normal")
        if saved_geom:
            try:
                self.geometry(saved_geom)
            except Exception:
                pass
        else:
            try:  # по центру родительского окна при первом открытии
                x = master.winfo_rootx() + (master.winfo_width() - self.winfo_width()) // 2
                y = master.winfo_rooty() + (master.winfo_height() - self.winfo_height()) // 3
                self.geometry(f"+{max(x, 0)}+{max(y, 0)}")
            except Exception:
                pass
        if saved_state == "zoomed":
            _set_win_zoomed(self, True)
        self.bind("<Configure>", self._remember_dialog_view)
        self.protocol("WM_DELETE_WINDOW", self._on_dialog_close)

    def _remember_dialog_view(self, event=None):
        if event is not None and event.widget is not self:
            return
        try:
            if _is_win_zoomed(self):
                self.master._claim_dialog_state = "zoomed"
            elif self.state() == "normal":
                self.master._claim_dialog_state = "normal"
                self.master._claim_dialog_geometry = self.geometry()
        except Exception:
            pass

    def _on_dialog_close(self):
        self._remember_dialog_view()
        if hasattr(self.master, "_save_window_state"):
            self.master._save_window_state()
        self.destroy()

    @staticmethod
    def _field_ok(key: str, value: str, row: Dict[str, str]) -> bool:
        """Проверка одного поля для подсветки (True — заполнять не нужно)."""
        if key == "_ident":
            return bool(_parse_identifier(value)[0]) or \
                bool(validate_passport(row.get("Паспорт")))
        if key == "Дата_рождения":
            return bool(parse_date_value(value))
        if key in ("Сумма_долга", "Пени", "Пошлина_оплачено"):
            return value == "" or parse_amount(value) is not None
        return bool(value.strip())

    def _save(self):
        patch: Dict[str, str] = {key: var.get().strip()
                                 for key, var in self.vars.items()}
        for key in ("Сумма_долга", "Пени", "Пошлина_оплачено"):
            if patch[key] and parse_amount(patch[key]) is None:
                messagebox.showwarning(
                    "Проверьте данные",
                    f"Поле «{key}» должно быть числом (сейчас: {patch[key]}).",
                    parent=self)
                return
        if patch.get("Дата_рождения") and not parse_date_value(patch["Дата_рождения"]):
            messagebox.showwarning(
                "Проверьте данные",
                "Дата рождения: используйте формат ДД.ММ.ГГГГ (например, 05.03.1980).",
                parent=self)
            return
        ident_kind, ident_value, ident_hint = _parse_identifier(patch.pop("_ident", ""))
        if ident_hint:
            messagebox.showwarning(
                "Проверьте данные",
                f"СНИЛС/ИНН: {ident_hint}. Впишите 11 цифр (СНИЛС) либо 12 (ИНН), "
                "или очистите поле, если есть паспорт.",
                parent=self)
            return
        if ident_kind and not ident_hint:
            valid = ident_kind == "snils" and validate_snils(ident_value) or \
                ident_kind == "inn" and validate_inn(ident_value)
            if not valid and not messagebox.askyesno(
                    "Проверьте данные",
                    "Номер не проходит контрольное число — заявка не уйдёт в АМИРС, "
                    "пока идентификатор не будет корректным (или не появится паспорт).\n\n"
                    "Сохранить как есть?",
                    parent=self):
                return
        patch["СНИЛС"] = ident_value if ident_kind == "snils" else ""
        patch["ИНН"] = ident_value if ident_kind == "inn" else ""
        merged = {**self.row, **patch}
        rec_for_screen = {
            "row": 0,
            "account": clean_account_number(merged.get("Лицевой_счет", "")),
            "claimant": merged.get("Взыскатель", ""),
            "fio": merged.get("Должник", ""),
            "birth_date": parse_date_value(merged.get("Дата_рождения")) or "",
            "birth_place": merged.get("Место_рождения", ""),
            "address": merged.get("Адрес", ""),
            "snils": merged.get("СНИЛС", ""),
            "inn": merged.get("ИНН", ""),
            "passport": validate_passport(merged.get("Паспорт")) or "",
            "period": merged.get("Период", ""),
            "subject": merged.get("Существо_требования", ""),
            "debt": parse_amount(merged.get("Сумма_долга")) or "0.00",
            "penalty": parse_amount(merged.get("Пени")) or "0.00",
            "duty": "0.00",
        }
        # Сохраняем ранее установленные процессуальные обстоятельства (документы,
        # подпись, доверенность, страна, льгота, спор о праве) из исходной карточки,
        # чтобы исправление анкетных реквизитов не снимало процессуальные основания.
        prior_findings: List[GroundFinding] = []
        prior_verdict = str(self.row.get("Вердикт") or "").strip()
        for chunk in str(self.row.get("Основания") or "").split("; "):
            parsed_f = _parse_ground_chunk(chunk)
            if parsed_f is None:
                continue
            rule_code = _ground_code_from_text(parsed_f.text)
            parsed_f.rule = rule_code
            if rule_code in ("cat", "limit", "country") and "не указан" not in parsed_f.text.lower() and "не распознан" not in parsed_f.text.lower():
                parsed_f.kind = "refuse"
            elif rule_code in ("docs", "sign", "form124") and "не отмечен" not in parsed_f.text.lower():
                parsed_f.kind = "return"
            elif prior_verdict == V_REFUSE:
                parsed_f.kind = "refuse"
            elif prior_verdict == V_RETURN:
                parsed_f.kind = "return"
            else:
                parsed_f.kind = "manual"
            if rule_code not in ("limit", "duty"):
                prior_findings.append(parsed_f)

        has_prior_lgota = any(f.rule == "lgota" for f in prior_findings)
        control_for_screen = {
            "Категория_Требования": merged.get("Категория_122", ""),
            "Дата_Поступления": datetime.now().strftime("%d.%m.%Y"),
            "Оплачено_Пошлины": merged.get("Пошлина_оплачено", ""),
            "Льгота_Пошлина": "да" if has_prior_lgota else "нет",
        }
        present = {
            "Категория_Требования": bool(merged.get("Категория_122", "").strip()),
            "Дата_Поступления": True,
            "Страна_Должника": False,
            "Документы_Приложены": False,
            "Заявление_Подписано": False,
            "Доверенность_Есть": False,
            "Оплачено_Пошлины": True,
            "Льгота_Пошлина": has_prior_lgota,
            "Признаки_Спора": False,
        }
        re_entry = screen_single(rec_for_screen, control_for_screen, present)
        combined_findings: List[GroundFinding] = [
            f for f in re_entry.findings if f.rule in ("cat", "limit", "duty")
        ]
        existing_keys = {(f.rule, f.ref, f.text) for f in combined_findings}
        for pf in prior_findings:
            if (pf.rule, pf.ref, pf.text) not in existing_keys:
                combined_findings.append(pf)
        re_entry.findings = combined_findings
        _finalize_verdict(re_entry)
        patch["Пошлина_расчет"] = re_entry.duty_required
        patch["Вердикт"] = re_entry.verdict
        patch["Основания"] = "; ".join(
            f"{f.ref}: {f.text}" for f in re_entry.findings
            if f.kind in ("return", "refuse", "manual")
        )
        update_claim_rows([self.row.get("ID") or ""], patch)
        app_log(f"РЕЕСТР: заявка {self.row.get('ID')} исправлена вручную")
        self.saved = True
        self._remember_dialog_view()
        if hasattr(self.master, "_save_window_state"):
            self.master._save_window_state()
        self.destroy()


class AmirsConverterApp(tk.Tk):
    """Главное окно: 5 вкладок по ходу работы + нижняя строка состояния."""

    _EXPANDED_HEIGHT = 760  # высота окна при развёрнутых уточнениях экспресс-формы

    def __init__(self):
        super().__init__()
        self.title(f"Помощник мирового судьи — ПИ «АМИРС» | версия {APP_VERSION}")
        self.geometry("920x700")
        self.minsize(880, 620)
        self.configure(bg="#F5F5F7")

        # Палитра Apple Human Interface Guidelines (macOS Sequoia / iOS)
        self.PRIMARY_BLUE = "#1D1D1F"
        self.ACCENT_BLUE = "#007AFF"
        self.ACCENT_HOVER = "#0062CC"
        self.ACCENT_ACTIVE = "#004999"
        self.GREEN_MAIN = "#34C759"
        self.GREEN_HOVER = "#2DB14E"
        self.GREEN_DARK = "#248A3D"
        self.RED_WARN = "#FF3B30"
        self.AMBER_WARN = "#FF9500"
        self.BG_WHITE = "#FFFFFF"
        self.BG_LIGHT = "#F2F2F7"
        self.BG_PAGE = "#F5F5F7"
        self.BORDER_SUBTLE = "#E5E5EA"
        self.TEXT_DARK = "#1D1D1F"
        self.TEXT_MUTED = "#86868B"

        self.selected_file = tk.StringVar()
        self.court_code_var = tk.StringVar(value=DEFAULT_COURT_CODE)
        self.strict_var = tk.BooleanVar(value=False)  # мягкий режим по умолчанию
        self.district_var = tk.StringVar()  # судебный район (справочник РК)
        self.section_var = tk.StringVar()   # судебный участок (справочник РК)
        self.judge_var = tk.StringVar()
        self.is_acting_var = tk.BooleanVar(value=False)  # режим «И.о. мирового судьи»
        self.acting_section_var = tk.StringVar()         # родной участок судьи-заместителя
        self.attach_dir_var = tk.StringVar()   # папка с приложениями к заявлениям
        self._attach_files: List[str] = []     # отдельные файлы-приложения (v3.6.1)
        self._manual_binds: Dict[str, Dict[str, object]] = {}   # ручная привязка (v3.7)
        self.attach_files_var = tk.StringVar() # сводка выбора отдельных файлов
        self.tesseract_path = ""               # путь к Tesseract OCR (необязательно)
        self.docs_preview_result = None
        self.docs_preview_running = False
        saved = load_app_settings()
        self._main_geometry = str(saved.get("window_geometry") or "")
        self._main_state = str(saved.get("window_state") or "normal")
        try:
            self._saved_tab_index = int(saved.get("active_tab", 0) or 0)
        except (TypeError, ValueError):
            self._saved_tab_index = 0
        self._saved_details_open = bool(saved.get("details_open", False))
        self._preview_geometry = str(saved.get("preview_geometry") or "")
        self._preview_state = str(saved.get("preview_state") or "normal")
        self._claim_dialog_geometry = str(saved.get("claim_dialog_geometry") or "")
        self._claim_dialog_state = str(saved.get("claim_dialog_state") or "normal")
        if saved:
            self.court_code_var.set(str(saved.get("court_code") or DEFAULT_COURT_CODE))
            self.strict_var.set(bool(saved.get("strict", False)))
            self.judge_var.set(str(saved.get("judge") or ""))
            self.attach_dir_var.set(str(saved.get("attachments_dir") or ""))
            self.tesseract_path = str(saved.get("ocr_models_path") or saved.get("tesseract_path") or "")
            district = str(saved.get("district") or "")
            section = str(saved.get("section") or "")
            if district in KOMI_DISTRICT_NAMES:
                self.district_var.set(district)
            matched = komi_match_section(section)
            if matched:
                self.section_var.set(matched)
            self.is_acting_var.set(bool(saved.get("is_acting", False)))
            acting_sec = komi_match_section(str(saved.get("acting_section") or ""))
            if acting_sec:
                self.acting_section_var.set(acting_sec)
        ensure_fees_config()  # файл шкалы пошлины — рядом с программой
        ensure_docs_config()  # профили обязательных документов — рядом с программой
        self.worker: Optional[threading.Thread] = None
        self.worker_result = None
        self.last_output_dir = ""

        self.create_widgets()
        self._restore_main_window_view()
        self.auto_detect_desktop_file()
        self.notebook.bind("<<NotebookTabChanged>>", lambda _e: self._save_window_state())
        self.bind("<Configure>", self._on_main_configure)
        self.protocol("WM_DELETE_WINDOW", self._on_app_close)

    # -- построение интерфейса ------------------------------------------------

    def _make_card(self, parent) -> tk.Frame:
        """Белая карточка с тонкой рамкой в стиле Apple Settings."""
        card = tk.Frame(parent, bg=self.BG_WHITE, bd=0, relief="flat",
                        highlightthickness=1, highlightbackground="#E5E5EA",
                        highlightcolor="#E5E5EA")
        card.pack(fill="both", expand=True, padx=4, pady=6)
        body = tk.Frame(card, bg=self.BG_WHITE)
        body.pack(fill="both", expand=True, padx=18, pady=14)
        return body

    def _flat_btn(self, parent, text, command, kind="secondary",
                  font_size=9, padx=14, pady=7, radius=9, anchor="center"):
        """Скругленная кнопка Apple-стиля, срабатывающая при клике в любую точку."""
        styles = {
            "primary":   ("#007AFF", "#0062CC", "#004999", "#FFFFFF"),
            "success":   ("#34C759", "#2DB14E", "#248A3D", "#FFFFFF"),
            "secondary": ("#F2F2F7", "#E5E5EA", "#D1D1D6", "#007AFF"),
            "danger":    ("#FFF2F2", "#FFE5E5", "#FFD1D1", "#FF3B30"),
        }
        bg, hover, active, fg = styles.get(kind, styles["secondary"])
        return AppleButton(
            parent, text=text, command=command,
            bg=bg, fg=fg, hover_bg=hover, active_bg=active,
            font=("Segoe UI", font_size, "bold"),
            radius=radius, padx=padx, pady=pady, anchor=anchor
        )

    def _field_label(self, parent, text):
        return tk.Label(parent, text=text, font=("Segoe UI", 9),
                        fg=self.TEXT_MUTED, bg=self.BG_WHITE)

    def create_widgets(self):
        # Шапка в стиле macOS Header Bar --------------------------------------
        header = tk.Frame(self, bg="#FFFFFF", height=58, highlightthickness=1,
                          highlightbackground="#E5E5EA")
        header.pack(fill="x", side="top")
        header.pack_propagate(False)

        head_left = tk.Frame(header, bg="#FFFFFF")
        head_left.pack(side="left", padx=20)
        tk.Label(head_left, text="Помощник мирового судьи · ПИ «АМИРС»",
                 font=("Segoe UI", 13, "bold"), fg="#1D1D1F",
                 bg="#FFFFFF").pack(anchor="w", pady=(8, 0))
        tk.Label(head_left,
                 text="реестры → XML · документы Word · скрининг ст. 125 · накопительный реестр",
                 font=("Segoe UI", 8), fg="#86868B",
                 bg="#FFFFFF").pack(anchor="w")
        badge = tk.Label(header, text=f" v{APP_VERSION} ", font=("Segoe UI", 9, "bold"),
                         fg="#007AFF", bg="#EBF3FE", padx=10, pady=3)
        badge.pack(side="right", padx=18)

        # Вкладки в стиле Segmented Control (macOS) ----------------------------
        style = ttk.Style(self)
        try:
            style.theme_use("clam")
        except Exception:
            pass
        style.configure("Amirs.TNotebook", background="#F5F5F7", borderwidth=0,
                        tabmargins=(8, 8, 8, 0))
        style.configure("Amirs.TNotebook.Tab", font=("Segoe UI", 10, "bold"),
                        padding=(14, 7), background="#E5E5EA",
                        foreground="#515154", borderwidth=0)
        style.map("Amirs.TNotebook.Tab",
                  background=[("selected", "#007AFF"), ("active", "#D1D1D6")],
                  foreground=[("selected", "#FFFFFF"), ("active", "#1D1D1F")])
        try:
            import tkinter.font as tkfont
            row_f = tkfont.Font(root=self, family="Segoe UI", size=9)
            line_px = max(int(row_f.metrics("linespace")), 18)
        except Exception:
            line_px = 20
        style.configure("Treeview", font=("Segoe UI", 9),
                        rowheight=max(line_px + 10, 28),
                        background="#FFFFFF", fieldbackground="#FFFFFF",
                        foreground=self.TEXT_DARK, borderwidth=0)
        style.configure("Treeview.Heading", font=("Segoe UI", 9, "bold"),
                        background="#F5F5F7", foreground="#1D1D1F",
                        relief="flat", padding=(6, 5))
        style.map("Treeview.Heading",
                  background=[("active", "#E5E5EA")])
        style.map("Treeview",
                  background=[("selected", "#EBF3FE")],
                  foreground=[("selected", "#007AFF")])
        style.configure("TCombobox", padding=4, relief="flat")

        self.notebook = ttk.Notebook(self, style="Amirs.TNotebook")
        self.notebook.pack(fill="both", expand=True, padx=12, pady=(4, 0))

        tab_convert = tk.Frame(self.notebook, bg="#F5F5F7")
        tab_screen = tk.Frame(self.notebook, bg="#F5F5F7")
        tab_express = tk.Frame(self.notebook, bg="#F5F5F7")
        tab_registry = tk.Frame(self.notebook, bg="#F5F5F7")
        tab_stats = tk.Frame(self.notebook, bg="#F5F5F7")
        self.notebook.add(tab_convert, text=" 1. Реестр → АМИРС ")
        self.notebook.add(tab_screen, text=" 2. Скрининг ст. 125 ")
        self.notebook.add(tab_express, text=" 3. Экспресс-заявление ")
        self.notebook.add(tab_registry, text=" 4. Накопительный реестр ")
        self.notebook.add(tab_stats, text=" 5. Статистика ")

        # --- вкладка 1: реестр → АМИРС и документы -----------------------------
        body = self._make_card(tab_convert)

        tk.Label(body, text="Шаг 1 · файл реестра должников (Excel .xlsx):",
                 font=("Segoe UI", 10, "bold"), fg=self.PRIMARY_BLUE,
                 bg=self.BG_WHITE).pack(anchor="w", pady=(0, 4))
        row_file = tk.Frame(body, bg=self.BG_WHITE)
        row_file.pack(fill="x")
        self.file_entry = tk.Entry(row_file, textvariable=self.selected_file,
                                   font=("Segoe UI", 10), bg="#F5F5F7",
                                   fg=self.TEXT_DARK, relief="solid", bd=1)
        self.file_entry.pack(side="left", fill="x", expand=True, ipady=6, padx=(0, 8))
        ModernTooltip(self.file_entry,
                      "Путь к реестру должников (.xlsx). Можно выбрать сразу "
                      "несколько файлов — они обработаются по очереди.")
        browse_btn = self._flat_btn(row_file, "Обзор…", self.browse_files, "primary")
        browse_btn.pack(side="left", ipady=5, padx=(0, 8))
        ModernTooltip(browse_btn,
                      "Выберите один или несколько файлов реестров (Ctrl/Shift)")
        template_btn = self._flat_btn(row_file, "Шаблон для взыскателя",
                                      self.save_template)
        template_btn.pack(side="left", ipady=5)
        ModernTooltip(template_btn,
                      "Эталонный .xlsx с примером заполнения и инструкцией — "
                      "передавайте взыскателям, чтобы реестры приходили правильными.")

        strict_cb = tk.Checkbutton(
            body,
            text="Строгий контроль СНИЛС/ИНН (обычно выключен: номера с ошибкой "
                 "контрольной суммы попадают в пакет, список — в warnings_log.csv)",
            variable=self.strict_var, font=("Segoe UI", 8), fg=self.TEXT_MUTED,
            bg=self.BG_WHITE, anchor="w", cursor="hand2")
        strict_cb.pack(anchor="w", pady=(6, 0))

        tk.Label(body, text="Шаг 2 · реквизиты участка (запоминаются автоматически):",
                 font=("Segoe UI", 10, "bold"), fg=self.PRIMARY_BLUE,
                 bg=self.BG_WHITE).pack(anchor="w", pady=(12, 4))
        grid = tk.Frame(body, bg=self.BG_WHITE)
        grid.pack(fill="x")
        grid.columnconfigure(1, weight=0)
        grid.columnconfigure(3, weight=1)

        self._field_label(grid, "Код участка").grid(row=0, column=0, sticky="w",
                                                    padx=(0, 4), pady=2)
        court_entry = tk.Entry(grid, textvariable=self.court_code_var, width=13,
                               font=("Segoe UI", 10, "bold"), bg="#F5F5F7",
                               fg=self.PRIMARY_BLUE, relief="solid", bd=1)
        court_entry.grid(row=0, column=1, sticky="w", ipady=3)
        ModernTooltip(court_entry,
                      "Код участка в классификаторе АМИРС (формат 11MS001)")
        self._field_label(grid, "Судья (ФИО)").grid(row=0, column=2, sticky="w",
                                                    padx=(16, 4), pady=2)
        judge_entry = tk.Entry(grid, textvariable=self.judge_var,
                               font=("Segoe UI", 10), bg="#F5F5F7",
                               fg=self.TEXT_DARK, relief="solid", bd=1)
        judge_entry.grid(row=0, column=3, sticky="we", ipady=3)
        ModernTooltip(judge_entry,
                      "Фамилия и инициалы судьи; пусто — будет линия для вписывания")

        self._field_label(grid, "Суд. район").grid(row=1, column=0, sticky="w",
                                                   padx=(0, 4), pady=2)
        self.district_cb = ttk.Combobox(grid, textvariable=self.district_var,
                                        values=KOMI_DISTRICT_NAMES, state="readonly",
                                        width=24, font=("Segoe UI", 9))
        self.district_cb.grid(row=1, column=1, sticky="w", ipady=2)
        self.district_cb.bind("<<ComboboxSelected>>", self._on_district_changed)
        ModernTooltip(self.district_cb,
                      "Судебный район Республики Коми (всего 17). Район не попадает "
                      "в XML — нужен только для выбора участка.")
        self._field_label(grid, "Суд. участок").grid(row=1, column=2, sticky="w",
                                                     padx=(16, 4), pady=2)
        self.section_cb = ttk.Combobox(
            grid, textvariable=self.section_var,
            values=self._sections_of_district(self.district_var.get()),
            state="readonly", font=("Segoe UI", 9))
        self.section_cb.grid(row=1, column=3, sticky="we", ipady=2)
        ModernTooltip(self.section_cb,
                      "Официальное наименование участка (справочник 60 участков РК) — "
                      "попадёт в шапки приказов, определений и извещений.")

        self.acting_cb = tk.Checkbutton(
            grid,
            text="И.о. мирового судьи (отпуск / отсутствие)",
            variable=self.is_acting_var,
            command=self._on_acting_toggled,
            font=("Segoe UI", 9), fg=self.PRIMARY_BLUE,
            bg=self.BG_WHITE, anchor="w", cursor="hand2"
        )
        self.acting_cb.grid(row=2, column=0, columnspan=2, sticky="w", pady=(4, 2))
        ModernTooltip(
            self.acting_cb,
            "Включите, если обязанности мирового судьи этого участка временно "
            "исполняет мировой судья другого судебного участка (ч. 3 ст. 8 ФЗ № 188-ФЗ)."
        )
        self.acting_sec_lbl = self._field_label(grid, "Осн. участок и.о.")
        self.acting_sec_lbl.grid(row=2, column=2, sticky="w", padx=(16, 4), pady=(4, 2))
        self.acting_section_cb = ttk.Combobox(
            grid, textvariable=self.acting_section_var,
            values=[""] + list(KOMI_SECTION_NAMES),
            state="readonly" if self.is_acting_var.get() else "disabled",
            font=("Segoe UI", 9)
        )
        self.acting_section_cb.grid(row=2, column=3, sticky="we", ipady=2, pady=(4, 2))
        ModernTooltip(
            self.acting_section_cb,
            "Основной судебный участок мирового судьи, на которого возложено "
            "исполнение обязанностей (например: Куратовский судебный участок г. Сыктывкара)."
        )

        tk.Label(body, text="Шаг 3 · обработка выбранного реестра:",
                 font=("Segoe UI", 10, "bold"), fg=self.PRIMARY_BLUE,
                 bg=self.BG_WHITE).pack(anchor="w", pady=(12, 4))
        btn_row = tk.Frame(body, bg=self.BG_WHITE)
        btn_row.pack(fill="x")
        self.convert_btn = self._flat_btn(btn_row, BTN_TEXT, self.run_conversion,
                                          "success", font_size=11, padx=18, pady=10, radius=11)
        self.convert_btn.pack(side="left", fill="x", expand=True, padx=(0, 8))
        ModernTooltip(self.convert_btn,
                      "Проверка реестра по ст. 124 ГПК РФ и выгрузка XML-пакета для АМИРС")
        self.docs_btn = self._flat_btn(btn_row, BTN_DOCS_TEXT, self.run_documents,
                                       "primary", font_size=11, padx=18, pady=10, radius=11)
        self.docs_btn.pack(side="left", fill="x", expand=True)
        ModernTooltip(self.docs_btn,
                      "Из того же реестра: проекты судебных приказов, проекты определений "
                      "об отмене, извещения взыскателю, конверты-ярлыки и почтовый реестр — "
                      "готовые документы Word в папке «Пакет_документов_…».")

        log_head = tk.Frame(body, bg=self.BG_WHITE)
        log_head.pack(fill="x", pady=(10, 3))
        tk.Label(log_head, text="Протокол:", font=("Segoe UI", 9, "bold"),
                 fg=self.TEXT_MUTED, bg=self.BG_WHITE).pack(side="left")
        log_wrap = tk.Frame(body, bg=self.BG_WHITE)
        log_wrap.pack(fill="both", expand=True)
        self.log_text = tk.Text(log_wrap, font=("Consolas", 9), bg="#1C1C1E",
                                fg="#F5F5F7", relief="flat", bd=0, height=7,
                                padx=12, pady=8, state="normal")
        scrollbar = ttk.Scrollbar(log_wrap, orient="vertical", command=self.log_text.yview)
        self.log_text.configure(yscrollcommand=scrollbar.set)
        scrollbar.pack(side="right", fill="y")
        self.log_text.pack(side="left", fill="both", expand=True)

        self._build_screen_tab(tab_screen)
        self._build_express_tab(tab_express)
        self._build_registry_tab(tab_registry)
        self._build_stats_tab(tab_stats)

        # Нижняя строка ---------------------------------------------------------
        footer = tk.Frame(self, bg=self.BG_LIGHT)
        footer.pack(fill="x", side="bottom")

        self.status_lbl = tk.Label(footer, text="Готов к работе.",
                                   font=("Segoe UI", 9), fg=self.PRIMARY_BLUE,
                                   bg=self.BG_LIGHT)
        self.status_lbl.pack(side="left", padx=16, pady=5)

        self.open_folder_btn = self._flat_btn(footer, "Открыть папку результата",
                                              self.open_output_folder, "primary")
        self.open_folder_btn.pack(side="right", padx=10, pady=3)
        self.open_folder_btn.config(state="disabled")

    # -- служебные методы -----------------------------------------------------

    @staticmethod
    def _sections_of_district(district: str) -> List[str]:
        """Список участков выбранного судебного района (или все 60)."""
        for name, sites in KOMI_JUDICIAL_DISTRICTS:
            if name == district:
                return list(sites)
        return list(KOMI_SECTION_NAMES)

    def _on_district_changed(self, event=None):
        """При смене района обновляет список участков и выбирает первый."""
        sites = self._sections_of_district(self.district_var.get())
        self.section_cb.config(values=sites)
        if self.section_var.get() not in sites:
            self.section_var.set(sites[0] if sites else "")

    def _on_acting_toggled(self):
        if hasattr(self, "acting_section_cb"):
            self.acting_section_cb.config(
                state="readonly" if self.is_acting_var.get() else "disabled"
            )
        self._save_window_state()

    def _make_doc_settings(self) -> DocSettings:
        return DocSettings(
            section=self.section_var.get(),
            judge=self.judge_var.get(),
            is_acting=bool(self.is_acting_var.get()),
            acting_section=self.acting_section_var.get() if self.is_acting_var.get() else "",
        )

    def _current_settings_payload(self) -> Dict[str, object]:
        """Реквизиты и вид окон для сохранения в amirs_settings.json."""
        active_tab = getattr(self, "_saved_tab_index", 0)
        if hasattr(self, "notebook"):
            try:
                active_tab = int(self.notebook.index(self.notebook.select()))
                self._saved_tab_index = active_tab
            except Exception:
                pass
        payload = {
            "court_code": self.court_code_var.get().strip().upper() or DEFAULT_COURT_CODE,
            "district": self.district_var.get(),
            "section": self.section_var.get(),
            "judge": self.judge_var.get().strip(),
            "is_acting": bool(self.is_acting_var.get()),
            "acting_section": self.acting_section_var.get().strip(),
            "strict": bool(self.strict_var.get()),
            "attachments_dir": (self.attach_dir_var.get().strip()
                                if hasattr(self, "attach_dir_var") else ""),
            "ocr_models_path": getattr(self, "tesseract_path", ""),
            "tesseract_path": getattr(self, "tesseract_path", ""),
            "window_geometry": getattr(self, "_main_geometry", ""),
            "window_state": getattr(self, "_main_state", "normal"),
            "active_tab": active_tab,
            "details_open": bool(getattr(self, "details_open", False)),
            "preview_geometry": getattr(self, "_preview_geometry", ""),
            "preview_state": getattr(self, "_preview_state", "normal"),
            "claim_dialog_geometry": getattr(self, "_claim_dialog_geometry", ""),
            "claim_dialog_state": getattr(self, "_claim_dialog_state", "normal"),
        }
        express = getattr(self, "express_vars", None)
        if express:
            try:  # последняя карточка экспресс-проверки — для предзаполнения
                payload["express_claimant"] = express["Взыскатель"].get().strip()
                payload["express_subject"] = express["Существо требования"].get().strip()
                payload["express_category"] = express["Категория (ст. 122)"].get().strip()
            except (KeyError, tk.TclError):
                pass
        return payload

    def center_on_screen(self):
        self.update_idletasks()
        width, height = self.winfo_width(), self.winfo_height()
        screen_w, screen_h = self.winfo_screenwidth(), self.winfo_screenheight()
        self.geometry(f"+{max((screen_w - width) // 2, 0)}+{max((screen_h - height) // 2, 0)}")

    def _restore_main_window_view(self):
        """Восстанавливает прежний размер, позицию, вкладку и состояние главного окна."""
        self.update_idletasks()
        if getattr(self, "_saved_details_open", False) and not getattr(self, "details_open", False):
            try:
                self._toggle_details()
            except Exception:
                pass
        if getattr(self, "_main_geometry", ""):
            try:
                self.geometry(self._main_geometry)
            except Exception:
                self.center_on_screen()
        else:
            self.center_on_screen()
        if getattr(self, "_main_state", "normal") == "zoomed":
            _set_win_zoomed(self, True)
        if hasattr(self, "notebook"):
            try:
                tabs_cnt = len(self.notebook.tabs())
                if 0 <= self._saved_tab_index < tabs_cnt:
                    self.notebook.select(self._saved_tab_index)
            except Exception:
                pass

    def _on_main_configure(self, event=None):
        if event is not None and event.widget is not self:
            return
        try:
            if _is_win_zoomed(self):
                self._main_state = "zoomed"
            elif self.state() == "normal":
                self._main_state = "normal"
                self._main_geometry = self.geometry()
        except Exception:
            pass

    def _save_window_state(self):
        try:
            self._on_main_configure()
            save_app_settings(self._current_settings_payload())
        except Exception:
            pass

    def _on_app_close(self):
        self._save_window_state()
        cleanup_ocr_temp_files()
        self.destroy()

    def auto_detect_desktop_file(self):
        """Подставляет свежий .xlsx с Рабочего стола (в т.ч. OneDrive-рабочего)."""
        home = os.path.expanduser("~")
        folders = [os.path.join(home, name) for name in
                   ("Desktop", os.path.join("OneDrive", "Desktop"), "Рабочий стол")]
        files: List[str] = []
        for folder in folders:
            if os.path.isdir(folder):
                files.extend(glob.glob(os.path.join(folder, "*.xlsx")))
        valid = [f for f in files if not os.path.basename(f).startswith("~$")]
        if valid:
            try:
                latest = max(valid, key=os.path.getmtime)
            except OSError:
                return
            self.selected_file.set(latest)
            self.log(f"[ИНФО] На рабочем столе найден свежий файл: {os.path.basename(latest)}"
                     f" (можно заменить кнопкой «Обзор...»)")
        else:
            self.log("[ИНФО] Выберите файл реестра кнопкой «Обзор...».")

    def browse_files(self):
        chosen = filedialog.askopenfilenames(
            title="Выберите Excel-файлы реестра должников (можно несколько)",
            filetypes=[("Файлы Excel (*.xlsx, *.xlsm)", "*.xlsx *.xlsm"), ("Все файлы", "*.*")],
            parent=self,
        )
        if chosen:
            self.selected_file.set("; ".join(chosen))
            if len(chosen) == 1:
                self.log(f"[ВЫБОР] Выбран файл: {chosen[0]}")
            else:
                self.log(f"[ВЫБОР] Выбрано файлов: {len(chosen)} (пакетная обработка)")

    def _selected_paths(self) -> List[str]:
        """Разбирает строку выбора на существующие файлы (можно несколько)."""
        raw_paths = self.selected_file.get().strip().strip('"')
        paths = [p.strip().strip('"') for p in raw_paths.split(";") if p.strip()]
        return [p for p in paths if os.path.isfile(p)]

    def save_template(self):
        """Создаёт эталонный шаблон реестра по пути, выбранному сотрудником."""
        chosen = filedialog.asksaveasfilename(
            title="Сохранить эталонный шаблон реестра",
            defaultextension=".xlsx",
            initialfile=TEMPLATE_DEFAULT_NAME,
            filetypes=[("Файлы Excel (*.xlsx)", "*.xlsx")],
            parent=self,
        )
        if not chosen:
            return
        try:
            make_template(chosen)
        except ConversionError as exc:
            messagebox.showerror("Не удалось создать шаблон", str(exc), parent=self)
            return
        self.log(f"[ШАБЛОН] Создан эталонный шаблон реестра: {chosen}")
        messagebox.showinfo(
            "Шаблон создан",
            "Эталонный шаблон реестра создан:\n" + chosen
            + "\n\nПередайте его взыскателям: на листе «Реестр» есть пример "
              "заполнения, на листе «Инструкция» — правила по ст. 124 ГПК РФ.",
            parent=self,
        )

    def open_output_folder(self):
        folder = self.last_output_dir
        if not folder or not os.path.isdir(folder):
            return
        try:
            if hasattr(os, "startfile"):
                os.startfile(folder)  # Windows
            else:
                subprocess.Popen(["xdg-open", folder])
        except Exception as exc:
            messagebox.showwarning("Не удалось открыть папку", str(exc), parent=self)

    def log(self, message: str):
        self.log_text.insert("end", message + "\n")
        self.log_text.see("end")

    # -- конвертация в фоновом потоке ------------------------------------------

    def run_conversion(self):
        if self.worker is not None and self.worker.is_alive():
            return  # предыдущая обработка ещё идет

        paths = self._selected_paths()
        if not paths:
            messagebox.showwarning(
                "Внимание",
                "Пожалуйста, укажите существующий Excel-файл (.xlsx).",
                parent=self,
            )
            return

        court_code = self.court_code_var.get().strip().upper() or DEFAULT_COURT_CODE
        save_app_settings(self._current_settings_payload())
        self.log("=" * 62)
        if len(paths) == 1:
            self.log(f"[{datetime.now().strftime('%H:%M:%S')}] Запуск конвертации: "
                     f"{os.path.basename(paths[0])}")
        else:
            self.log(f"[{datetime.now().strftime('%H:%M:%S')}] Пакетная обработка: "
                     f"{len(paths)} файлов, код участка {court_code}")
        self.status_lbl.config(text="Идет обработка файла, пожалуйста, подождите...")
        self.convert_btn.config(state="disabled", text="  ОБРАБОТКА...  ")
        self.docs_btn.config(state="disabled", text="  ОБРАБОТКА...  ")
        self.screen_btn.config(state="disabled")
        self.attach_check_btn.config(state="disabled")
        self.open_folder_btn.config(state="disabled")
        self.worker_result = None

        self.worker = threading.Thread(
            target=self._conversion_worker, args=(paths, court_code, bool(self.strict_var.get())),
            daemon=True
        )
        self.worker.start()
        self.after(100, self._poll_worker)

    def _conversion_worker(self, paths: List[str], court_code: str, strict_ids: bool):
        try:
            if len(paths) == 1:
                self.worker_result = ("ok", process_registry(paths[0], court_code, strict_ids=strict_ids))
            else:
                self.worker_result = ("batch", process_batch(paths, court_code, strict_ids=strict_ids))
        except ConversionError as exc:
            self.worker_result = ("error", str(exc))
        except Exception as exc:  # непредвиденное — показываем, но не падаем
            self.worker_result = ("crash", f"{type(exc).__name__}: {exc}")

    def _poll_worker(self):
        if self.worker is not None and self.worker.is_alive():
            self.after(100, self._poll_worker)
            return

        self.convert_btn.config(state="normal", text=BTN_TEXT)
        self.docs_btn.config(state="normal", text=BTN_DOCS_TEXT)
        self.screen_btn.config(state="normal")
        self.attach_check_btn.config(state="normal", text=" ПРОВЕРИТЬ ПРИЛОЖЕНИЯ ")
        kind, payload = self.worker_result or ("crash", "Неизвестная ошибка")

        if kind == "ok":
            self._show_result(payload)
        elif kind == "batch":
            self._show_batch_result(payload)
        elif kind == "docs":
            self._show_docs_result(payload)
        elif kind == "screen":
            self._show_screening_result(payload)
        else:
            self.log(f"[{'ОШИБКА' if kind == 'error' else 'КРИТИЧЕСКИЙ СБОЙ'}] {payload}")
            self.status_lbl.config(text="Ошибка обработки.")
            title = "Ошибка конвертации" if kind == "error" else "Сбой программы"
            messagebox.showerror(title, str(payload), parent=self)

    def _show_batch_result(self, batch: BatchResult):
        """Сводный протокол пакетной обработки."""
        for entry in batch.entries:
            name = os.path.basename(entry.path)
            if entry.status == "ok" and entry.result:
                res = entry.result
                self.log(f"[OK] {name}: принято {res.success_count}, отклонено {len(res.rejected)}"
                         + (f", дубли {res.duplicate_count}" if res.duplicate_count else ""))
                for warning in res.warnings:
                    self.log(f"      ВНИМАНИЕ: {warning}")
                if res.rejected:
                    self.log(f"      Файл ошибок: {os.path.basename(res.log_path)}")
            else:
                label = "ОШИБКА" if entry.status == "error" else "СБОЙ"
                self.log(f"[{label}] {name}: {entry.message}")
        self.log("=" * 62)
        self.log(f"[ИТОГО] Файлов обработано: {len(batch.entries)} | "
                 f"успешно: {batch.ok_count} | с ошибками: {batch.fail_count} | "
                 f"принято записей: {batch.total_accepted} | "
                 f"отклонено: {batch.total_rejected} | "
                 f"время: {batch.duration_sec} с")

        self.status_lbl.config(
            text=f"Пакетная обработка завершена: успешно {batch.ok_count} из {len(batch.entries)}, "
                 f"принято {batch.total_accepted} записей."
        )
        for entry in batch.entries:
            if entry.result and entry.result.xml_path:
                self.last_output_dir = os.path.dirname(entry.result.xml_path)
                break
        else:
            self.last_output_dir = ""
        if self.last_output_dir:
            self.open_folder_btn.config(state="normal")

        failed = [e for e in batch.entries if e.status != "ok"]
        message = (
            f"Пакетная обработка завершена.\n\n"
            f"• Файлов обработано: {len(batch.entries)}\n"
            f"• Успешно: {batch.ok_count} (принято {batch.total_accepted} записей)\n"
            f"• С ошибками: {batch.fail_count}"
        )
        if failed:
            message += "\n\nНе удалось обработать:\n" + "\n".join(
                f"• {os.path.basename(e.path)}" for e in failed
            )
        messagebox.showinfo(
            "Пакетная обработка завершена" if batch.ok_count else "Обработка завершена с ошибками",
            message,
            parent=self,
        )

    def _show_result(self, res: RegistryResult):
        for warning in res.warnings:
            self.log(f"[ВНИМАНИЕ] {warning}")
        if res.skipped_empty:
            self.log(f"[ИНФО] Пропущено пустых строк: {res.skipped_empty}")
        self.log(f"[УСПЕХ] Включено в XML-пакет: {res.success_count} дел "
                 f"(всего строк с данными: {res.total_rows})")
        if res.rejected:
            self.log(f"[БРАК] Отклонено при проверке: {len(res.rejected)} записей.")
            self.log(f"[ФАЙЛ ОШИБОК] Создан: {os.path.basename(res.log_path)}")
        if res.warning_count:
            self.log(f"[ВНИМАНИЕ] Предупреждений по контрольным суммам СНИЛС/ИНН: {res.warning_count} "
                     f"(список: {os.path.basename(res.warnings_log_path)})")
        if res.duplicate_count:
            self.log(f"[ВНИМАНИЕ] Возможных дубликатов записей: {res.duplicate_count} "
                     f"(список: {os.path.basename(res.warnings_log_path)})")
        if res.journal_path:
            self.log(f"[ЖУРНАЛ] Итог дописан в журнал обработок: {os.path.basename(res.journal_path)}")
        self.log(f"[ГОТОВО] Сформирован XML-пакет: {res.xml_path}")
        self.log("=" * 62)

        self.status_lbl.config(
            text=f"Завершено успешно! Включено {res.success_count} позиций "
                 f"(отклонено: {len(res.rejected)})."
        )
        self.last_output_dir = os.path.dirname(res.xml_path)
        self.open_folder_btn.config(state="normal")

        message = (
            f"Конвертация успешно завершена!\n\n"
            f"• Включено в XML-пакет: {res.success_count} дел\n"
            f"• Отклонено при проверке: {len(res.rejected)} записей"
        )
        if res.warning_count:
            message += f"\n• Предупреждений по СНИЛС/ИНН: {res.warning_count}"
        if res.duplicate_count:
            message += f"\n• Возможных дубликатов: {res.duplicate_count}"
        message += f"\n\nФайл пакета:\n{res.xml_path}"
        if res.rejected:
            message += f"\n\nФайл ошибок:\n{res.log_path}"
        if res.warning_count or res.duplicate_count:
            message += f"\nФайл предупреждений:\n{res.warnings_log_path}"
        if res.journal_path:
            message += f"\nЖурнал обработок:\n{res.journal_path}"
        messagebox.showinfo("Конвертация завершена", message, parent=self)

    # -- пакет документов (DOCX) в фоновом потоке -------------------------------

    def run_documents(self):
        if self.worker is not None and self.worker.is_alive():
            return  # предыдущая обработка ещё идет

        paths = self._selected_paths()
        if not paths:
            messagebox.showwarning(
                "Внимание",
                "Пожалуйста, укажите существующий Excel-файл (.xlsx).",
                parent=self,
            )
            return

        settings = self._make_doc_settings()
        save_app_settings(self._current_settings_payload())
        self.log("=" * 62)
        self.log(f"[{datetime.now().strftime('%H:%M:%S')}] Формирование пакета "
                 f"документов: {len(paths)} реестр(ов), участок: "
                 f"{settings.section or 'не выбран (укажите район и участок!)'}")
        self.status_lbl.config(text="Формируются документы, пожалуйста, подождите...")
        self.convert_btn.config(state="disabled", text="  ОБРАБОТКА...  ")
        self.docs_btn.config(state="disabled", text="  ОБРАБОТКА...  ")
        self.screen_btn.config(state="disabled")
        self.attach_check_btn.config(state="disabled")
        self.open_folder_btn.config(state="disabled")
        self.worker_result = None

        self.worker = threading.Thread(
            target=self._docs_worker,
            args=(paths, settings, bool(self.strict_var.get())),
            daemon=True,
        )
        self.worker.start()
        self.after(100, self._poll_worker)

    def _docs_worker(self, paths: List[str], settings: DocSettings, strict_ids: bool):
        results = []
        errors = []
        for path in paths:
            try:
                results.append(generate_document_package(path, settings, strict_ids=strict_ids))
            except ConversionError as exc:
                errors.append((path, str(exc)))
            except Exception as exc:  # непредвиденное — фиксируем и идём дальше
                errors.append((path, f"{type(exc).__name__}: {exc}"))
        self.worker_result = ("docs", (results, errors))

    def _show_docs_result(self, payload):
        results, errors = payload
        for res in results:
            self.log(f"[ДОКУМЕНТЫ] {os.path.basename(res.folder)}: "
                     f"должников {res.debtors}")
            for file_path in res.files:
                self.log(f"      • {os.path.basename(file_path)}")
            if res.rejected:
                self.log(f"      Строк с ошибками: {res.rejected} "
                         f"(error_log.csv в папке пакета)")
            if res.warning_count:
                self.log(f"      Предупреждений: {res.warning_count} "
                         f"(warnings_log.csv в папке пакета)")
        for path, message in errors:
            self.log(f"[ОШИБКА] {os.path.basename(path)}: {message}")
        self.log("=" * 62)

        if results:
            self.last_output_dir = results[0].folder
            self.open_folder_btn.config(state="normal")
        self.status_lbl.config(
            text=f"Пакет документов готов: {len(results)} из "
                 f"{len(results) + len(errors)} реестров."
        )

        message = f"Пакеты документов сформированы: {len(results)}"
        for res in results:
            message += f"\n\nПапка «{os.path.basename(res.folder)}» — должников: {res.debtors}\n"
            message += "\n".join(f"• {os.path.basename(f)}" for f in res.files)
        if errors:
            message += "\n\nНе удалось обработать:\n" + "\n".join(
                f"• {os.path.basename(p)}" for p, _ in errors
            )
        messagebox.showinfo(
            "Пакет документов" if results else "Пакет документов не сформирован",
            message,
            parent=self,
        )

